window.QUESTIONS = [

/* ---------- I. Sounds & Spelling ---------- */

{s:"The alphabet and stress", q:"How is the letter [[W]] named in German?", a:["weh","doppel-u","weh-weh","vau"], t:"recall", c:0, e:"[[W]] is named [[weh]] and sounds like an English v."},
{s:"The alphabet and stress", q:"Where does the stress fall in [[aufstehen]]?", a:["on the prefix: **auf**stehen","on the stem: auf**ste**hen","on the last syllable","it varies"], t:"rule", c:0, e:"A separable prefix is stressed, which is exactly why it can detach."},
{s:"The alphabet and stress", q:"Where does the stress fall in [[verstehen]]?", a:["on the stem: ver**ste**hen","on the prefix: **ver**stehen","on the last syllable","evenly"], t:"rule", c:0, e:"Inseparable prefixes are unstressed and never detach."},
{s:"The alphabet and stress", q:"Which is true of [[ß]]?", a:["it never begins a word","it is pronounced like z","it only appears in names","it is always doubled"], t:"rule", c:0, e:"[[ß]] is a sharp s and is written [[ss]] in Switzerland."},
{s:"The alphabet and stress", q:"Which letter completes [[Stra___e]] (street)?", a:["ß","s","z","sch"], t:"gap", c:0, e:"A sharp s after a long vowel is written [[ß]]: [[Straße]]."},
{s:"The alphabet and stress", q:"What is the German name of the letter [[Y]]?", a:["üpsilon","jott","iks","tsett"], t:"recall", c:0, e:"[[Y]] is [[üpsilon]]; [[jott]] is [[J]], [[iks]] is [[X]] and [[tsett]] is [[Z]]."},
{s:"The alphabet and stress", q:"Where do words beginning with [[ä]], [[ö]] and [[ü]] appear in a German dictionary?", a:["Filed as though they were plain [[a]], [[o]] and [[u]]","At the very end, after [[z]]","Immediately after [[z]], in umlaut order","Before [[a]], as separate first letters"], t:"recall", c:0, e:"The umlaut is treated as a mark on the vowel, not as a new letter — unlike [[ß]], which is sorted as [[ss]]."},
{s:"The alphabet and stress", q:"Where does the stress fall in [[studieren]]?", a:["On [[-die-]], because verbs in [[-ieren]] stress that syllable","On [[stu-]], the first syllable","On the final [[-ren]]","It has no fixed stress"], t:"rule", c:0, e:"Every [[-ieren]] verb behaves the same way, so [[telefonieren]] and [[probieren]] are stressed on the same syllable."},
{s:"The alphabet and stress", q:"Loanwords such as [[Universität]] and [[Nation]] are stressed…", a:["near the end of the word","on the first syllable","on the prefix","evenly across every syllable"], t:"rule", c:0, e:"Native German words go the other way and take the stress on the first syllable: [[Arbeit]], [[Kinder]]."},
{s:"The alphabet and stress", q:"[[übersetzen]] can mean **to ferry across** or **to translate**. What tells the two apart?", a:["Which syllable carries the stress","The gender of the object","The auxiliary used in the Perfekt","Nothing — only the context"], t:"rule", c:0, e:"Stressing the prefix gives the separable verb **to ferry across**; stressing the stem gives the inseparable verb **to translate**."},
{s:"The alphabet and stress", q:"[[Ich muss morgen um sechs Uhr ___.]] (get up)", a:["aufstehen","ankommen","verstehen","bezahlen"], t:"gap", c:0, e:"[[aufstehen]] carries a separable prefix, and a separable prefix always takes the stress: [[auf-]]stehen."},
{s:"The alphabet and stress", q:"[[Herr Ober, ich möchte bitte ___.]] (pay)", a:["bezahlen","aufstehen","ankommen","übersetzen"], t:"gap", c:0, e:"[[be-]] is an inseparable prefix: it never separates and never takes the stress, which sits on the stem [[-zah-]]."},

{s:"Vowels", q:"How does [[ie]] sound, as in [[Liebe]]?", a:["like **ee** in see","like **eye**","like **oy** in boy","like **ay** in say"], t:"recall", c:0, e:"Each of [[ei]] and [[ie]] says the name of its second letter."},
{s:"Vowels", q:"How does [[ei]] sound, as in [[mein]]?", a:["like **eye**","like **ee** in see","like **ay** in say","like **ow** in how"], t:"recall", c:0, e:"[[ei]] sounds like the English letter I."},
{s:"Vowels", q:"How does [[eu]] sound, as in [[neu]]?", a:["like **oy** in boy","like **you**","like **ee**","like **eye**"], t:"recall", c:0, e:"[[eu]] and [[äu]] both sound like **oy**."},
{s:"Vowels", q:"In [[kommen]] the [[o]] is short. Why?", a:["a double consonant follows","it is unstressed","it is at the start","it is followed by n"], t:"rule", c:0, e:"A vowel is short before a double consonant and long before h or when doubled."},
{s:"Vowels", q:"Which vowel completes [[M___nner]] (men)?", a:["ä","a","e","ö"], t:"gap", c:0, e:"The plural of [[Mann]] takes an umlaut: [[Männer]]."},
{s:"Vowels", q:"Why is the vowel in [[Zahn]] long?", a:["An [[h]] after a vowel is silent and lengthens it","Because [[a]] is always long","Because the word ends in a consonant","Because the [[n]] is doubled"], t:"rule", c:0, e:"The same silent [[h]] stretches the vowel in [[Uhr]] and [[gehen]]."},
{s:"Vowels", q:"In which of these words is the vowel short?", a:["Kind","Brot","Boot","Uhr"], t:"rule", c:0, e:"A vowel before a consonant cluster is short ([[Kind]], [[Herbst]]); a single consonant, a doubled vowel or a following [[h]] all make it long."},
{s:"Vowels", q:"What is the quickest way to remember how [[ei]] and [[ie]] sound?", a:["Each says the name of its second letter","Each says the name of its first letter","Both are pronounced the same","The first letter of each pair is silent"], t:"rule", c:0, e:"So [[ei]] sounds like English **I** ([[mein]]) and [[ie]] like English **E** ([[Liebe]])."},
{s:"Vowels", q:"How does [[au]] sound in [[Haus]]?", a:["like **ow** in **how**","like **oy** in **boy**","like **aw** in **saw**","like **eye**"], t:"recall", c:0, e:"Put an umlaut on it and the sound changes completely: [[äu]] in [[Häuser]] is **oy** in **boy**."},
{s:"Vowels", q:"How is the [[ü]] of [[über]] produced?", a:["Say **ee** with the lips rounded","Say **oo** as in **boot**","Say **ur** as in **fur**","Say **you** as in English"], t:"recall", c:0, e:"[[ö]] is made the same way from a different starting point: **ur** in **fur** with the lips rounded."},
{s:"Vowels", q:"Which letters complete [[H___ser]] (houses)?", a:["äu","eu","au","ai"], t:"gap", c:0, e:"The plural umlauts the [[au]] of [[Haus]] into [[äu]] — spelled differently from [[eu]] but pronounced identically, **oy**."},
{s:"Vowels", q:"Which vowel completes [[sch___n]] (beautiful)?", a:["ö","o","ü","ä"], t:"gap", c:0, e:"[[ö]] is **ur** in **fur** with rounded lips; without the umlaut you get [[schon]], a different word meaning **already**."},

{s:"Consonants", q:"How is the [[ch]] in [[Buch]] pronounced?", a:["throaty, as in Scottish **loch**","soft, as in **huge**","like **k**","like **sh**"], t:"recall", c:0, e:"After a, o, u and au the [[ch]] is the rasping sound."},
{s:"Consonants", q:"How is the [[ch]] in [[ich]] pronounced?", a:["soft, as in **huge**","throaty, as in **loch**","like **k**","like **ch** in church"], t:"recall", c:0, e:"After any other vowel, including the umlauts, [[ch]] is soft."},
{s:"Consonants", q:"How does [[v]] sound in [[Vater]]?", a:["like English **f**","like English **v**","like **w**","it is silent"], t:"recall", c:0, e:"Native words have [[v]] as **f**; loanwords such as [[Vase]] keep the **v** sound."},
{s:"Consonants", q:"Why does [[Hund]] sound like **hunt**?", a:["final b, d and g harden","the u is short","the n is silent","it is a regional variant"], t:"rule", c:0, e:"The soft sound returns when an ending follows: [[Hunde]]."},
{s:"Consonants", q:"Which letters complete [[___ule]] (school)?", a:["Sch","Sh","Ch","Sk"], t:"gap", c:0, e:"[[sch]] is the German spelling of the **sh** sound."},
{s:"Consonants", q:"How does the [[st]] at the start of [[Stadt]] sound?", a:["like **sht**","like **st** in English **stop**","like **sd**","like **sh**, with no **t**"], t:"rule", c:0, e:"[[sp]] and [[st]] become **shp** and **sht** only at the beginning of a word; inside one, as in [[ist]], the plain **s** returns."},
{s:"Consonants", q:"After which vowels does [[ch]] take the throaty sound of [[Bach]]?", a:["After [[a]], [[o]], [[u]] and [[au]]","After [[ä]], [[ö]] and [[ü]]","After [[i]] and [[e]] only","After every vowel"], t:"rule", c:0, e:"Everything else — including all three umlauts — gives the soft [[ch]] of [[ich]], so [[Buch]] rasps but [[Bücher]] does not."},
{s:"Consonants", q:"How does [[w]] sound in [[Wasser]]?", a:["like English **v**","like English **w**","like English **f**","it is silent"], t:"recall", c:0, e:"German [[w]] is English **v** and German [[v]] is usually English **f**, so [[Vater]] and [[wo]] swap the sounds an English reader expects."},
{s:"Consonants", q:"How does [[z]] sound in [[Zeit]]?", a:["like **ts** in **cats**","like **z** in **zoo**","like **s** in **sun**","like **sh**"], t:"recall", c:0, e:"German [[z]] is always **ts**; the buzzing English **z** sound belongs instead to [[s]] before a vowel."},
{s:"Consonants", q:"How is the [[s]] of [[sagen]] pronounced?", a:["like English **z**","like the sharp **s** of [[Fuß]]","like **sh**","like **ts**"], t:"recall", c:0, e:"A single [[s]] before a vowel buzzes; [[ss]] and [[ß]] keep the sharp **s**, which is why [[Wasser]] and [[Sonne]] differ."},
{s:"Consonants", q:"Which letters complete [[___anne]] (frying pan)?", a:["Pf","F","Ph","P"], t:"gap", c:0, e:"In [[pf]] both letters are actually sounded — lips closed for the **p**, then straight into the **f**."},
{s:"Consonants", q:"Which letters complete [[___rechen]] (to speak)?", a:["sp","schp","shp","st"], t:"gap", c:0, e:"It is written [[sp]] but said **shp** at the start of a word; German never spells the [[sch]] out here."},

/* ---------- II. Pronouns ---------- */

{s:"Personal pronouns", q:"Which pronoun completes it? [[Kannst du ___ helfen?]] (help me)", a:["mir","mich","meiner","ich"], t:"gap", c:0, e:"[[helfen]] takes the dative, so 1st person singular is [[mir]]."},
{s:"Personal pronouns", q:"What is the accusative of [[er]]?", a:["ihn","ihm","seiner","er"], t:"recall", c:0, e:"[[er]] → [[ihn]] in the accusative, [[ihm]] in the dative."},
{s:"Personal pronouns", q:"[[Ich gebe ___ das Buch]] — I give it to them.", a:["ihnen","sie","ihr","ihren"], t:"gap", c:0, e:"Third person plural dative is [[ihnen]]. Capitalised [[Ihnen]] would be formal you."},
{s:"Personal pronouns", q:"Formal [[Sie]] takes which verb endings?", a:["always plural","always singular","singular for one person","the same as [[du]]"], t:"rule", c:0, e:"[[Sie sind]] whether you address one person or many."},
{s:"Personal pronouns", q:"What is the dative of [[du]]?", a:["dir","dich","deiner","du"], t:"recall", c:0, e:"[[dich]] is the accusative and [[dir]] the dative — the same split as [[mich]] and [[mir]]."},
{s:"Personal pronouns", q:"In [[Ich zeige ihr die Stadt]], what is [[ihr]]?", a:["the dative of [[sie]] — **to her**","the nominative [[ihr]] — **you** (plural)","the possessive **her** before a noun","the formal possessive **your**"], t:"rule", c:0, e:"Four different words are spelled [[ihr]]; a possessive would need a noun after it, as in [[ihr Hund]]."},
{s:"Personal pronouns", q:"[[Ich kenne ___ nicht.]] (him)", a:["ihn","ihm","er","ihnen"], t:"gap", c:0, e:"[[kennen]] takes a direct object, so [[er]] becomes accusative [[ihn]]; [[ihm]] would be needed after a dative verb such as [[helfen]]."},
{s:"Personal pronouns", q:"[[Ich schreibe ___ morgen eine E-Mail.]] (to you, formal)", a:["Ihnen","Sie","Ihrer","euch"], t:"gap", c:0, e:"Formal [[Sie]] keeps its shape in the accusative but turns into [[Ihnen]] in the dative — here the e-mail is the direct object and the person is the recipient."},
{s:"Personal pronouns", q:"[[Kommst du heute Abend mit ___?]] (with us)", a:["uns","wir","unser","euch"], t:"gap", c:0, e:"[[mit]] always takes the dative, and [[wir]] becomes [[uns]] in both the accusative and the dative."},
{s:"Personal pronouns", q:"Why do you rarely hear forms like [[meiner]] and [[seiner]]?", a:["The genitive pronouns are archaic; speech uses [[von]] + Dativ instead","They may only be used in writing","They were replaced by the accusative forms","They occur only in questions"], t:"rule", c:0, e:"They survive in a few fixed phrases such as [[Wir gedenken ihrer]], but [[ein Freund von mir]] is the everyday pattern."},
{s:"Personal pronouns", q:"What is the accusative of [[ihr]] (**you**, plural informal)?", a:["euch","ihr","euer","ihnen"], t:"recall", c:0, e:"[[ihr]] becomes [[euch]] in both the accusative and the dative; [[euer]] is the possessive, not a pronoun object."},
{s:"Personal pronouns", q:"[[Der Tisch steht neben der Lampe. Er ist neu.]] What is new?", a:["the table","the lamp","both","it cannot be told"], t:"rule", c:0, e:"[[er]] is masculine and [[Tisch]] is the only masculine noun available; [[Lampe]] would need [[sie]]."},
{s:"Personal pronouns", q:"[[Die Katze jagt den Vogel. Sie ist sehr schnell.]] What is fast?", a:["the cat","the bird","the chase","either — it is ambiguous"], t:"rule", c:0, e:"[[sie]] is feminine, and [[Vogel]] is masculine, so only [[die Katze]] can be meant. Gender does the work English does with word order."},
{s:"Personal pronouns", q:"[[Das Mädchen sucht seinen Hund. Es weint.]] Who is crying?", a:["the girl","the dog","the girl's mother","nobody in particular"], t:"rule", c:0, e:"[[Mädchen]] is grammatically neuter, so it takes [[es]] and [[sein]] even though the person is female."},
{s:"Personal pronouns", q:"[[Ich habe das Buch und die Zeitung. Sie ist alt.]] What is old?", a:["the newspaper","the book","both","the sentence is wrong"], t:"rule", c:0, e:"[[sie]] is also the plural pronoun, but the singular [[ist]] rules that out. [[Zeitung]] is feminine and [[Buch]] neuter, so a neuter reference would have been [[es ist alt]]."},

{s:"Reflexive pronouns", q:"[[Ich wasche ___ die Hände.]]", a:["mir","mich","meiner","sich"], t:"gap", c:0, e:"A direct object ([[die Hände]]) is already present, so the reflexive goes dative."},
{s:"Reflexive pronouns", q:"[[Wir freuen ___ auf den Sommer.]]", a:["uns","sich","unser","euch"], t:"gap", c:0, e:"1st person plural is [[uns]] in both accusative and dative."},
{s:"Reflexive pronouns", q:"Which persons have different accusative and dative reflexives?", a:["1st and 2nd singular only","all six persons","only the third person","only the plural"], t:"rule", c:0, e:"[[mich/mir]] and [[dich/dir]]. Everything else uses one form."},
{s:"Reflexive pronouns", q:"When does a reflexive verb take the dative reflexive rather than the accusative?", a:["When a direct object is already present in the sentence","When the subject is plural","When the verb has a separable prefix","When the sentence is negated"], t:"rule", c:0, e:"In [[Ich wasche mich]] the reflexive is the only object; add [[die Hände]] and the reflexive is pushed into the dative."},
{s:"Reflexive pronouns", q:"What is the accusative reflexive pronoun for [[du]]?", a:["dich","dir","sich","du"], t:"recall", c:0, e:"Only the first and second person singular tell the two cases apart — [[mich]]/[[mir]] and [[dich]]/[[dir]]. Everywhere else one form covers both."},
{s:"Reflexive pronouns", q:"[[Du musst ___ beeilen, der Zug fährt gleich.]]", a:["dich","dir","sich","du"], t:"gap", c:0, e:"[[sich beeilen]] has no other object, so the reflexive is the direct object and stands in the accusative."},
{s:"Reflexive pronouns", q:"[[Er interessiert ___ für alte Autos.]] (is interested in)", a:["sich","ihn","ihm","er"], t:"gap", c:0, e:"The third person uses [[sich]] in both cases; the ordinary pronoun [[ihn]] would make it somebody else who is interesting."},
{s:"Reflexive pronouns", q:"[[Ich kann ___ nicht an seinen Namen erinnern.]]", a:["mich","mir","sich","ich"], t:"gap", c:0, e:"[[sich erinnern]] parks its content in an [[an]] phrase, so the reflexive itself is the direct object — accusative [[mich]]."},
{s:"Reflexive pronouns", q:"Which reflexive pronoun goes with [[ihr]] (**you**, plural)?", a:["euch","ihr","sich","uns"], t:"recall", c:0, e:"[[euch]] serves as both accusative and dative: [[ihr setzt euch]] and [[ihr kauft euch ein Auto]]."},
{s:"Reflexive pronouns", q:"[[sich vorstellen]] in the sense **to imagine** takes which reflexive case?", a:["The dative — [[Ich stelle mir das vor]]","The accusative — [[Ich stelle mich das vor]]","The genitive","Either one, with no change of meaning"], t:"rule", c:0, e:"Switch to the accusative and the meaning switches too: [[ich stelle mich vor]] means **I introduce myself**."},

{s:"Relative pronouns", q:"[[Die Leute, mit ___ ich rede, sind nett.]]", a:["denen","die","der","deren"], t:"gap", c:0, e:"[[mit]] takes the dative, and the dative plural relative pronoun is [[denen]]."},
{s:"Relative pronouns", q:"[[Die Frau, ___ Auto neu ist, wohnt hier.]]", a:["deren","dessen","der","die"], t:"gap", c:0, e:"Possession, feminine → genitive [[deren]]."},
{s:"Relative pronouns", q:"In a relative clause the verb goes…", a:["at the end","second","first","directly after the pronoun"], t:"rule", c:0, e:"Relative clauses are subordinate, so the verb is final and commas fence the clause off."},
{s:"Relative pronouns", q:"[[Der Mann, ___ ich helfe, ist mein Nachbar.]]", a:["dem","den","der","dessen"], t:"gap", c:0, e:"[[helfen]] governs the dative, so the masculine pronoun is [[dem]] — the case is set by the verb inside the relative clause, never by the main clause."},
{s:"Relative pronouns", q:"In [[Das Buch, das ich lese, ist spannend]], why [[das]] and not [[dem]]?", a:["The pronoun is the direct object of [[lese]], so it is accusative","Neuter nouns can only ever take [[das]]","[[lesen]] governs the genitive","The main clause is in the present tense"], t:"rule", c:0, e:"Gender comes from [[Buch]] (neuter), case from the job done inside the clause; for neuter the two accusative and nominative forms happen to look alike."},
{s:"Relative pronouns", q:"[[Der Film, von ___ alle reden, läuft noch.]]", a:["dem","den","der","dessen"], t:"gap", c:0, e:"A preposition inside the relative clause sets the case: [[von]] takes the dative, so masculine [[der]] becomes [[dem]]."},
{s:"Relative pronouns", q:"Which two things decide the form of a relative pronoun?", a:["Gender from the noun described, case from its job inside the relative clause","Gender and case both from the noun described","Gender and case both from the main clause verb","Case from the noun, gender from the relative clause"], t:"rule", c:0, e:"The two decisions are independent, which is how [[Der Mann, dem ich helfe]] comes out masculine but dative."},
{s:"Relative pronouns", q:"Where do the relative pronouns differ from the definite article?", a:["In the dative plural [[denen]] and in all four genitive forms","In the genitive singular only","Throughout the plural","They never differ"], t:"rule", c:0, e:"Eleven of the sixteen cells are identical, so only [[denen]], [[dessen]] and [[deren]] have to be learned separately."},
{s:"Relative pronouns", q:"[[Alles, ___ er sagt, stimmt.]]", a:["was","das","dass","welches"], t:"gap", c:0, e:"After [[alles]], [[nichts]], [[etwas]] and [[vieles]] — and after a whole preceding clause — the relative pronoun is [[was]], not a der-form."},
{s:"Relative pronouns", q:"What is the masculine genitive relative pronoun?", a:["dessen","deren","denen","des"], t:"recall", c:0, e:"[[dessen]] covers masculine and neuter, [[deren]] feminine and plural: [[Der Mann, dessen Auto neu ist]]."},
{s:"Relative pronouns", q:"[[Der Mann, den die Frau sieht, ist mein Bruder.]] Who is doing the seeing?", a:["the woman","the man","the brother","it is ambiguous"], t:"rule", c:0, e:"[[den]] is accusative, so the man is the object inside the clause and [[die Frau]] its subject."},
{s:"Relative pronouns", q:"[[Die Frau, der ich helfe, ist Ärztin.]] What does [[der]] tell you here?", a:["she is the dative object of [[helfen]]","she is the subject","it is a genitive","it is the plural"], t:"rule", c:0, e:"[[helfen]] takes the dative, so a feminine relative pronoun appears as [[der]] rather than [[die]]."},
{s:"Relative pronouns", q:"[[Das Kind, dessen Hund weglief, weint.]] Whose dog ran away?", a:["the child's","the dog's own","nobody's — it is a stray","the mother's"], t:"rule", c:0, e:"[[dessen]] is the genitive relative pronoun: possession, referring back to the neuter [[Kind]]."},

{s:"Indefinite pronouns", q:"What is the accusative of [[man]]?", a:["einen","man","manen","einem"], t:"recall", c:0, e:"[[man]] exists only in the nominative and borrows [[einen]] / [[einem]] elsewhere."},
{s:"Indefinite pronouns", q:"[[Ich habe etwas ___ gehört.]] (something new)", a:["Neues","neues","Neue","neuen"], t:"gap", c:0, e:"After [[etwas]] the adjective is capitalised, neuter and strong: [[Neues]]."},
{s:"Indefinite pronouns", q:"Which is the usual German alternative to an English passive?", a:["[[man]] + active verb","[[es gibt]]","[[sich]] + verb","[[jemand]] + verb"], t:"rule", c:0, e:"[[Man spricht hier Deutsch]] for \"German is spoken here\"."},
{s:"Indefinite pronouns", q:"What is the dative of [[jemand]]?", a:["jemandem","jemanden","jemands","jemand"], t:"recall", c:0, e:"[[jemand]] and [[niemand]] decline like [[jeder]]: [[-en]] in the accusative, [[-em]] in the dative."},
{s:"Indefinite pronouns", q:"[[Ich habe gestern ___ gesehen.]] (no one)", a:["niemanden","niemandes","niemandem","nichts"], t:"gap", c:0, e:"[[sehen]] takes a direct object, so [[niemand]] moves into the accusative [[niemanden]]; [[nichts]] would mean **nothing** rather than **no one**."},
{s:"Indefinite pronouns", q:"[[Ich habe mit ___ darüber gesprochen.]] (someone)", a:["jemandem","jemand","jemanden","jemandes"], t:"gap", c:0, e:"[[mit]] takes the dative, and unlike [[man]] the pronoun [[jemand]] has a dative form of its own."},
{s:"Indefinite pronouns", q:"What does the prefix [[irgend-]] add to a word?", a:["Vagueness — [[irgendwo]] is **somewhere or other**","Negation — it reverses the meaning","Emphasis — it makes the word stronger","Formality — it marks polite speech"], t:"rule", c:0, e:"The same prefix gives [[irgendjemand]] **somebody or other** and [[irgendwann]] **at some point**."},
{s:"Indefinite pronouns", q:"Which quantifier means **several**?", a:["mehrere","wenige","beide","andere"], t:"recall", c:0, e:"[[wenige]] is **few**, [[beide]] **both** and [[andere]] **others** — all four stand on their own, without a noun."},
{s:"Indefinite pronouns", q:"[[Nicht ___ kann so gut kochen.]] (everyone)", a:["jeder","jeden","jedem","jedes"], t:"gap", c:0, e:"The pronoun is the subject of the sentence, so it stays nominative; [[jeden]] and [[jedem]] would be the accusative and dative."},
{s:"Indefinite pronouns", q:"Which of these is true of [[man]]?", a:["It is never capitalised and is unrelated to [[der Mann]]","It is a short form of [[der Mann]] and refers to men","It is capitalised like any other noun","It exists in every case except the nominative"], t:"rule", c:0, e:"[[man]] exists only in the nominative and borrows [[einen]] and [[einem]] from [[einer]] for the other cases."},

/* ---------- III. Articles & Case ---------- */

{s:"The four cases at a glance", q:"Which question word asks for the dative?", a:["wem?","wen?","wer?","wessen?"], t:"recall", c:0, e:"[[wer – wen – wem – wessen]] run nominative, accusative, dative, genitive."},
{s:"The four cases at a glance", q:"[[Den Mann beißt der Hund.]] Who does the biting?", a:["the dog","the man","it is ambiguous","neither"], t:"rule", c:0, e:"[[der Hund]] is nominative, so it is the subject regardless of word order."},
{s:"The four cases at a glance", q:"After [[sein]], [[werden]] and [[bleiben]] the following noun is…", a:["nominative","accusative","dative","genitive"], t:"recall", c:0, e:"These verbs link two nominatives: [[Er ist ein guter Lehrer.]]"},
{s:"The four cases at a glance", q:"The question word [[wessen?]] asks for which case?", a:["Genitiv","Dativ","Akkusativ","Nominativ"], t:"recall", c:0, e:"Each case has its own question word: [[wer/was]] nominative, [[wen/was]] accusative, [[wem]] dative, [[wessen]] genitive."},
{s:"The four cases at a glance", q:"What is the dative plural form of the definite article?", a:["den","der","dem","die"], t:"recall", c:0, e:"[[den]] does double duty as accusative masculine and dative plural — the extra [[-n]] on the noun ([[den Kindern]]) tells you which one you are looking at."},
{s:"The four cases at a glance", q:"Which form is the feminine dative of the definite article?", a:["der","die","dem","den"], t:"recall", c:0, e:"Feminine [[die]] becomes [[der]] in both dative and genitive — [[mit der Frau]] — which trips learners up because [[der]] looks masculine."},
{s:"The four cases at a glance", q:"[[Ich gebe dem Mann das Buch.]] What case is [[das Buch]] in?", a:["Akkusativ","Dativ","Nominativ","Genitiv"], t:"rule", c:0, e:"[[dem Mann]] is the indirect object (dative); the book is the thing actually handed over, so it is the direct object — neuter [[das]] just happens to look identical in nominative and accusative."},
{s:"The four cases at a glance", q:"German allows both [[Der Hund beißt den Mann]] and [[Den Mann beißt der Hund]] with the same meaning. Why?", a:["The case endings, not the position, show which noun is subject and which is object","The first noun in a German sentence is always the subject","Both nouns are nominative, so either one can do the biting","Word order is only fixed in questions"], t:"rule", c:0, e:"Because the articles carry the information, German can move nouns around for emphasis in a way English cannot."},
{s:"The four cases at a glance", q:"In the article table the genitive is written [[des]] +s. What does that [[+s]] refer to?", a:["An ending added to the noun itself","A second, longer form of the article","An ending added to any adjective present","A marker showing the noun is plural"], t:"rule", c:0, e:"The article and the noun are both marked in the genitive: [[des Mann]] is wrong, [[des Mannes]] is right."},
{s:"The four cases at a glance", q:"[[___ Hund gehört meinem Bruder.]] (the dog — it is the subject)", a:["Der","Den","Dem","Des"], t:"gap", c:0, e:"Whoever or whatever performs the verb stands in the nominative, however far into the sentence it sits; [[meinem Bruder]] is the dative because [[gehören]] takes a dative object."},
{s:"The four cases at a glance", q:"[[___ Auto des Mannes ist neu.]] (the car)", a:["Das","Der","Dem","Des"], t:"gap", c:0, e:"Two cases in one phrase: [[das Auto]] is the nominative subject, [[des Mannes]] the genitive possessor hanging off it."},
{s:"The four cases at a glance", q:"[[Den Hund beißt der Mann.]] Who bites whom?", a:["The man bites the dog","The dog bites the man","Each bites the other","The sentence is ungrammatical"], t:"rule", c:0, e:"[[den Hund]] is accusative and [[der Mann]] nominative, so the man is the subject wherever he stands in the sentence."},
{s:"The four cases at a glance", q:"[[Die Katze sieht der Hund.]] Who is doing the seeing?", a:["the dog","the cat","it is ambiguous","both at once"], t:"rule", c:0, e:"[[der Hund]] is nominative. [[die Katze]] looks like a subject but feminine nominative and accusative are identical, so the unambiguously marked word decides."},
{s:"The four cases at a glance", q:"[[Dem Kind gibt die Frau das Buch.]] Who ends up with the book?", a:["the child","the woman","the book's owner is not stated","both share it"], t:"rule", c:0, e:"[[dem Kind]] is dative — the receiver. [[die Frau]] is nominative and [[das Buch]] accusative."},
{s:"The four cases at a glance", q:"Why can German put the object first when English cannot?", a:["case endings mark the roles, so order is free to do other work","German has no fixed word order at all","the verb always comes first","English can do it too"], t:"rule", c:0, e:"Fronting an object emphasises it. English has to rely on order, so [[the dog the man bites]] simply breaks."},

{s:"Nominative", q:"Which is the feminine nominative of [[kein]]?", a:["keine","kein","keinen","keiner"], t:"recall", c:0, e:"Feminine takes [[-e]]: [[keine Frau]]."},
{s:"Nominative", q:"[[___ Schwester heißt Anna.]] (my sister)", a:["Meine","Mein","Meinen","Meiner"], t:"gap", c:0, e:"[[Schwester]] is feminine nominative, so [[meine]]."},
{s:"Nominative", q:"Which possessive is the odd one out in spelling once an ending is added?", a:["euer → eure","unser → unsere","ihr → ihre","dein → deine"], t:"rule", c:0, e:"[[euer]] drops its second [[e]]: [[eure]], never [[euere]]."},
{s:"Nominative", q:"After which of these verbs does a following noun stand in the nominative rather than the accusative?", a:["heißen","sehen","kennen","brauchen"], t:"rule", c:0, e:"[[sein]], [[werden]], [[bleiben]] and [[heißen]] take no object at all — the noun after them simply repeats the case of the subject."},
{s:"Nominative", q:"In [[Er wird ein guter Arzt]], why [[ein]] and not [[einen]]?", a:["[[werden]] is followed by the nominative, not the accusative","[[Arzt]] is feminine and cannot take [[einen]]","[[ein]] has no accusative form","An adjective in between blocks the accusative"], t:"rule", c:0, e:"Only a genuine direct object goes into the accusative; [[werden]] links two descriptions of the same person, so both are nominative."},
{s:"Nominative", q:"What is the nominative plural of [[mein]]?", a:["meine","meinen","meiner","mein"], t:"recall", c:0, e:"Every ein-word takes [[-e]] in the nominative and accusative plural: [[meine Eltern]], [[keine Bücher]]."},
{s:"Nominative", q:"Which is the correct nominative form for **our house**?", a:["[[unser Haus]]","[[unseres Haus]]","[[unsere Haus]]","[[unserem Haus]]"], t:"recall", c:0, e:"The neuter nominative is an empty slot for every ein-word, so [[unser]] stands bare — the same shape as [[ein Haus]] and [[mein Haus]]."},
{s:"Nominative", q:"Which possessive means **their**?", a:["ihr","sein","unser","euer"], t:"recall", c:0, e:"[[ihr]] does double duty for **her** and **their**; capitalised [[Ihr]] is the formal **your**, and context sorts them out."},
{s:"Nominative", q:"[[Das ist ___ guter Wein.]] (a)", a:["ein","einen","einem","eines"], t:"gap", c:0, e:"[[Das ist…]] is a linking construction, so the noun phrase after it is nominative — masculine [[ein]] with no ending."},
{s:"Nominative", q:"[[___ Bruder wohnt in Berlin.]] (his brother)", a:["Sein","Seinen","Seinem","Seiner"], t:"gap", c:0, e:"The subject is nominative, and masculine nominative is one of the three cells where an ein-word shows no ending at all."},
{s:"Nominative", q:"[[___ Eltern kommen morgen.]] (my parents)", a:["Meine","Mein","Meinen","Meiner"], t:"gap", c:0, e:"[[Eltern]] is plural, and the plural nominative of every ein-word ends in [[-e]]; [[meinen Eltern]] would be the dative, as in [[Ich helfe meinen Eltern]]."},

{s:"Accusative", q:"[[Ich sehe ___ Hund.]] (the dog)", a:["den","der","dem","des"], t:"gap", c:0, e:"Masculine accusative is [[den]] — the only column that changes from the nominative."},
{s:"Accusative", q:"Which column differs between nominative and accusative?", a:["masculine only","feminine only","neuter and plural","all four"], t:"rule", c:0, e:"Feminine, neuter and plural are identical in the two cases."},
{s:"Accusative", q:"[[Er kommt ___ Tag.]] (every day)", a:["jeden","jedem","jeder","jedes"], t:"gap", c:0, e:"Definite time without a preposition takes the accusative."},
{s:"Accusative", q:"What is the masculine accusative of [[kein]]?", a:["keinen","kein","keinem","keines"], t:"recall", c:0, e:"[[kein]] simply copies [[ein]]: [[einen]] → [[keinen]]. [[keinem]] is dative and [[keines]] genitive."},
{s:"Accusative", q:"What is the accusative plural of [[ihr]] (**their**)?", a:["ihre","ihren","ihrer","ihr"], t:"recall", c:0, e:"The plural column is identical in nominative and accusative, so [[ihre Bücher]] works as subject or object; [[ihren]] would be the dative plural."},
{s:"Accusative", q:"Why does [[der Mann]] become [[den Mann]] as a direct object while [[die Frau]] stays [[die Frau]]?", a:["Only the masculine singular has a separate accusative form","Feminine nouns never take case endings","[[die]] is already an accusative form and cannot change further","Feminine objects go into the dative instead"], t:"rule", c:0, e:"Feminine, neuter and plural are letter-for-letter the same in both cases, so a sentence with no masculine singular noun looks identical in nominative and accusative."},
{s:"Accusative", q:"[[Ich bleibe einen Monat.]] Why is [[einen Monat]] accusative?", a:["The accusative measures a span of time without a preposition","Time expressions are always accusative after [[bleiben]]","It is the subject of the sentence","[[Monat]] has no other form"], t:"rule", c:0, e:"Duration and definite time take a bare accusative: [[jeden Tag]], [[nächste Woche]], [[einen Monat]] — no preposition needed."},
{s:"Accusative", q:"[[Den Hund sieht der Mann.]] Who is doing the seeing?", a:["[[der Mann]]","[[der Hund]]","Both — the sentence is ambiguous","Neither — it is a question"], t:"rule", c:0, e:"[[den]] marks the accusative object wherever it stands, so fronting it changes the emphasis, not the meaning."},
{s:"Accusative", q:"[[Ich brauche ___ Stuhl.]] (a chair)", a:["einen","ein","einem","eines"], t:"gap", c:0, e:"[[der Stuhl]] is masculine, and masculine is the one column that changes for a direct object: [[ein]] → [[einen]]."},
{s:"Accusative", q:"[[Ich habe ___ Zeit.]] (no time)", a:["keine","keinen","kein","keiner"], t:"gap", c:0, e:"[[die Zeit]] is feminine, so nothing changes in the accusative — the tempting [[keinen]] belongs with masculine nouns like [[keinen Hunger]]."},
{s:"Accusative", q:"[[Kennst du ___ Lehrer?]] (our teacher)", a:["unseren","unser","unserem","unseres"], t:"gap", c:0, e:"[[kennen]] takes a direct object, and masculine accusative adds [[-en]] to every ein-word: [[meinen]], [[seinen]], [[unseren]]."},
{s:"Accusative", q:"[[Den Brief schreibt meine Schwester.]] Who is writing?", a:["my sister","the letter's sender is not stated","the letter","somebody unnamed"], t:"rule", c:0, e:"[[den Brief]] carries the masculine accusative [[-en]], so it is the object; [[meine Schwester]] is the subject."},
{s:"Accusative", q:"[[Der Lehrer fragt den Schüler.]] and [[Den Lehrer fragt der Schüler.]] — do these mean the same?", a:["No, the asker swaps","Yes, word order does not matter","Yes, both are the teacher asking","No, the second is ungrammatical"], t:"rule", c:0, e:"First the teacher asks; second the pupil asks. Only [[der]] / [[den]] tells you, and it moves with the noun."},
{s:"Accusative", q:"[[Ich sehe die Frau und das Kind.]] Which case are both nouns in?", a:["accusative, though neither shows it","nominative, as the subjects","the first accusative, the second nominative","dative, after [[sehen]]"], t:"rule", c:0, e:"Feminine and neuter are identical in the nominative and accusative, so nothing on the nouns shows it — [[sehen]] and its subject [[ich]] are what make them objects."},

{s:"Dative", q:"[[Wir fahren mit ___ Zug.]]", a:["dem","den","der","des"], t:"gap", c:0, e:"[[mit]] takes the dative; masculine dative is [[dem]]."},
{s:"Dative", q:"What happens to a plural noun in the dative?", a:["it adds -n unless it already ends in -n or -s","nothing","it adds -s","it adds -e"], t:"rule", c:0, e:"[[die Kinder]] → [[mit den Kindern]], but [[den Autos]] is unchanged."},
{s:"Dative", q:"The dative endings run…", a:["-m, -r, -m, -n","-n, -e, -s, -e","-s, -r, -s, -r","-r, -e, -s, -e"], t:"rule", c:0, e:"Masculine and neuter are identical throughout the dative."},
{s:"Dative", q:"What is the feminine dative of [[ein]]?", a:["einer","eine","einem","einen"], t:"recall", c:0, e:"The dative endings run [[-m, -r, -m, -n]], so feminine takes [[-r]]: [[mit einer Freundin]]."},
{s:"Dative", q:"How does [[die Freunde]] appear after the preposition [[mit]]?", a:["[[mit den Freunden]]","[[mit den Freunde]]","[[mit dem Freunden]]","[[mit der Freunden]]"], t:"recall", c:0, e:"Two things happen at once in the dative plural: the article becomes [[den]] and the noun itself gains an [[-n]]."},
{s:"Dative", q:"Which two columns are identical right across the dative?", a:["maskulin and neutrum","feminin and Plural","maskulin and feminin","neutrum and Plural"], t:"rule", c:0, e:"[[dem]], [[einem]], [[meinem]] cover both masculine and neuter, which removes one gender decision from the dative entirely."},
{s:"Dative", q:"Why is there no extra [[-n]] on the noun in [[mit den Autos]]?", a:["Plurals already ending in [[-n]] or [[-s]] add nothing","[[Auto]] is neuter, and neuter plurals never change","[[mit]] does not actually take the dative","The [[-n]] appears only in the genitive"], t:"rule", c:0, e:"The dative plural [[-n]] is a real case ending: [[den Kindern]], [[den Büchern]]. It is simply left off where it cannot show — plurals already ending in [[-n]] ([[den Frauen]]) and foreign [[-s]] plurals ([[den Autos]])."},
{s:"Dative", q:"[[Ich helfe ___ Schwester.]] (my sister)", a:["meiner","meine","meinem","meinen"], t:"gap", c:0, e:"[[helfen]] is one of the verbs whose only object is dative, and feminine dative takes [[-r]] — no preposition needed to trigger it."},
{s:"Dative", q:"[[Das Buch gehört ___ Lehrer.]] (the teacher, m)", a:["dem","den","der","des"], t:"gap", c:0, e:"[[gehören]] takes a dative object, so masculine [[der]] becomes [[dem]]; [[den]] would be the accusative you might expect from English word order."},
{s:"Dative", q:"[[Wir spielen mit ___ Kindern.]] (the children)", a:["den","dem","der","die"], t:"gap", c:0, e:"The [[-n]] already on [[Kindern]] is the giveaway: it only appears in the dative plural, which pairs with [[den]]."},
{s:"Dative", q:"[[Ich schreibe ___ Eltern eine E-Mail.]] (my parents)", a:["meinen","meine","meiner","meinem"], t:"gap", c:0, e:"The person written to is the indirect object, so plural dative [[meinen]]; [[eine E-Mail]] is the accusative direct object."},
{s:"Dative", q:"[[Der Mann zeigt dem Kind den Hund.]] Who is shown to whom?", a:["the dog is shown to the child","the child is shown to the dog","the man is shown to the child","the dog shows the child"], t:"rule", c:0, e:"[[dem Kind]] is dative — the recipient — and [[den Hund]] accusative — the thing handed over."},
{s:"Dative", q:"[[Die Frau folgt dem Mann.]] Who is in front?", a:["the man","the woman","they walk side by side","it cannot be told"], t:"rule", c:0, e:"[[folgen]] takes a dative object, so the dative [[dem Mann]] is the one being followed, not the follower."},
{s:"Dative", q:"[[Ich habe es ihm gegeben.]] What was given to whom?", a:["it was given to him","he was given to it","it was given to her","it was given to them"], t:"rule", c:0, e:"[[ihm]] is dative and so the receiver, [[es]] accusative and so the thing given. When both objects are pronouns the accusative comes first — [[es ihm]], never [[ihm es]]."},

{s:"Genitive", q:"[[das Auto ___ Mannes]]", a:["des","der","dem","den"], t:"gap", c:0, e:"Masculine genitive [[des]], and the noun itself adds [[-es]]."},
{s:"Genitive", q:"Which ending does a one-syllable masculine or neuter noun take in the genitive?", a:["-es","-s","-en","none"], t:"recall", c:0, e:"[[des Mannes]], [[des Kindes]]; longer nouns take plain [[-s]]."},
{s:"Genitive", q:"What replaces the genitive in everyday speech?", a:["von + Dativ","für + Akkusativ","zu + Dativ","an + Akkusativ"], t:"rule", c:0, e:"[[das Auto vom Mann]] rather than [[des Mannes]]."},
{s:"Genitive", q:"What is the feminine genitive of the definite article?", a:["der","die","des","den"], t:"recall", c:0, e:"The genitive endings run [[-s, -r, -s, -r]], so feminine and plural both give [[der]]: [[die Farbe der Tür]], [[die Autos der Leute]]."},
{s:"Genitive", q:"What is the genitive of [[das Haus]]?", a:["[[des Hauses]]","[[des Haus]]","[[der Hauses]]","[[dem Hauses]]"], t:"recall", c:0, e:"Nouns of one syllable, and any ending in [[s, ß, z, tz, x]], take [[-es]]; longer ones take plain [[-s]], as in [[des Lehrers]]."},
{s:"Genitive", q:"What is the genitive plural of [[kein]]?", a:["keiner","keines","keinen","keine"], t:"recall", c:0, e:"Genitive plural takes [[-r]] for every determiner — [[der]], [[keiner]], [[meiner]] — matching the feminine singular exactly."},
{s:"Genitive", q:"The plural column for [[ein]] is blank in every one of these tables. Why?", a:["[[ein]] means **a**, and **a** has no plural","[[ein]] survives only in the nominative","Its plural forms are irregular and listed separately","[[ein]] is a pronoun rather than a determiner"], t:"rule", c:0, e:"German drops the article there just as English does; [[kein]] and the possessives do have full plurals, which is why only the [[ein]] row is empty."},
{s:"Genitive", q:"In the genitive, which columns share a form?", a:["maskulin with neutrum ([[des]]), and feminin with Plural ([[der]])","maskulin with feminin, and neutrum with Plural","All four columns are different","Only feminin and neutrum match"], t:"rule", c:0, e:"The pattern [[-s, -r, -s, -r]] means you really only have two forms to produce; the dative pairs maskulin with neutrum in the same way, but there feminin and Plural go their separate ways."},
{s:"Genitive", q:"[[der Titel ___ Buches]] (the book)", a:["des","der","dem","das"], t:"gap", c:0, e:"The [[-es]] on [[Buches]] and the [[des]] on the article always travel together — one without the other is a half-formed genitive."},
{s:"Genitive", q:"[[Wegen ___ Wetters bleiben wir zu Hause.]] (the weather)", a:["des","dem","das","der"], t:"gap", c:0, e:"[[wegen]] is a genitive preposition, and [[das Wetter]] is neuter, so [[des Wetters]] — in casual speech you will also hear [[wegen dem Wetter]]."},
{s:"Genitive", q:"[[Während ___ Ferien war ich in Berlin.]] (the holidays)", a:["der","den","des","die"], t:"gap", c:0, e:"[[Ferien]] is plural, and the genitive plural article is [[der]]; unlike the dative, the noun adds nothing."},
{s:"Genitive", q:"[[das Auto des Mannes]] and [[der Mann des Autos]] — which is normal German?", a:["the first: the man's car","the second: the car's man","both mean the same","neither is grammatical"], t:"rule", c:0, e:"The genitive noun is the owner and follows what it owns, so the [[-es]] marks the man as the possessor."},
{s:"Genitive", q:"[[Die Farbe der Tür gefällt mir.]] What do I like?", a:["the colour","the door","both equally","the door's owner"], t:"rule", c:0, e:"Feminine dative and genitive are both [[der Tür]], but a bare noun sitting behind another with no preposition can only be genitive. It describes [[die Farbe]], the nominative subject of [[gefallen]]."},

{s:"der-words and ein-words", q:"Which is NOT a der-word?", a:["kein","dieser","jeder","welcher"], t:"recall", c:0, e:"[[kein]] follows [[ein]], so it is an ein-word."},
{s:"der-words and ein-words", q:"In how many cells do the two families differ?", a:["three","one","eight","sixteen"], t:"rule", c:0, e:"Masculine nominative, and neuter nominative and accusative."},
{s:"der-words and ein-words", q:"[[___ Mann ist mein Bruder.]] (this man)", a:["Dieser","Diese","Diesen","Dies"], t:"gap", c:0, e:"A der-word shows [[-er]] in the masculine nominative, where [[ein]] shows nothing."},
{s:"der-words and ein-words", q:"Which family does [[welcher]] belong to?", a:["the der-words","the ein-words","neither family","both, depending on case"], t:"recall", c:0, e:"[[dieser]], [[jeder]], [[welcher]], [[mancher]], [[jener]], [[solcher]] and [[aller]] all carry the definite-article endings."},
{s:"der-words and ein-words", q:"What is the masculine dative of [[jeder]]?", a:["jedem","jeden","jedes","jeder"], t:"recall", c:0, e:"der-words copy the article cell for cell: [[dem]] → [[jedem]], [[diesem]], [[welchem]]."},
{s:"der-words and ein-words", q:"What is the genitive plural of [[dieser]]?", a:["dieser","dieses","diesen","diesem"], t:"recall", c:0, e:"Genitive plural takes [[-er]] just like [[der]]: [[die Farbe dieser Blumen]]; [[diesen]] would be the dative plural."},
{s:"der-words and ein-words", q:"[[dieser Mann]] but [[ein Mann]] — why does [[ein]] show no ending?", a:["ein-words carry no ending in the masculine nominative","[[Mann]] is a weak noun and refuses endings","[[ein]] never takes any ending at all","der-words add [[-er]] only before people"], t:"rule", c:0, e:"The two families part company in exactly three cells — masculine nominative and neuter nominative/accusative — and agree in the other thirteen."},
{s:"der-words and ein-words", q:"[[kein]] takes its endings from which pattern?", a:["the ein-word pattern","the der-word pattern","the adjective pattern","it takes no endings"], t:"rule", c:0, e:"[[kein]] is [[ein]] with a [[k-]] in front, so [[kein Mann]] and [[keinen Mann]]; unlike [[ein]] it does have a full set of plural forms."},
{s:"der-words and ein-words", q:"[[In ___ Stadt gibt es einen Dom.]] (this city)", a:["dieser","diese","diesem","diesen"], t:"gap", c:0, e:"[[in]] with no movement takes the dative, and feminine dative is [[-er]] for der-words and ein-words alike: [[dieser]], [[der]], [[meiner]]."},
{s:"der-words and ein-words", q:"[[Er hat ___ Buch schon gelesen.]] (this book)", a:["dieses","diesem","dieser","diesen"], t:"gap", c:0, e:"Neuter accusative is one of the cells where a der-word does show an ending — [[dieses Buch]] beside the bare [[ein Buch]]."},
{s:"der-words and ein-words", q:"[[___ Kind bekommt ein Geschenk.]] (each child)", a:["Jedes","Jeder","Jedem","Jeden"], t:"gap", c:0, e:"[[jeder]] is a der-word and [[Kind]] is neuter, so the nominative shows [[-es]] exactly as [[das]] does; [[jeder]] would need a masculine noun."},

/* ---------- IV. Adjectives ---------- */

{s:"Which ending pattern?", q:"[[Der Wagen ist rot.]] Why has [[rot]] no ending?", a:["it is predicative, not in front of a noun","[[rot]] never takes endings","the noun is masculine","[[sein]] blocks endings"], t:"rule", c:0, e:"Only attributive adjectives — those in front of a noun — take endings."},
{s:"Which ending pattern?", q:"Which pattern follows [[jeder]]?", a:["weak","mixed","strong","none"], t:"recall", c:0, e:"[[jeder]] is a der-word, so the adjective is weak."},
{s:"Which ending pattern?", q:"[[ein ___ Wagen]] (a red car)", a:["roter","rote","roten","rotes"], t:"gap", c:0, e:"Mixed pattern: masculine nominative takes [[-er]] because [[ein]] shows nothing."},
{s:"Which ending pattern?", q:"When does a German adjective take an ending at all?", a:["Only when it stands directly in front of a noun","Only when it follows [[sein]] or [[werden]]","Whenever it describes a plural noun","Whenever it comes after the noun it describes"], t:"rule", c:0, e:"Attributive adjectives take endings; predicative ones ([[Der Wagen ist rot]]) and adverbs ([[Er fährt schnell]]) never do."},
{s:"Which ending pattern?", q:"Why must an adjective take strong endings when no determiner precedes it?", a:["Case and gender have to be marked exactly once, so the adjective does the job itself","Strong endings are simply the default for all adjectives","Nouns without an article are always plural","The adjective is stressed and so needs a longer ending"], t:"rule", c:0, e:"With no determiner the adjective borrows the der-word endings: [[guter Wein]], [[gutem Wein]]."},
{s:"Which ending pattern?", q:"Which of these is an ein-word, and so triggers the mixed pattern?", a:["unser","dieser","jeder","welcher"], t:"recall", c:0, e:"[[ein, kein]] and all the possessives ([[mein, dein, ihr, unser]]) are ein-words; [[dieser, jeder, welcher, mancher]] are der-words and take weak endings."},
{s:"Which ending pattern?", q:"Which is correct for **a high mountain**?", a:["ein hoher Berg","ein hocher Berg","ein hohes Berg","ein hoch Berg"], t:"recall", c:0, e:"[[hoch]] loses its [[-c-]] before an ending: [[hoch]] → [[hoh-]], so [[ein hoher Berg]] but [[Der Berg ist hoch]]."},
{s:"Which ending pattern?", q:"Which is correct for **a dark room**?", a:["ein dunkler Raum","ein dunkeler Raum","ein dunkeler Raume","ein dunkel Raum"], t:"recall", c:0, e:"Adjectives in [[-el]] and [[-er]] drop the [[e]] of the stem before an ending: [[dunkel]] → [[dunkl-]], [[teuer]] → [[teur-]], [[sauer]] → [[saur-]]."},
{s:"Which ending pattern?", q:"After a bare number such as [[zwei]] or [[drei]], which pattern does the adjective take?", a:["Strong, because numbers do not count as determiners","Weak, because a number behaves like a der-word","Mixed, because a number behaves like an ein-word","No ending at all after a number"], t:"rule", c:0, e:"[[zwei rote Wagen]] — the number marks nothing, so the adjective still has to signal case and gender."},
{s:"Which ending pattern?", q:"[[Ich trinke keine ___ Milch.]] (sour)", a:["saure","sauere","sauerer","sauer"], t:"gap", c:0, e:"[[sauer]] → [[saur-]] before an ending, and [[keine]] + feminine accusative gives the weak [[-e]]."},
{s:"Which ending pattern?", q:"[[Das Auto ist ___.]] (expensive)", a:["teuer","teures","teure","teurer"], t:"gap", c:0, e:"After [[sein]], [[werden]] or [[bleiben]] the adjective is predicative and takes no ending — the stem stays [[teuer]], not [[teur-]]."},

{s:"Weak endings — after a der-word", q:"[[dem ___ Mann]] (the good man)", a:["guten","gute","guter","gutem"], t:"gap", c:0, e:"Every weak dative is [[-en]]."},
{s:"Weak endings — after a der-word", q:"How many different endings does the weak pattern use?", a:["two","three","four","five"], t:"rule", c:0, e:"Only [[-e]] and [[-en]]."},
{s:"Weak endings — after a der-word", q:"[[die ___ Leute]] (the good people)", a:["guten","gute","guter","gutes"], t:"gap", c:0, e:"Weak plural nominative is [[-en]]."},
{s:"Weak endings — after a der-word", q:"Which five weak cells take [[-e]] rather than [[-en]]?", a:["All three nominative singulars, plus feminine and neuter accusative","All four nominatives, plus masculine accusative","All three accusative singulars, plus masculine and neuter nominative","The whole nominative row and the whole dative row"], t:"recall", c:0, e:"The [[-e]] forms a block in the top-left corner of the table; everything else — masculine accusative, the nominative plural and the whole dative and genitive rows — is [[-en]]."},
{s:"Weak endings — after a der-word", q:"[[Ich kenne den ___ Mann.]] (old)", a:["alten","alte","alter","altem"], t:"gap", c:0, e:"Masculine accusative is outside the [[-e]] block, so the weak ending is [[-en]] — and [[den]] has already marked the case."},
{s:"Weak endings — after a der-word", q:"[[Das ___ Kind schläft.]] (small)", a:["kleine","kleines","kleinen","kleiner"], t:"gap", c:0, e:"Neuter nominative is one of the five [[-e]] cells; [[-es]] would be the mixed ending, as in [[ein kleines Kind]]."},
{s:"Weak endings — after a der-word", q:"[[Er hilft der ___ Frau.]] (old)", a:["alten","alte","alter","altem"], t:"gap", c:0, e:"[[helfen]] takes the dative, and every dative cell in the weak table is [[-en]] — feminine [[-e]] only survives in the nominative and accusative."},
{s:"Weak endings — after a der-word", q:"[[Wir wohnen in diesem ___ Haus.]] (new)", a:["neuen","neuem","neues","neue"], t:"gap", c:0, e:"[[dieser]] is a der-word, so the pattern is weak and the dative takes [[-en]]; [[-em]] is the strong ending you would need without a determiner."},
{s:"Weak endings — after a der-word", q:"Which is correct: **each new day**?", a:["jeder neue Tag","jeder neuer Tag","jeder neuen Tag","jeder neues Tag"], t:"rule", c:0, e:"[[jeder]] is a der-word and already shows masculine nominative, so the adjective relaxes to weak [[-e]]. [[-er]] is the mixed ending after an ein-word ([[ein neuer Tag]]) or the strong ending with no determiner at all ([[neuer Tag]])."},
{s:"Weak endings — after a der-word", q:"Which weak genitive form is right: [[des ___ Kindes]]?", a:["guten","gutes","gute","gutem"], t:"recall", c:0, e:"The whole genitive row is [[-en]] in the weak pattern — the [[-es]] on [[des]] and on [[Kindes]] does all the marking needed."},
{s:"Weak endings — after a der-word", q:"Why is it [[die guten Leute]] and not [[die gute Leute]]?", a:["The weak plural is [[-en]] in every case, including the nominative","Plural adjectives always copy the ending of the article","[[Leute]] is a weak noun and forces [[-en]]","[[-e]] is only used with masculine nouns"], t:"rule", c:0, e:"The [[-e]] block covers only the three nominative singulars and two accusatives; the nominative plural sits outside it."},

{s:"Mixed endings — after an ein-word", q:"[[ein ___ Kind]] (a good child)", a:["gutes","guter","gute","guten"], t:"gap", c:0, e:"Neuter nominative takes [[-es]], one of the three cells where mixed differs from weak."},
{s:"Mixed endings — after an ein-word", q:"[[einen ___ Mann]]", a:["guten","guter","gutes","gutem"], t:"gap", c:0, e:"Masculine accusative is [[-en]], the same as the weak pattern."},
{s:"Mixed endings — after an ein-word", q:"The mixed pattern differs from the weak one in how many cells?", a:["three","one","six","none"], t:"rule", c:0, e:"Masculine nominative, neuter nominative and neuter accusative."},
{s:"Mixed endings — after an ein-word", q:"Which three cells make the mixed pattern differ from the weak one?", a:["Masculine nominative, neuter nominative and neuter accusative","Masculine nominative, masculine accusative and neuter dative","Feminine nominative, feminine accusative and the plural","The whole genitive row"], t:"rule", c:0, e:"Those are exactly the three slots where [[ein]] itself has no ending, so the adjective steps in: [[ein guter Mann]], [[ein gutes Kind]]."},
{s:"Mixed endings — after an ein-word", q:"[[Mein ___ Bruder wohnt in Berlin.]] (little)", a:["kleiner","kleine","kleinen","kleines"], t:"gap", c:0, e:"[[mein]] is bare in the masculine nominative, so the adjective supplies [[-er]] — after [[der]] you would write [[der kleine Bruder]]."},
{s:"Mixed endings — after an ein-word", q:"[[Sie hat ein ___ Auto.]] (new)", a:["neues","neue","neuen","neuer"], t:"gap", c:0, e:"Neuter accusative after an ein-word is [[-es]], because [[ein]] shows nothing; the weak form after [[das]] would be [[das neue Auto]]."},
{s:"Mixed endings — after an ein-word", q:"[[Eine ___ Frau wartet draußen.]] (young)", a:["junge","junger","jungen","junges"], t:"gap", c:0, e:"Feminine nominative is not one of the three special cells: [[eine]] already marks it, so the adjective stays weak with [[-e]]."},
{s:"Mixed endings — after an ein-word", q:"Why is it [[mit meinem neuen Wagen]] and not [[mit meinem neuem Wagen]]?", a:["In the dative the ein-word already shows the case, so the adjective stays weak with [[-en]]","[[mit]] always forces [[-en]] on a following adjective","[[-em]] can only be used with neuter nouns","Possessives never allow strong endings anywhere"], t:"rule", c:0, e:"Mixed differs from weak in three cells only; the dative is not one of them, so the whole dative row is [[-en]]."},
{s:"Mixed endings — after an ein-word", q:"What ending does the adjective take in the plural after [[keine]]?", a:["-en","-e","-er","-es"], t:"recall", c:0, e:"[[keine guten Leute]] — the entire plural column is [[-en]] in both the weak and the mixed pattern; only the strong plural nominative and accusative use [[-e]]."},
{s:"Mixed endings — after an ein-word", q:"Which is correct for **a small child** in the genitive: [[eines ___ Kindes]]?", a:["kleinen","kleines","kleinem","kleine"], t:"recall", c:0, e:"The whole genitive row is [[-en]] in the mixed pattern, exactly as in the weak one: [[eines kleinen Kindes]]."},
{s:"Mixed endings — after an ein-word", q:"Why does [[ein guter Mann]] have [[-er]] where [[der gute Mann]] has [[-e]]?", a:["[[ein]] carries no ending, so the adjective must show masculine nominative itself","[[gut]] changes its ending after any indefinite word","[[-er]] marks the noun as a person rather than a thing","[[der]] is dative here and [[ein]] is nominative"], t:"rule", c:0, e:"German marks case and gender exactly once in the noun phrase — whichever word is free to do it takes the job."},

{s:"Strong endings — no determiner", q:"[[___ Wein]] (good wine, nominative)", a:["Guter","Gutes","Gute","Guten"], t:"gap", c:0, e:"With no determiner the adjective borrows the der-word ending [[-er]]."},
{s:"Strong endings — no determiner", q:"[[mit ___ Milch]] (with good milk)", a:["guter","gutem","gute","guten"], t:"gap", c:0, e:"Feminine dative strong is [[-er]], mirroring [[der]]."},
{s:"Strong endings — no determiner", q:"Which strong ending does NOT mirror the definite article?", a:["masculine genitive -en","masculine dative -em","feminine dative -er","neuter nominative -es"], t:"rule", c:0, e:"Masculine and neuter genitive take [[-en]], because the noun already carries the [[-s]]."},
{s:"Strong endings — no determiner", q:"[[Ich trinke gern ___ Bier.]] (cold)", a:["kaltes","kalte","kalter","kaltem"], t:"gap", c:0, e:"With no determiner the adjective has to mark the neuter itself: strong neuter nominative and accusative are [[-es]], as in [[kaltes Bier]]."},
{s:"Strong endings — no determiner", q:"[[Bei ___ Wetter bleiben wir zu Hause.]] (bad)", a:["schlechtem","schlechten","schlechtes","schlechter"], t:"gap", c:0, e:"[[bei]] takes the dative and nothing else marks it, so the adjective takes strong [[-em]] — from [[dem]] with the [[d-]] chopped off."},
{s:"Strong endings — no determiner", q:"[[Wir haben viel ___ Wein getrunken.]] (good)", a:["guten","guter","gutes","gutem"], t:"gap", c:0, e:"[[viel]], [[wenig]], [[etwas]] and [[mehr]] do not count as determiners, so the adjective is strong: masculine accusative [[-en]]."},
{s:"Strong endings — no determiner", q:"Which strong plural nominative is right for **good wines**?", a:["gute Weine","guten Weine","guter Weine","gutes Weine"], t:"recall", c:0, e:"Strong plural nominative and accusative are [[-e]]; [[guten Weine]] would confuse it with the plural after a determiner, and [[guter Weine]] is the genitive."},
{s:"Strong endings — no determiner", q:"What is the strong ending in the dative plural?", a:["-en","-e","-em","-er"], t:"recall", c:0, e:"[[mit guten Weinen]] — it mirrors [[den]] in [[den Weinen]], and the noun adds its own dative-plural [[-n]] as well."},
{s:"Strong endings — no determiner", q:"Why do the masculine and neuter genitive take [[-en]] rather than [[-es]]?", a:["The noun already carries the genitive [[-s]], so the adjective need not repeat it","Genitive adjectives are always weak","[[-es]] is reserved for the nominative","The genitive has no strong forms at all"], t:"rule", c:0, e:"[[guten Weines]], [[guten Bieres]] — this is the one place where the strong endings break with the article pattern."},
{s:"Strong endings — no determiner", q:"The strong endings are the definite-article endings with what removed?", a:["The initial [[d-]]","The final [[-r]]","The vowel of the article","The plural [[-n]]"], t:"rule", c:0, e:"[[d-er]] → [[-er]], [[d-em]] → [[-em]], [[d-ie]] → [[-e]]: if you know [[der/dem/die]] you already know most of the strong table. Only the masculine and neuter genitive break the pattern, taking [[-en]] rather than [[-es]]."},
{s:"Strong endings — no determiner", q:"After [[etwas]] and [[wenig]], which pattern does a following adjective take?", a:["Strong","Weak","Mixed","No ending"], t:"rule", c:0, e:"They are quantifiers, not determiners, so they mark nothing and leave the work to the adjective: [[wenig frisches Obst]]."},

{s:"Adjectival nouns and participles", q:"[[Er ist ein ___.]] (a German man)", a:["Deutscher","Deutsche","Deutschen","Deutsch"], t:"gap", c:0, e:"Adjectival nouns keep adjective endings; after [[ein]] the mixed masculine ending is [[-er]]."},
{s:"Adjectival nouns and participles", q:"[[das ___ Kind]] (the laughing child)", a:["lachende","gelachte","lachend","lacht"], t:"gap", c:0, e:"Present participle is infinitive + [[d]], then normal adjective endings."},
{s:"Adjectival nouns and participles", q:"Which ordinal is irregular?", a:["dritte","zweite","vierte","fünfte"], t:"recall", c:0, e:"[[erste]], [[dritte]], [[siebte]] and [[achte]] are the irregular ones."},
{s:"Adjectival nouns and participles", q:"Why is it [[der Deutsche]] but [[ein Deutscher]]?", a:["An adjectival noun keeps adjective endings, so it is weak after [[der]] and mixed after [[ein]]","Nouns change their ending depending on how formal the sentence is","[[Deutscher]] is the plural and [[Deutsche]] the singular","[[ein]] always adds [[-r]] to a following noun"], t:"rule", c:0, e:"The word is capitalised but still declines like an adjective: [[der Deutsche]], [[ein Deutscher]], [[die Deutschen]]."},
{s:"Adjectival nouns and participles", q:"[[Ich habe mit einem ___ gesprochen.]] (a German man)", a:["Deutschen","Deutscher","Deutsche","Deutschem"], t:"gap", c:0, e:"Dative after an ein-word is [[-en]] on any adjective, and an adjectival noun is no exception — only the capital letter marks it as a noun."},
{s:"Adjectival nouns and participles", q:"[[Erzähl mir etwas ___!]] (something new)", a:["Neues","neues","Neue","Neuen"], t:"gap", c:0, e:"After [[etwas]], [[nichts]], [[viel]] and [[wenig]] the adjectival noun is neuter and strong — hence [[-es]] — and it is capitalised."},
{s:"Adjectival nouns and participles", q:"Why is it [[nichts Gutes]] and not [[nichts Gute]]?", a:["After [[nichts]] the adjectival noun is neuter and strong, so it takes [[-es]]","[[nichts]] is a der-word and forces the weak pattern","[[Gutes]] is a fixed idiom with no rule behind it","[[nichts]] counts as a plural"], t:"rule", c:0, e:"The same logic gives [[etwas Neues]] and [[viel Interessantes]] — nothing precedes to mark neuter, so the adjective does it."},
{s:"Adjectival nouns and participles", q:"Why is it [[ein gekochtes Ei]] and not [[ein gekochte Ei]]?", a:["A participle used before a noun takes the ordinary adjective endings, here mixed neuter [[-es]]","Participles always end in [[-es]]","[[Ei]] is a weak noun and needs [[-es]] on the word before it","Past participles never change, so [[gekocht]] is simply wrong"], t:"rule", c:0, e:"Partizip II works exactly like an adjective: [[das gekochte Ei]] after a der-word, [[ein gekochtes Ei]] after an ein-word."},
{s:"Adjectival nouns and participles", q:"How is a present participle used as an adjective built from [[schlafen]]?", a:["das schlafende Kind","das geschlafene Kind","das schlafene Kind","das schlafend Kind"], t:"recall", c:0, e:"Infinitive + [[-d]] gives [[schlafend]], then the normal adjective ending: [[lachen]] → [[das lachende Kind]]."},
{s:"Adjectival nouns and participles", q:"Which is correct for **an official** (male, nominative)?", a:["ein Beamter","ein Beamte","ein Beamten","ein Beamtes"], t:"recall", c:0, e:"[[der Beamte]] but [[ein Beamter]]: the same weak/mixed contrast as [[der Bekannte]] / [[ein Bekannter]]."},
{s:"Adjectival nouns and participles", q:"[[Heute ist der ___ März.]] (3rd)", a:["dritte","dreite","dritten","dreiste"], t:"gap", c:0, e:"Ordinals up to 19 are number + [[-t]] + ending, but [[erste]], [[dritte]], [[siebte]] and [[achte]] are irregular; from 20 up it is [[-st]], as in [[der zwanzigste]]."},

{s:"Adverbs", q:"[[Sie singt schön.]] What does this mean?", a:["she sings beautifully","she is beautiful","she sings a beautiful song","she likes singing"], t:"rule", c:0, e:"A bare adjective after a verb is adverbial. German does not add anything for **-ly**."},
{s:"Adverbs", q:"Which points **towards** the speaker?", a:["her","hin","dort","weg"], t:"recall", c:0, e:"[[Komm her!]] come here; [[Geh hin!]] go there."},
{s:"Adverbs", q:"What does [[übermorgen]] mean?", a:["the day after tomorrow","the day before yesterday","this evening","in a moment"], t:"recall", c:0, e:"Formed from [[über]] plus [[morgen]]."},
{s:"Adverbs", q:"What does [[neulich]] mean?", a:["recently","back then","in a moment","at last"], t:"recall", c:0, e:"[[neulich]] points to the recent past; [[damals]] is the distant **back then** and [[gleich]] means **in a moment**."},
{s:"Adverbs", q:"Which adverb means **back then**?", a:["damals","neulich","danach","gleich"], t:"recall", c:0, e:"[[damals]] refers to a remote time in the past, [[danach]] means **afterwards** and [[gleich]] looks forward, not back."},
{s:"Adverbs", q:"What does [[gleich]] mean as a time adverb?", a:["in a moment","already","straight on","at last"], t:"recall", c:0, e:"[[Ich komme gleich]] means **I am coming in a moment**; **straight on** is [[geradeaus]] and **at last** is [[endlich]]."},
{s:"Adverbs", q:"Which adverb of frequency means **rarely**?", a:["selten","manchmal","meistens","täglich"], t:"recall", c:0, e:"The scale runs [[immer]] – [[meistens]] – [[oft]] – [[manchmal]] – [[selten]] – [[nie]]."},
{s:"Adverbs", q:"[[Er wohnt nicht hier, sondern ___.]] (there)", a:["dort","drinnen","oben","überall"], t:"gap", c:0, e:"[[hier]] and [[dort]] are the basic here/there pair; [[drinnen]] is **inside** and [[oben]] is **above**."},
{s:"Adverbs", q:"[[Gehen Sie immer ___!]] (straight on)", a:["geradeaus","gerade","zurück","nirgends"], t:"gap", c:0, e:"[[geradeaus]] is the direction; [[gerade]] on its own is the time adverb **just now**."},
{s:"Adverbs", q:"[[Der Kurs findet ___ statt.]] (weekly)", a:["wöchentlich","täglich","gestern","überall"], t:"gap", c:0, e:"[[täglich]] and [[wöchentlich]] are built from [[Tag]] and [[Woche]] and, like all adverbs, take no ending."},
{s:"Adverbs", q:"Why does [[schnell]] have no ending in [[Er fährt schnell]] but [[-er]] in [[ein schneller Wagen]]?", a:["Used adverbially the word modifies the verb, and adverbs never take endings","[[fahren]] is irregular and blocks adjective endings","The ending is dropped because the sentence has no article","Adverbs only take endings in the past tense"], t:"rule", c:0, e:"German uses the same word for both jobs; a bare adjective after a verb is therefore always adverbial — [[Sie singt schön]] means **she sings beautifully**."},

{s:"Adverbs of degree and attitude", q:"[[Leider ___ ich nicht kommen.]]", a:["kann","ich kann","können","zu kommen"], t:"gap", c:0, e:"An attitude adverb in first position still leaves the verb second."},
{s:"Adverbs of degree and attitude", q:"What does [[eigentlich]] mean?", a:["actually","eventually","exactly","especially"], t:"recall", c:0, e:"**Eventually** is [[schließlich]]."},
{s:"Adverbs of degree and attitude", q:"Which means **hardly**?", a:["kaum","fast","ganz","sehr"], t:"recall", c:0, e:"[[fast]] means almost, [[kaum]] means hardly."},
{s:"Adverbs of degree and attitude", q:"What does [[übrigens]] mean?", a:["by the way","actually","apparently","luckily"], t:"recall", c:0, e:"[[übrigens]] adds an aside; [[eigentlich]] is **actually**, [[anscheinend]] **apparently** and [[zum Glück]] **luckily**."},
{s:"Adverbs of degree and attitude", q:"Which adverb means **apparently**?", a:["anscheinend","wahrscheinlich","hoffentlich","vielleicht"], t:"recall", c:0, e:"[[anscheinend]] reports how things look; [[wahrscheinlich]] is **probably** and [[hoffentlich]] expresses a hope."},
{s:"Adverbs of degree and attitude", q:"Which adverb of degree means **especially**?", a:["besonders","ziemlich","völlig","sogar"], t:"recall", c:0, e:"[[besonders]] singles something out; [[ziemlich]] is **fairly**, [[völlig]] **completely** and [[sogar]] **even**."},
{s:"Adverbs of degree and attitude", q:"What does [[möglicherweise]] mean?", a:["possibly","fortunately","normally","for example"], t:"recall", c:0, e:"The [[-weise]] family: [[möglicherweise]], [[glücklicherweise]] **fortunately**, [[normalerweise]] **normally**, [[beispielsweise]] **for example**."},
{s:"Adverbs of degree and attitude", q:"[[___ hat er den Zug noch erreicht.]] (luckily)", a:["Zum Glück","Leider","Kaum","Genug"], t:"gap", c:0, e:"[[zum Glück]] and [[leider]] are opposites; note the verb still stands second even though the adverb opens the sentence."},
{s:"Adverbs of degree and attitude", q:"[[Ist das Zimmer groß ___?]] (enough)", a:["genug","zu","sehr","ziemlich"], t:"gap", c:0, e:"[[genug]] follows the adjective, while [[zu]], [[sehr]] and [[ziemlich]] all come before it: [[zu klein]], [[sehr groß]]."},
{s:"Adverbs of degree and attitude", q:"[[Wir sind ___ pünktlich angekommen.]] (fortunately)", a:["glücklicherweise","beispielsweise","normalerweise","möglicherweise"], t:"gap", c:0, e:"All four are [[-weise]] adverbs and all four fit grammatically — only the meaning decides, so learn them as a set."},
{s:"Adverbs of degree and attitude", q:"What happens to the verb when an attitude adverb such as [[leider]] opens the sentence?", a:["It still comes second, so the subject moves behind it","It moves to the end of the clause","It stays third, after the subject","It takes a comma and then normal word order"], t:"rule", c:0, e:"[[Leider kann ich nicht kommen]] — the adverb fills first position, the finite verb holds second, and the subject follows."},

/* ---------- V. Prepositions ---------- */

{s:"Prepositions by case", q:"Which preposition always takes the accusative?", a:["durch","mit","seit","bei"], t:"recall", c:0, e:"DOGFUB: durch, ohne, gegen, für, um, bis."},
{s:"Prepositions by case", q:"[[bei + dem]] contracts to…", a:["beim","beidem","bem","bei'm"], t:"recall", c:0, e:"The contractions are standard in speech unless you are pointing at something specific."},
{s:"Prepositions by case", q:"Which preposition takes the genitive?", a:["während","gegenüber","ohne","seit"], t:"recall", c:0, e:"[[während des Films]]."},
{s:"Prepositions by case", q:"[[in + das]] contracts to…", a:["ins","im","ans","aufs"], t:"recall", c:0, e:"[[in + das]] → [[ins]], but [[in + dem]] → [[im]]. The [[-s]] ending hides an accusative [[das]], so [[ins]] always points at movement into somewhere."},
{s:"Prepositions by case", q:"In [[Ich fahre zur Post]], which article is hidden inside [[zur]]?", a:["[[der]] — dative feminine","[[die]] — accusative feminine","[[dem]] — dative masculine","[[das]] — accusative neuter"], t:"rule", c:0, e:"[[zur]] = [[zu + der]]. Because [[zu]] is a dative preposition, feminine [[die Post]] becomes [[der Post]]."},
{s:"Prepositions by case", q:"[[Sie fährt jeden Morgen ___ Arbeit.]] (to work)", a:["zur","zum","zu die","nach"], t:"gap", c:0, e:"[[die Arbeit]] is feminine and [[zu]] is dative, so [[zu + der]] contracts to [[zur]]. The full form [[zu der]] survives only when you are pointing at one particular thing."},
{s:"Prepositions by case", q:"Why does [[Ich gehe in das Kino dort drüben]] keep [[in das]] rather than contracting to [[ins]]?", a:["The separate article points at one specific cinema","[[in]] can only contract in the dative","Contractions are forbidden in the accusative","The sentence is really a question"], t:"rule", c:0, e:"Contractions are the norm in speech; splitting one apart puts weight on the article, much as English stresses **that** cinema."},
{s:"Prepositions by case", q:"Which case does [[trotz]] govern in standard written German?", a:["Genitive","Dative","Accusative","Either, depending on movement"], t:"recall", c:0, e:"[[trotz]] belongs to the genitive group along with [[wegen]], [[während]] and [[statt]] — [[trotz des Regens]]."},
{s:"Prepositions by case", q:"Which of these is a two-way (Wechsel) preposition?", a:["zwischen","durch","seit","wegen"], t:"recall", c:0, e:"The nine are [[an, auf, hinter, in, neben, über, unter, vor, zwischen]]. [[durch]] is accusative, [[seit]] dative and [[wegen]] genitive."},
{s:"Prepositions by case", q:"The mnemonic DOGFUB collects prepositions that take which case?", a:["Accusative","Dative","Genitive","Whichever case the verb needs"], t:"rule", c:0, e:"DOGFUB = [[durch, ohne, gegen, für, um, bis]], all accusative. Case never follows from a preposition's meaning, so the two have to be learnt as one item."},
{s:"Prepositions by case", q:"[[Sie kommt gerade ___ Supermarkt.]] (from the supermarket)", a:["vom","zum","beim","im"], t:"gap", c:0, e:"[[von + dem]] → [[vom]]. [[zum]] would send her there, [[beim]] would leave her standing at it and [[im]] would put her inside."},

{s:"Accusative prepositions", q:"[[Ich habe es ___ meinen Bruder gekauft.]]", a:["für","mit","von","bei"], t:"gap", c:0, e:"[[für]] is accusative."},
{s:"Accusative prepositions", q:"Which accusative preposition follows its noun?", a:["entlang","durch","gegen","um"], t:"recall", c:0, e:"[[die Straße entlang]]."},
{s:"Accusative prepositions", q:"[[Er kam ___ acht.]] (around eight)", a:["gegen","um","bis","für"], t:"gap", c:0, e:"[[um]] is exactly eight; [[gegen]] is approximately."},
{s:"Accusative prepositions", q:"[[bis zum Bahnhof]] is dative, although [[bis]] is an accusative preposition. Why?", a:["a second preposition takes over and sets the case","[[bis]] is an exception","[[Bahnhof]] is masculine","it is a fixed phrase"], t:"rule", c:0, e:"[[bis]] often pairs with another preposition, and that one governs the case."},
{s:"Accusative prepositions", q:"[[Wir gehen durch ___ Park.]] ([[der Park]])", a:["den","dem","der","des"], t:"gap", c:0, e:"[[durch]] always takes the accusative, so masculine [[der Park]] becomes [[den Park]]."},
{s:"Accusative prepositions", q:"[[Ich gehe nicht ohne ___ Bruder.]] (without my brother)", a:["meinen","meinem","mein","meines"], t:"gap", c:0, e:"[[ohne]] is accusative, and the masculine accusative adds [[-en]] to [[mein]]. Compare the dative [[außer meinem Bruder]]."},
{s:"Accusative prepositions", q:"[[gegen]] appears in both [[gegen die Wand]] and [[gegen acht]]. Which case does it take in each?", a:["Accusative in both","Accusative for place, dative for time","Dative in both","Accusative for place, genitive for time"], t:"rule", c:0, e:"An accusative preposition keeps the accusative whatever it means — [[gegen]] shifts from **against** to **around** without changing case."},
{s:"Accusative prepositions", q:"Why is [[Ich fahre ohne Auto]] more usual than [[ohne ein Auto]]?", a:["[[ohne]] normally drops the article altogether","[[Auto]] cannot take an article","[[ohne]] takes the genitive, which has no article","Articles disappear after every preposition"], t:"rule", c:0, e:"[[ohne Geld]], [[ohne Auto]], [[ohne Arbeit]] — the bare noun is the default, and an article is added only to stress **one particular** thing."},
{s:"Accusative prepositions", q:"[[wider]], as in [[wider besseres Wissen]], means…", a:["contrary to","once again","next to","in spite of"], t:"recall", c:0, e:"[[wider]] is formal and rare. Do not confuse it with [[wieder]] (**again**), which is not a preposition at all."},
{s:"Accusative prepositions", q:"Which case does [[bis]] take when it stands on its own?", a:["Accusative","Dative","Genitive","It varies with the noun"], t:"recall", c:0, e:"[[bis nächsten Freitag]] is accusative, and [[bis]] usually appears with no article at all."},
{s:"Accusative prepositions", q:"Which of these is NOT an accusative preposition?", a:["seit","durch","ohne","um"], t:"recall", c:0, e:"[[seit]] is dative — [[seit einem Jahr]]. The accusative set is [[durch, für, gegen, ohne, um, bis, entlang, wider]]."},
{s:"Accusative prepositions", q:"In time expressions, which of these means **until**?", a:["bis","um","gegen","für"], t:"recall", c:0, e:"[[um]] gives exact clock time, [[gegen]] approximates it, [[für]] measures a planned span and [[bis]] marks the end point."},

{s:"Dative prepositions", q:"Which is correct for going to Berlin?", a:["nach Berlin","zu Berlin","in Berlin","an Berlin"], t:"rule", c:0, e:"[[nach]] for places that take no article; [[zu]] for people and businesses."},
{s:"Dative prepositions", q:"[[Ich wohne ___ drei Jahren hier.]]", a:["seit","für","ab","von"], t:"gap", c:0, e:"[[seit]] + present tense where English uses the perfect."},
{s:"Dative prepositions", q:"Which means \"at home\"?", a:["zu Hause","nach Hause","in Hause","bei Hause"], t:"recall", c:0, e:"[[nach Hause]] is homewards; [[zu Hause]] is at home."},
{s:"Dative prepositions", q:"[[Ich fahre mit ___ Bus in die Stadt.]] ([[der Bus]])", a:["dem","den","der","das"], t:"gap", c:0, e:"[[mit]] is always dative, so [[der]] becomes [[dem]]. [[mit dem Bus]], [[mit dem Auto]], [[mit der Bahn]] is how German says **by**."},
{s:"Dative prepositions", q:"[[Er wohnt noch bei ___ Eltern.]] (his parents)", a:["seinen","seine","seinem","seiner"], t:"gap", c:0, e:"The dative plural takes [[-en]] on the determiner, and the noun normally adds [[-n]] too — [[Eltern]] already ends in one."},
{s:"Dative prepositions", q:"Which dative preposition expresses origin, as in [[___ der Schweiz]]?", a:["aus","von","seit","ab"], t:"recall", c:0, e:"[[aus]] says where someone or something comes from; [[von]] gives a starting point or a sender, as in [[vom Bahnhof]]."},
{s:"Dative prepositions", q:"[[Alle sind da außer ___ Bruder.]] (except my brother)", a:["meinem","meinen","mein","meines"], t:"gap", c:0, e:"[[außer]] is dative, so masculine [[mein]] takes [[-em]]. The English **except** gives no clue — only the preposition does."},
{s:"Dative prepositions", q:"Why [[zum Arzt]] but [[nach Berlin]]?", a:["[[zu]] goes with people and businesses, [[nach]] with places that take no article","[[zu]] is for movement and [[nach]] for position","[[nach]] is only used with the perfect tense","[[zu]] is dative and [[nach]] accusative"], t:"rule", c:0, e:"Both are dative. Watch the pair [[nach Hause]] (**homewards**) against [[zu Hause]] (**at home**)."},
{s:"Dative prepositions", q:"Which dative preposition often comes after its noun, as in [[dem Bahnhof ___]]?", a:["gegenüber","außer","seit","ab"], t:"recall", c:0, e:"[[gegenüber]] (**opposite**) may go before or after a noun, but after a pronoun it always follows: [[mir gegenüber]]."},
{s:"Dative prepositions", q:"[[ab nächster Woche]] means…", a:["from next week onwards","by next week at the latest","since last week","for one week only"], t:"recall", c:0, e:"[[ab]] opens a stretch of time running forwards; [[seit]] opens one running back from now."},
{s:"Dative prepositions", q:"[[Ich fahre mit dem Bus nach Köln]] — the bus is clearly moving, so why the dative?", a:["[[mit]] is a dative preposition and never changes","Vehicles always take the dative","Movement only forces the accusative in the perfect","[[Bus]] is masculine, which blocks the accusative"], t:"rule", c:0, e:"Only the nine two-way prepositions let movement decide the case. Everywhere else the preposition itself fixes it."},

{s:"Two-way prepositions", q:"[[Ich hänge das Bild an ___ Wand.]] (I hang it on the wall)", a:["die","der","dem","den"], t:"gap", c:0, e:"Movement into a new place → accusative [[die Wand]]."},
{s:"Two-way prepositions", q:"[[Das Bild hängt an ___ Wand.]]", a:["der","die","dem","den"], t:"gap", c:0, e:"Position, not movement → dative [[der Wand]]."},
{s:"Two-way prepositions", q:"Which verb signals the accusative in a two-way pair?", a:["stellen","stehen","liegen","sitzen"], t:"recall", c:0, e:"[[stellen, legen, setzen]] put something somewhere; their partners describe where it is."},
{s:"Two-way prepositions", q:"What decides the case after a two-way preposition?", a:["whether there is movement into a new place","the gender of the noun","the tense of the verb","the position in the sentence"], t:"rule", c:0, e:"Accusative for [[wohin?]], dative for [[wo?]]"},
{s:"Two-way prepositions", q:"[[Die Kinder laufen in ___ Garten.]] (out into the garden)", a:["den","dem","der","das"], t:"gap", c:0, e:"They cross into a new place — [[Wohin?]] — so [[in]] takes the accusative [[den Garten]]."},
{s:"Two-way prepositions", q:"[[Die Kinder spielen ___ Garten.]] (in the garden)", a:["im","ins","in den","in die"], t:"gap", c:0, e:"Playing is [[Wo?]], so the dative, and [[in + dem]] contracts to [[im]]. [[ins]] would push them through the gate."},
{s:"Two-way prepositions", q:"[[Sie geht im Zimmer auf und ab]] takes the dative although she is walking. Why?", a:["The movement stays inside one place, so it counts as [[Wo?]]","[[gehen]] always takes the dative","[[auf und ab]] forces the dative","Only vehicles trigger the accusative"], t:"rule", c:0, e:"The accusative marks crossing a boundary into somewhere new; pacing about inside a room crosses nothing."},
{s:"Two-way prepositions", q:"[[vor einem Jahr]] (**a year ago**) is dative although nothing moves. Why?", a:["Used non-spatially these prepositions have one fixed case","Time phrases are always dative in German","[[vor]] is not really a two-way preposition","[[Jahr]] is neuter and neuters take the dative"], t:"rule", c:0, e:"The Wohin/Wo test only applies to real places. Away from space the case is simply part of the expression and must be learnt with it."},
{s:"Two-way prepositions", q:"In the fixed expression [[sich auf etwas freuen]], [[auf]] takes…", a:["the accusative, always","the dative, always","the accusative for future events, the dative for past ones","whichever case the noun suggests"], t:"recall", c:0, e:"[[Ich freue mich auf den Sommer.]] The same goes for [[an etwas denken]] — non-spatial uses lock the accusative."},
{s:"Two-way prepositions", q:"[[Er stellt die Flasche zwischen ___ Gläser.]] (between the glasses)", a:["die","den","der","dem"], t:"gap", c:0, e:"[[stellen]] puts something somewhere new, so the accusative plural [[die Gläser]]. Standing there already would give [[zwischen den Gläsern]]."},
{s:"Two-way prepositions", q:"[[Häng die Jacke bitte in den Schrank!]] — why the accusative [[den]]?", a:["The jacket ends up somewhere it was not before","Imperatives always take the accusative","[[Schrank]] is masculine, which forces the accusative","[[hängen]] is accusative in every sense"], t:"rule", c:0, e:"[[hängen]] belongs to both families: as an action beside [[stellen, legen, setzen]] it is accusative, as a state beside [[stehen, liegen, sitzen]] it is dative — [[Die Jacke hängt im Schrank.]]"},
{s:"Two-way prepositions", q:"[[an]] and [[auf]] both translate as **on**. What separates them?", a:["[[an]] for vertical surfaces, [[auf]] for horizontal ones","[[an]] for horizontal, [[auf]] for vertical","[[an]] takes the accusative and [[auf]] the dative","[[an]] is for people and [[auf]] for objects"], t:"recall", c:0, e:"[[an der Wand]] but [[auf dem Tisch]]. Both still pick their case by the Wohin/Wo test."},
{s:"Two-way prepositions", q:"[[Er hängt das Bild an die Wand.]] Where is the picture now?", a:["being put onto the wall","already hanging on the wall","leaning against the wall","behind the wall"], t:"rule", c:0, e:"[[an die Wand]] is accusative, so it describes the movement to a new place, not the resting position."},
{s:"Two-way prepositions", q:"[[Das Bild hängt an der Wand.]] and [[Er hängt das Bild an die Wand.]] — what separates them?", a:["dative describes where it is, accusative where it goes","nothing, both are correct spellings","the first is plural","the second is past tense"], t:"rule", c:0, e:"The case, not the preposition, carries the difference between location and destination."},
{s:"Two-way prepositions", q:"[[Die Kinder laufen in der Halle.]] What are they doing?", a:["running about inside the hall","running into the hall","running past the hall","leaving the hall"], t:"rule", c:0, e:"Dative [[in der Halle]] means the running happens within the hall. Accusative [[in die Halle]] would be entering it."},

{s:"Genitive prepositions", q:"[[___ des schlechten Wetters]] (because of)", a:["wegen","gegen","durch","seit"], t:"gap", c:0, e:"[[wegen]] takes the genitive in standard written German."},
{s:"Genitive prepositions", q:"[[___ einer Woche]] (within a week)", a:["innerhalb","außerhalb","während","trotz"], t:"gap", c:0, e:"[[innerhalb]] is within, [[außerhalb]] outside."},
{s:"Genitive prepositions", q:"As a one-word reply, [[Meinetwegen!]] means…", a:["fine by me","because of me","instead of me","without me"], t:"recall", c:0, e:"[[wegen]] fuses with pronouns into fixed forms; as a reply it signals indifferent agreement."},
{s:"Genitive prepositions", q:"You often hear [[wegen dem Wetter]]. Is that standard?", a:["common in speech but not standard","fully standard","never heard","standard only in Austria"], t:"rule", c:0, e:"[[wegen]], [[trotz]], [[während]] and [[statt]] take the genitive in writing."},
{s:"Genitive prepositions", q:"[[___ des Films bin ich eingeschlafen.]] (during)", a:["Während","Wegen","Trotz","Statt"], t:"gap", c:0, e:"[[während]] marks a stretch of time. All four take the genitive, but they give time, cause, concession and substitution respectively."},
{s:"Genitive prepositions", q:"[[Trotz ___ Kälte gehen wir spazieren.]] ([[die Kälte]])", a:["der","die","dem","des"], t:"gap", c:0, e:"The feminine genitive is [[der]] — identical to the feminine dative, which is why the genitive here is so easy to miss."},
{s:"Genitive prepositions", q:"[[Er schrieb statt ___ Briefes eine E-Mail.]] ([[der Brief]])", a:["eines","einem","einen","einer"], t:"gap", c:0, e:"Masculine and neuter genitive take [[-es]] on the determiner and [[-s]] or [[-es]] on the noun itself: [[eines Briefes]]."},
{s:"Genitive prepositions", q:"[[jenseits der Grenze]] means…", a:["beyond the border","this side of the border","below the border","in view of the border"], t:"recall", c:0, e:"[[diesseits]] and [[jenseits]] are a pair: **this side of** and **the far side of**."},
{s:"Genitive prepositions", q:"Which genitive preposition means **on the basis of**?", a:["aufgrund","angesichts","oberhalb","innerhalb"], t:"recall", c:0, e:"[[aufgrund der Daten]] introduces evidence; [[angesichts der Lage]] introduces a situation you are responding to."},
{s:"Genitive prepositions", q:"[[wegen]] plus [[er]] produces which fixed form?", a:["seinetwegen","wegen seiner","seinwegen","seinerwegen"], t:"recall", c:0, e:"[[wegen]] fuses with pronouns: [[meinetwegen, deinetwegen, seinetwegen, unsertwegen]]. The loose [[wegen ihm]] is heard but not careful German."},
{s:"Genitive prepositions", q:"[[Der Parkplatz liegt ___ des Zentrums.]] (outside of)", a:["außerhalb","innerhalb","oberhalb","diesseits"], t:"gap", c:0, e:"The [[-halb]] group works in pairs: [[außerhalb]] against [[innerhalb]], [[oberhalb]] against [[unterhalb]]."},
{s:"Genitive prepositions", q:"[[Angesichts der Lage]] — why [[der]] and not [[die]]?", a:["[[angesichts]] takes the genitive, and [[die Lage]] becomes [[der Lage]]","[[angesichts]] takes the dative","[[Lage]] is masculine","[[angesichts]] always takes [[der]] whatever the gender"], t:"rule", c:0, e:"A feminine noun looks unchanged in the genitive; only the article shifts, from [[die]] to [[der]]."},

/* ---------- VI. Verbs ---------- */

{s:"Present tense — regular endings", q:"[[du arbeit___]]", a:["est","st","et","t"], t:"gap", c:0, e:"Stems ending in [[-d]] or [[-t]] insert an [[e]] before the ending."},
{s:"Present tense — regular endings", q:"[[du heiß___]]", a:["t","st","est","et"], t:"gap", c:0, e:"Stems in [[-s, -ß, -z, -x]] take only [[-t]] in the du form."},
{s:"Present tense — regular endings", q:"[[ich spiele]] can mean…", a:["all three of I play / am playing / do play","only I play","only I am playing","only I do play"], t:"rule", c:0, e:"German has a single present tense; add [[gerade]] to stress the moment."},
{s:"Present tense — regular endings", q:"[[Ihr ___ Fußball.]] ([[spielen]])", a:["spielt","spielst","spielen","spiele"], t:"gap", c:0, e:"[[ihr]] takes \"-t\", the same ending as [[er/sie/es]] — only four endings exist and three of them repeat."},
{s:"Present tense — regular endings", q:"[[Du ___ sehr gut.]] ([[tanzen]])", a:["tanzt","tanzst","tanzest","tanzen"], t:"gap", c:0, e:"A stem ending in -s, -ß, -z, -x or -tz already contains the s of \"-st\", so [[du]] adds only \"-t\": [[du tanzt]]."},
{s:"Present tense — regular endings", q:"[[Er ___ das Fenster.]] ([[öffnen]])", a:["öffnet","öffnt","öffnst","öffnen"], t:"gap", c:0, e:"Stems in -d, -t, -chn, -ffn or -gn slip an e in before the ending, otherwise the -t would be unpronounceable."},
{s:"Present tense — regular endings", q:"What is the [[du]] form of [[reisen]] (**to travel**)?", a:["reist","reisest","reisst","reisen"], t:"recall", c:0, e:"[[reis-]] ends in -s, so the [[du]] ending shrinks to \"-t\" — the same rule that gives [[du heißt]]."},
{s:"Present tense — regular endings", q:"Which pronoun takes the same present-tense ending as [[er/sie/es]]?", a:["ihr","wir","du","sie (plural)"], t:"recall", c:0, e:"Both [[er]] and [[ihr]] take \"-t\", which is why [[er spielt]] and [[ihr spielt]] look identical."},
{s:"Present tense — regular endings", q:"Why is it [[du findest]] and not [[du findst]]?", a:["the stem ends in -d, so an e is inserted before the ending","[[finden]] is a stem-changing verb","all [[du]] forms in German end in -est","the e marks a question"], t:"rule", c:0, e:"The inserted e is purely for pronounceability and shows up in [[er findet]] too, not just [[du findest]]."},
{s:"Present tense — regular endings", q:"The formal [[Sie]] always borrows which form?", a:["the 3rd person plural","the 2nd person singular","the 1st person singular","the 2nd person plural"], t:"rule", c:0, e:"[[Sie haben]] and [[sie haben]] are identical in every tense — only the capital letter tells them apart."},

{s:"Stem-changing verbs", q:"[[er ___]] from [[nehmen]]", a:["nimmt","nehmt","nehmet","nahm"], t:"gap", c:0, e:"[[nehmen]] is irregular: [[du nimmst, er nimmt]]."},
{s:"Stem-changing verbs", q:"Which forms show the stem change?", a:["du and er/sie/es","all six","only er/sie/es","the plural"], t:"rule", c:0, e:"The plural is always regular: [[wir fahren, ihr fahrt]]."},
{s:"Stem-changing verbs", q:"[[er ___]] from [[sehen]]", a:["sieht","seht","siehen","sah"], t:"gap", c:0, e:"e → ie in the du and er forms."},
{s:"Stem-changing verbs", q:"[[Du ___ viel zu schnell.]] ([[fahren]])", a:["fährst","fahrst","fährest","fährt"], t:"gap", c:0, e:"[[fahren]] is an a → ä verb, and the umlaut appears in exactly two forms: [[du fährst]] and [[er fährt]]."},
{s:"Stem-changing verbs", q:"[[Wir ___ jeden Morgen im Park.]] ([[laufen]])", a:["laufen","läufen","läuft","lauft"], t:"gap", c:0, e:"The stem change never touches the plural — [[wir laufen]], [[ihr lauft]], [[sie laufen]] are all regular."},
{s:"Stem-changing verbs", q:"[[Er ___ mir das Buch.]] ([[geben]])", a:["gibt","gebt","gibst","gebet"], t:"gap", c:0, e:"[[geben]] is an e → i verb; [[gebt]] is the [[ihr]] form, where the vowel stays put."},
{s:"Stem-changing verbs", q:"What is the [[er]] form of [[helfen]]?", a:["hilft","helft","hilfst","hälft"], t:"recall", c:0, e:"[[helfen]] shifts e → i like [[geben]] and [[sprechen]]; [[helft]] is what [[ihr]] does."},
{s:"Stem-changing verbs", q:"What is the [[du]] form of [[lesen]]?", a:["liest","lesest","lest","liesst"], t:"recall", c:0, e:"Two rules stack here: e → ie gives the stem [[lies-]], and a stem in -s means [[du]] adds only -t."},
{s:"Stem-changing verbs", q:"Which vowel change does [[laufen]] show?", a:["au → äu","a → ä","e → i","e → ie"], t:"rule", c:0, e:"[[laufen]] and [[saufen]] are the everyday au → äu pair: [[du läufst]], [[er läuft]]."},
{s:"Stem-changing verbs", q:"Which verbs keep their stem change in the [[du]] imperative?", a:["e → i verbs, as in [[Gib!]] and [[Sprich!]]","a → ä verbs, as in [[Fähr!]]","all stem-changing verbs","none — the imperative is always regular"], t:"rule", c:0, e:"The umlaut of a → ä verbs is dropped in the imperative ([[Fahr!]]), but the e → i shift survives."},

{s:"haben, sein, werden", q:"[[ihr ___]] from [[sein]]", a:["seid","sind","seit","bist"], t:"gap", c:0, e:"[[seid]] with a d — [[seit]] with a t is the preposition."},
{s:"haben, sein, werden", q:"What is the Präteritum [[ihr]] form of [[sein]]?", a:["wart","seid","waren","wurdet"], t:"recall", c:0, e:"[[ich war, du warst, er war, wir waren, ihr wart, sie waren]]."},
{s:"haben, sein, werden", q:"Which auxiliary does [[werden]] take in the perfect?", a:["sein","haben","werden","either"], t:"recall", c:0, e:"[[Er ist Arzt geworden]]."},
{s:"haben, sein, werden", q:"[[Du ___ mein bester Freund.]] ([[sein]])", a:["bist","bin","seid","bester"], t:"gap", c:0, e:"[[sein]] is the most irregular verb in German: [[bin, bist, ist, sind, seid, sind]] — worth learning as a chant."},
{s:"haben, sein, werden", q:"[[Es ___ langsam kalt.]] ([[werden]])", a:["wird","werdet","wirst","geworden"], t:"gap", c:0, e:"Here [[werden]] means **to become**; the [[er/sie/es]] form shifts e → i and takes no ending at all — [[wird]], not [[werdet]]."},
{s:"haben, sein, werden", q:"[[Wir ___ letztes Jahr in Wien.]] (Präteritum of [[sein]])", a:["waren","warten","sind","wurden"], t:"gap", c:0, e:"[[sein]] is one of the few verbs Germans use in the Präteritum even when speaking: [[ich war]], [[wir waren]]."},
{s:"haben, sein, werden", q:"What is the Partizip II of [[sein]]?", a:["gewesen","gesein","geseint","gewest"], t:"recall", c:0, e:"[[sein]] takes itself as its own auxiliary: [[Ich bin dort gewesen]]."},
{s:"haben, sein, werden", q:"What is the Konjunktiv II of [[haben]]?", a:["hätte","hatte","häbe","habte"], t:"recall", c:0, e:"The Konjunktiv II is the Präteritum [[hatte]] plus an umlaut — the same trick gives [[war]] → [[wäre]]."},
{s:"haben, sein, werden", q:"Complete the Präteritum of [[haben]]: [[ich hatte]], [[du ___]]", a:["hattest","hastest","hattst","hatest"], t:"recall", c:0, e:"[[haben]] builds a weak Präteritum on the shortened stem [[hat-]]: [[hatte, hattest, hatte, hatten]]."},
{s:"haben, sein, werden", q:"In which sentence is [[werden]] the passive auxiliary?", a:["[[Das Haus wird gebaut.]]","[[Ich werde gehen.]]","[[Er wird Arzt.]]","[[Es wird kalt.]]"], t:"rule", c:0, e:"[[werden]] does three jobs — **become**, future, passive. Only a following Partizip II makes it passive."},

{s:"Modal verbs", q:"[[ich ___]] from [[müssen]]", a:["muss","musse","müss","musst"], t:"gap", c:0, e:"The ich and er forms of a modal are identical and take no ending."},
{s:"Modal verbs", q:"What does [[Ich muss nicht gehen]] mean?", a:["I don't have to go","I must not go","I can't go","I shouldn't go"], t:"rule", c:0, e:"For \"must not\" use [[nicht dürfen]]."},
{s:"Modal verbs", q:"Where does the second verb go?", a:["to the end, as a bare infinitive","directly after the modal","first","it takes zu"], t:"rule", c:0, e:"[[Ich muss morgen früh aufstehen.]]"},
{s:"Modal verbs", q:"[[Wir ___ heute Abend ins Kino gehen.]] ([[wollen]])", a:["wollen","wollt","will","willst"], t:"gap", c:0, e:"The [[wir]] and [[sie]] forms of every modal are identical to the infinitive; [[ihr]] adds -t ([[ihr wollt]]) — only the singular is odd."},
{s:"Modal verbs", q:"[[Du ___ hier nicht rauchen.]] (**you are not allowed to**)", a:["darfst","dürfst","durfst","darf"], t:"gap", c:0, e:"**Must not** is [[nicht dürfen]], never [[nicht müssen]] — and the singular of [[dürfen]] drops the umlaut."},
{s:"Modal verbs", q:"[[Ich ___ einen Tee, bitte.]] (**would like**)", a:["möchte","mag","muss","möchten"], t:"gap", c:0, e:"[[möchten]] is the polite way to order or ask; [[Ich mag Kaffee]] states a taste rather than a request."},
{s:"Modal verbs", q:"What is the [[er]] form of [[können]]?", a:["kann","könnt","kannt","kanne"], t:"recall", c:0, e:"Modals take no ending at all in the [[er]] form — [[er kann]], never [[er kannt]]; [[könnt]] belongs to [[ihr]]."},
{s:"Modal verbs", q:"Which modal means **should, be supposed to**?", a:["sollen","wollen","dürfen","mögen"], t:"recall", c:0, e:"[[sollen]] reports an outside expectation: [[Du sollst warten]] — someone else has decided it."},
{s:"Modal verbs", q:"Why is it [[er will]] and not [[er willt]]?", a:["modals take no ending in the ich and er forms","[[wollen]] is a separable verb","the -t is only added in questions","[[wollen]] has no 3rd person"], t:"rule", c:0, e:"The [[ich]] and [[er]] forms of a modal are always identical and always bare: [[ich muss]] / [[er muss]]."},
{s:"Modal verbs", q:"Which sentence is correct?", a:["[[Ich will ein Auto kaufen.]]","[[Ich will ein Auto zu kaufen.]]","[[Ich will kaufen ein Auto.]]","[[Ich will ein Auto gekauft.]]"], t:"rule", c:0, e:"After a modal the second verb is a bare infinitive at the end of the clause — no [[zu]] and no participle."},
{s:"Modal verbs", q:"[[Du musst nicht kommen.]] What does this tell the listener?", a:["they are not obliged to come","they are forbidden to come","they must stay away","they should come"], t:"rule", c:0, e:"Negated [[müssen]] removes an obligation. Forbidding it needs [[Du darfst nicht kommen]]."},
{s:"Modal verbs", q:"[[Er darf nicht rauchen.]] and [[Er muss nicht rauchen.]] — which one forbids?", a:["the first","the second","both","neither"], t:"rule", c:0, e:"[[dürfen]] is permission, so its negative bans; [[müssen]] is obligation, so its negative merely releases."},
{s:"Modal verbs", q:"[[Sie will Ärztin werden.]] What does [[will]] mean?", a:["she wants to","she will, as a prediction","she is allowed to","she is able to"], t:"rule", c:0, e:"A false friend in disguise: [[wollen]] is to want. Future [[will]] in English is German [[wird]]."},

{s:"Separable and inseparable verbs", q:"[[Ich ___ um sechs ___.]] ([[aufstehen]], main clause)", a:["stehe … auf","aufstehe … —","stehe auf … —","auf … stehe"], t:"gap", c:0, e:"The stressed prefix detaches and moves to the end of the clause."},
{s:"Separable and inseparable verbs", q:"What is the Partizip II of [[verstehen]]?", a:["verstanden","geverstanden","verstehgt","gestanden"], t:"recall", c:0, e:"Inseparable verbs form the participle without [[ge-]]."},
{s:"Separable and inseparable verbs", q:"Which prefix is always inseparable?", a:["ver-","auf-","mit-","zurück-"], t:"recall", c:0, e:"be-, emp-, ent-, er-, ge-, miss-, ver-, zer- never detach."},
{s:"Separable and inseparable verbs", q:"[[..., weil ich um sechs ___.]] ([[aufstehen]])", a:["aufstehe","stehe auf","auf stehe","aufstehen"], t:"gap", c:0, e:"In a subordinate clause the whole verb goes to the end, so the prefix rejoins the stem: [[aufstehe]]."},
{s:"Separable and inseparable verbs", q:"[[Ich versuche, früh ___.]] ([[aufstehen]])", a:["aufzustehen","zu aufstehen","aufstehen zu","aufgestanden"], t:"gap", c:0, e:"With a separable verb the [[zu]] is buried between prefix and stem — one word, [[aufzustehen]]."},
{s:"Separable and inseparable verbs", q:"[[Ich rufe dich morgen ___.]] ([[anrufen]])", a:["an","auf","ab","zu"], t:"gap", c:0, e:"In a main clause the stressed prefix is stranded at the very end, however long the sentence gets."},
{s:"Separable and inseparable verbs", q:"What is the Partizip II of [[anrufen]]?", a:["angerufen","geanrufen","angeruft","anrufen"], t:"recall", c:0, e:"A separable verb wraps its [[ge-]] inside: prefix + [[ge]] + rest, just like [[aufgestanden]]."},
{s:"Separable and inseparable verbs", q:"Which participle is formed **without** [[ge-]]?", a:["umarmt (from [[umarmen]])","angerufen (from [[anrufen]])","aufgestanden (from [[aufstehen]])","mitgebracht (from [[mitbringen]])"], t:"recall", c:0, e:"In [[umarmen]] the prefix [[um-]] is unstressed and therefore inseparable, and inseparable verbs never take [[ge-]]."},
{s:"Separable and inseparable verbs", q:"What decides whether a prefix detaches from its verb?", a:["where the stress falls","the case of the object","whether the verb is strong or weak","the length of the prefix"], t:"rule", c:0, e:"Stressed prefix ([[ab-, an-, auf-, mit-]]) separates; unstressed ([[be-, er-, ver-, zer-]]) never does."},
{s:"Separable and inseparable verbs", q:"[[Er übersetzt den Text ins Deutsche.]] — does [[über-]] separate here?", a:["No — the stress is on the stem, so the prefix stays put","Yes — every [[über-]] verb separates","Yes, but only in subordinate clauses","No — [[über-]] is a preposition, not a prefix"], t:"rule", c:0, e:"[[über-]] is a dual prefix: stressed it means **ferry across** and splits, unstressed it means **translate** and does not."},
{s:"Separable and inseparable verbs", q:"[[Er ruft seine Mutter an.]] What is he doing?", a:["phoning her","shouting at her","calling her over","naming her"], t:"rule", c:0, e:"The prefix at the end changes everything: [[rufen]] is to shout, [[anrufen]] is to telephone. You cannot know until the clause ends."},
{s:"Separable and inseparable verbs", q:"[[Sie gibt jeden Monat viel Geld aus.]] What does she do with the money?", a:["spends it","gives it away","returns it","saves it"], t:"rule", c:0, e:"[[ausgeben]] is to spend. [[geben]] alone would be to give, and [[zurückgeben]] to give back."},
{s:"Separable and inseparable verbs", q:"[[Der Zug fährt um acht Uhr ab.]] What happens at eight?", a:["it departs","it arrives","it passes through","it is cancelled"], t:"rule", c:0, e:"[[abfahren]] is to depart; [[ankommen]] would be to arrive. The prefix waits until the end of the clause."},
{s:"Separable and inseparable verbs", q:"Why must you read a German main clause to the end before translating the verb?", a:["a separable prefix there can change the verb's meaning entirely","the subject appears at the end","German verbs have no meaning alone","the tense is marked at the end"], t:"rule", c:0, e:"[[Er sieht fern]] is watching television, not seeing something distant."},

/* ---------- VII. Tenses ---------- */

{s:"The tenses at a glance", q:"Which past tense dominates spoken German?", a:["Perfekt","Präteritum","Plusquamperfekt","Futur II"], t:"recall", c:0, e:"The Präteritum belongs to writing, apart from [[sein]], [[haben]] and the modals."},
{s:"The tenses at a glance", q:"How is the future usually expressed in conversation?", a:["present tense plus a time word","werden + Infinitiv","Futur II","Konjunktiv II"], t:"rule", c:0, e:"[[Ich gehe morgen ins Kino]]. [[werden]] is for predictions and promises."},
{s:"The tenses at a glance", q:"[[Ich werde gespielt haben]] is which tense?", a:["Futur II","Futur I","Plusquamperfekt","Perfekt"], t:"rule", c:0, e:"werden + Partizip II + haben/sein."},
{s:"The tenses at a glance", q:"[[Es ___ bestimmt regnen.]] (a genuine prediction)", a:["wird","würde","wurde","werdet"], t:"gap", c:0, e:"[[werden]] is reserved for real predictions, promises and assumptions — everyday plans just use the present."},
{s:"The tenses at a glance", q:"[[Ich ___ nächste Woche nach Hamburg.]] (the normal way to talk about next week)", a:["fahre","werde","fuhr","bin gefahren"], t:"gap", c:0, e:"Präsens plus a time word is the standard German future — [[werden]] would sound like a solemn promise."},
{s:"The tenses at a glance", q:"[[ich spielte]] is which tense?", a:["Präteritum","Perfekt","Plusquamperfekt","Futur I"], t:"recall", c:0, e:"The Präteritum is the one-word past: stem plus a past ending, no auxiliary anywhere."},
{s:"The tenses at a glance", q:"[[ich hatte gespielt]] is which tense?", a:["Plusquamperfekt","Perfekt","Präteritum","Futur II"], t:"recall", c:0, e:"Swap the auxiliary from [[habe]] to [[hatte]] and the Perfekt becomes the Plusquamperfekt."},
{s:"The tenses at a glance", q:"Which verbs prefer the Präteritum even in speech?", a:["[[sein]], [[haben]] and the modals","verbs of motion","separable verbs","reflexive verbs"], t:"rule", c:0, e:"[[Ich war müde]] and [[Ich musste gehen]] sound natural spoken; [[Ich bin müde gewesen]] sounds heavy."},
{s:"The tenses at a glance", q:"You are writing a narrative report about the past. Which tense?", a:["Präteritum","Perfekt","Plusquamperfekt","Präsens"], t:"rule", c:0, e:"The split is medium, not meaning: Perfekt for speaking, Präteritum for writing — both translate the same English."},
{s:"The tenses at a glance", q:"When should you actually reach for [[werden]] + Infinitiv?", a:["for genuine predictions, promises and assumptions","for anything happening tomorrow","whenever the sentence has a time word","to report what someone else said"], t:"rule", c:0, e:"[[Sie wird schon zu Hause sein]] is an assumption about now, not a statement about the future at all."},

{s:"Perfekt", q:"[[Ich ___ nach Berlin gefahren.]]", a:["bin","habe","werde","war"], t:"gap", c:0, e:"Verbs of motion take [[sein]]."},
{s:"Perfekt", q:"What is the Partizip II of [[studieren]]?", a:["studiert","gestudiert","gestudieren","studierte"], t:"recall", c:0, e:"Verbs in [[-ieren]] take no [[ge-]]."},
{s:"Perfekt", q:"[[Ich habe das Auto gefahren]] — why [[haben]]?", a:["there is a direct object","[[fahren]] is weak","it is a mistake","[[Auto]] is neuter"], t:"rule", c:0, e:"With an accusative object the auxiliary is [[haben]], even for a motion verb."},
{s:"Perfekt", q:"[[Das Kind ___ sofort eingeschlafen.]]", a:["ist","hat","warst","wird"], t:"gap", c:0, e:"[[einschlafen]] is a change of state, and changes of state take [[sein]] just as changes of place do."},
{s:"Perfekt", q:"[[Wir ___ gestern Pizza gegessen.]]", a:["haben","sind","waren","hattet"], t:"gap", c:0, e:"[[Pizza]] is a direct object, so the verb is transitive and the auxiliary can only be [[haben]]."},
{s:"Perfekt", q:"[[Ich ___ mich schon gewaschen.]]", a:["habe","bin","war","hattest"], t:"gap", c:0, e:"Every reflexive verb takes [[haben]] in the Perfekt, no matter what the verb means."},
{s:"Perfekt", q:"What is the Partizip II of [[arbeiten]]?", a:["gearbeitet","gearbeitt","gearbeiten","arbeitet"], t:"recall", c:0, e:"Weak verbs with a stem in -d or -t take \"-et\" rather than \"-t\", exactly as they do in the present."},
{s:"Perfekt", q:"Complete the pattern: [[machen]] → [[gemacht]], [[sprechen]] → ___", a:["gesprochen","gesprecht","gesprochet","gesprach"], t:"recall", c:0, e:"Strong verbs end in \"-en\" and usually change their vowel too — the pair must simply be learnt."},
{s:"Perfekt", q:"Why does [[bleiben]] take [[sein]] although nobody moves?", a:["it is one of the three specials — [[sein]], [[bleiben]], [[werden]]","staying counts as a change of place","it has no accusative object, so [[sein]] is automatic","its participle begins with [[ge-]]"], t:"rule", c:0, e:"[[sein]], [[bleiben]] and [[werden]] are learnt as exceptions; every other [[sein]]-verb means motion or transformation."},
{s:"Perfekt", q:"What do all the [[sein]]-verbs have in common?", a:["they are intransitive — they never take a direct object","they are all strong","they all begin with a separable prefix","they all describe the weather"], t:"rule", c:0, e:"That is why [[Ich bin gefahren]] but [[Ich habe das Auto gefahren]] — an accusative object forces [[haben]]."},
{s:"Passive", q:"[[Ich habe das Fenster geöffnet.]] and [[Das Fenster ist geöffnet.]] — what is the difference?", a:["the first reports an action, the second a state","they are identical","the second is a question","the first is future"], t:"rule", c:0, e:"[[haben]] plus participle tells you what happened; [[sein]] plus participle describes how something now is."},
{s:"Perfekt", q:"[[Er ist nach Berlin gefahren.]] What does the [[sein]] tell you?", a:["the verb is one of movement to a new place","that he owns a car","that the trip is in the future","that somebody drove him"], t:"rule", c:0, e:"Verbs of motion and change of state take [[sein]]; a transitive [[fahren]] with an object would take [[haben]]."},

{s:"Präteritum", q:"[[er ___]] — Präteritum of [[gehen]]", a:["ging","gingte","gehte","gegangen"], t:"gap", c:0, e:"Strong verbs change the stem and take no ending in the 1st and 3rd singular."},
{s:"Präteritum", q:"[[ich ___]] — Präteritum of [[bringen]]", a:["brachte","bringte","brang","gebracht"], t:"gap", c:0, e:"Mixed verbs change the vowel and take the weak endings."},
{s:"Präteritum", q:"Which weak Präteritum ending goes with [[du]]?", a:["-test","-te","-ten","-tet"], t:"recall", c:0, e:"[[du spieltest]]."},
{s:"Präteritum", q:"[[Er ___ mich gar nicht.]] (Präteritum of [[sehen]])", a:["sah","sahte","sehte","sahst"], t:"gap", c:0, e:"Strong verbs take a brand-new stem and no ending at all in the 1st and 3rd person singular."},
{s:"Präteritum", q:"[[Wir ___ oft im Park.]] (Präteritum of [[spielen]])", a:["spielten","spielte","spieltet","spielen"], t:"gap", c:0, e:"Weak Präteritum = stem + \"-te-\" + the plural ending, so [[wir]] gets [[-ten]] and [[ihr]] gets [[-tet]]."},
{s:"Präteritum", q:"[[Ich ___ die Antwort nicht.]] (Präteritum of [[wissen]])", a:["wusste","wisste","wusst","weißte"], t:"gap", c:0, e:"[[wissen]] is mixed: strong vowel change to [[wuss-]], then the weak ending \"-te\"."},
{s:"Präteritum", q:"What is the Präteritum [[ich]] form of [[arbeiten]]?", a:["arbeitete","arbeitte","arbeitet","arbeite"], t:"recall", c:0, e:"The -t- stem keeps its helper e, so the tense marker and the ending stack up: [[arbeit-e-te]]."},
{s:"Präteritum", q:"What is the Präteritum [[ihr]] form of [[gehen]]?", a:["gingt","ginget","gingtet","gingen"], t:"recall", c:0, e:"Strong Präteritum endings are the present endings with the 1st and 3rd person singular left bare: [[--, -st, --, -en, -t, -en]]."},
{s:"Präteritum", q:"Why does [[ich ging]] carry no ending?", a:["strong verbs take no ending in the 1st and 3rd singular","[[gehen]] is a modal verb","the ending was absorbed by the vowel change","[[ich]] never takes an ending in the past"], t:"rule", c:0, e:"That is also why [[ich ging]] and [[er ging]] are identical — the same gap appears in every strong verb."},
{s:"Präteritum", q:"What do mixed verbs combine?", a:["a strong stem change with weak endings","a weak stem with strong endings","two different auxiliaries","a separable prefix with an umlaut"], t:"rule", c:0, e:"[[bringen]] → [[brachte]], [[denken]] → [[dachte]], [[kennen]] → [[kannte]]: new vowel, but the weak \"-te\"."},
{s:"Präteritum", q:"[[Als ich klein war, wohnten wir in Bonn.]] Is this one event or a habit?", a:["a lasting state in the past","a single moment","something happening now","a plan for the future"], t:"rule", c:0, e:"[[klein sein]] and [[wohnen]] are both states, so the Präteritum paints a lasting situation. Contrast [[Als ich das hörte…]], where the same pattern is a single instant."},
{s:"Präteritum", q:"[[Er las die Zeitung, während sie kochte.]] What were they doing?", a:["reading and cooking at the same time","he read after she had cooked","he cooked while she read","neither had begun"], t:"rule", c:0, e:"[[während]] with two Präteritum verbs runs both past actions in parallel, and sends its own verb to the end of the clause."},

{s:"Plusquamperfekt and Futur", q:"Which conjunction usually triggers the Plusquamperfekt?", a:["nachdem","weil","wenn","obwohl"], t:"recall", c:0, e:"[[Nachdem ich gegessen hatte, ging ich ins Bett.]]"},
{s:"Plusquamperfekt and Futur", q:"[[Sie wird wohl krank sein]] most likely means…", a:["she is probably ill","she will be ill","she wants to be ill","she was ill"], t:"rule", c:0, e:"[[werden]] plus [[wohl]] or [[schon]] expresses an assumption."},
{s:"Plusquamperfekt and Futur", q:"How is the Plusquamperfekt formed?", a:["hatte / war + Partizip II","werden + Infinitiv","hatte + Infinitiv","war + Infinitiv"], t:"rule", c:0, e:"It is the perfect with the auxiliary in the Präteritum."},
{s:"Plusquamperfekt and Futur", q:"[[Nachdem wir gegessen ___, gingen wir spazieren.]]", a:["hatten","haben","hätten","waren"], t:"gap", c:0, e:"[[nachdem]] forces a step down: Plusquamperfekt in the subordinate clause, simple past in the main clause."},
{s:"Plusquamperfekt and Futur", q:"[[Er ___ bereits nach Hause gegangen.]] (Plusquamperfekt)", a:["war","hatte","ist","wurde"], t:"gap", c:0, e:"The Plusquamperfekt keeps whichever auxiliary the Perfekt uses, just shifted into the Präteritum."},
{s:"Plusquamperfekt and Futur", q:"[[Ihr ___ es bald sehen.]] (Futur I)", a:["werdet","werden","wirst","wurdet"], t:"gap", c:0, e:"Futur I is [[werden]] conjugated in second position with the plain infinitive parked at the end."},
{s:"Plusquamperfekt and Futur", q:"What is the formula for the Futur II?", a:["[[werden]] + Partizip II + [[haben]]/[[sein]]","[[werden]] + Infinitiv","[[hatte]]/[[war]] + Partizip II","[[haben]]/[[sein]] + Infinitiv"], t:"recall", c:0, e:"Three verbs pile up at the end: [[Bis Montag werde ich es fertig gemacht haben]]."},
{s:"Plusquamperfekt and Futur", q:"Which auxiliary does [[fahren]] use in the Plusquamperfekt when it means **to travel**?", a:["war","hatte","wurde","ist"], t:"recall", c:0, e:"[[fahren]] is a [[sein]]-verb, so its Plusquamperfekt is [[ich war gefahren]] — the choice never changes with the tense."},
{s:"Plusquamperfekt and Futur", q:"In [[Nachdem ich gegessen hatte, ging ich ins Bett]], why is the main clause not in the Perfekt?", a:["[[nachdem]] steps each clause one tense back","the Perfekt is forbidden after a comma","[[gehen]] has no Perfekt","the two clauses must have different subjects"], t:"rule", c:0, e:"The pluperfect only earns its keep by contrast — it needs a later past event beside it."},
{s:"Plusquamperfekt and Futur", q:"[[Sie wird den Zug verpasst haben.]] What does this express?", a:["an assumption about something already past","a firm plan for tomorrow","a polite request","a command"], t:"rule", c:0, e:"Futur II far more often means **she has probably missed it** than a genuine statement about the future."},
{s:"Plusquamperfekt and Futur", q:"[[Nachdem er gegessen hatte, ging er ins Bett.]] Which happened first?", a:["eating","going to bed","they happened together","it cannot be told"], t:"rule", c:0, e:"The Plusquamperfekt [[hatte gegessen]] marks the earlier of two past events, which is exactly what [[nachdem]] needs."},
{s:"Plusquamperfekt and Futur", q:"[[Sie wird wohl krank sein.]] Is this about the future?", a:["No — it is a guess about the present","Yes, she will fall ill","Yes, but only tomorrow","No, it is the past"], t:"rule", c:0, e:"[[werden]] plus infinitive often expresses an assumption, and [[wohl]] confirms it. She is probably ill right now."},

/* ---------- VIII. Mood & Voice ---------- */

{s:"Imperative", q:"Imperative of [[geben]] addressing [[du]]", a:["Gib!","Geb!","Gibst!","Gebe!"], t:"recall", c:0, e:"e → i verbs keep the change in the du imperative."},
{s:"Imperative", q:"Imperative of [[fahren]] addressing [[du]]", a:["Fahr!","Fähr!","Fahre du!","Fahrst!"], t:"recall", c:0, e:"a → ä verbs lose the umlaut in the imperative."},
{s:"Imperative", q:"Which imperative keeps its pronoun?", a:["the Sie form","the du form","the ihr form","none of them"], t:"rule", c:0, e:"The [[du]] and [[ihr]] forms drop the pronoun; [[Kommen Sie!]] and [[Gehen wir!]] keep it."},
{s:"Imperative", q:"[[___ doch noch ein Stück Kuchen!]] (take — speaking to [[du]])", a:["Nimm","Nehm","Nimmst","Nehme"], t:"gap", c:0, e:"[[nehmen]] changes e → i, and the du-imperative keeps that change while dropping the ending: [[Nimm!]]"},
{s:"Imperative", q:"What is the [[du]]-imperative of [[lesen]]?", a:["Lies!","Les!","Liest!","Lese!"], t:"recall", c:0, e:"The e → ie change of [[du liest]] survives into the imperative, but the [[-st]] ending does not."},
{s:"Imperative", q:"Why is it [[Fahr langsamer!]] and not [[Fähr langsamer!]]?", a:["The a → ä change is dropped in the imperative","[[fahren]] does not change its stem at all","The umlaut only survives after [[bitte]]","Imperatives always use the plain infinitive stem"], t:"rule", c:0, e:"Verbs with e → i or e → ie keep the change ([[Gib!]], [[Sieh!]]), but a → ä verbs lose the umlaut: [[Fahr!]], [[Lauf!]]"},
{s:"Imperative", q:"[[Kinder, ___ bitte leise!]] (be quiet — to more than one child)", a:["seid","sei","seien","sind"], t:"gap", c:0, e:"The [[ihr]]-imperative is the stem plus [[-t]] with no pronoun, and for [[sein]] that gives [[Seid!]]"},
{s:"Imperative", q:"Which set of imperatives belongs to [[sein]]?", a:["Sei! / Seid! / Seien Sie!","Sei! / Seid! / Sein Sie!","Bist! / Seid! / Seien Sie!","Sei! / Seien! / Seien Sie!"], t:"recall", c:0, e:"[[sein]] is the one truly irregular imperative: the Sie-form is [[Seien Sie]], not the infinitive plus [[Sie]]."},
{s:"Imperative", q:"[[___, wir kommen sonst zu spät!]] (get up — to [[du]])", a:["Steh auf","Aufsteh","Aufstehst","Aufstehen"], t:"gap", c:0, e:"A separable verb splits in the imperative exactly as it does in a main clause, with the prefix at the end."},
{s:"Imperative", q:"Why does [[arbeiten]] give [[Arbeite!]] rather than [[Arbeit!]]?", a:["Stems ending in -d or -t keep the -e","[[arbeiten]] is an irregular verb","The -e is what makes a command polite","Every du-imperative ends in -e"], t:"rule", c:0, e:"The -e is optional for most verbs ([[Komm!]] or [[Komme!]]) but compulsory after a -d or -t stem, where the ending would otherwise be unpronounceable."},

{s:"Konjunktiv II", q:"[[Wenn ich Zeit ___, würde ich kommen.]]", a:["hätte","habe","hatte","hätt"], t:"gap", c:0, e:"[[haben]] has a real Konjunktiv II form, so [[würde haben]] is avoided."},
{s:"Konjunktiv II", q:"How is the past Konjunktiv II formed?", a:["hätte / wäre + Partizip II","würde + Partizip II","würde + Infinitiv","hatte + Infinitiv"], t:"rule", c:0, e:"[[Wenn ich Zeit gehabt hätte…]] — [[würde]] is never used for the past."},
{s:"Konjunktiv II", q:"Which is the polite way to ask for a coffee?", a:["Ich hätte gern einen Kaffee.","Ich habe gern einen Kaffee.","Ich will einen Kaffee.","Ich hatte einen Kaffee."], t:"rule", c:0, e:"Konjunktiv II softens a request."},
{s:"Konjunktiv II", q:"What is the Konjunktiv II of [[können]]?", a:["könnte","konnte","könne","kannte"], t:"recall", c:0, e:"[[konnte]] is the Präteritum and [[könne]] is Konjunktiv I; the umlaut plus [[-e]] gives Konjunktiv II [[könnte]]."},
{s:"Konjunktiv II", q:"Which form means **I would have to** — the Konjunktiv II of [[müssen]]?", a:["müsste","musste","müsse","müssen"], t:"recall", c:0, e:"All six modals build Konjunktiv II the same way, and only [[sollen]] and [[wollen]] end up with no umlaut."},
{s:"Konjunktiv II", q:"Which verb normally forms its Konjunktiv II with [[würde]] + Infinitiv rather than a form of its own?", a:["spielen","sein","haben","können"], t:"rule", c:0, e:"[[würde]] + Infinitiv is the default; only [[sein]], [[haben]], the modals and a handful of common strong verbs keep a real Konjunktiv II."},
{s:"Konjunktiv II", q:"What is the Konjunktiv II of [[gehen]]?", a:["ginge","gänge","ging","gehte"], t:"recall", c:0, e:"Strong verbs build it from the Präteritum stem plus [[-e]]: [[ging]] → [[ginge]], just as [[kam]] → [[käme]]."},
{s:"Konjunktiv II", q:"[[Ich wünschte, ich ___ jetzt am Meer.]]", a:["wäre","würde","hätte","war"], t:"gap", c:0, e:"A wish takes Konjunktiv II, and [[sein]] has a form of its own, so [[wäre]] — never [[würde sein]]."},
{s:"Konjunktiv II", q:"[[Wenn ich früher losgefahren wäre, ___ ich den Zug nicht verpasst.]]", a:["hätte","wäre","würde","hatte"], t:"gap", c:0, e:"Past Konjunktiv II is [[hätte]] or [[wäre]] plus the Partizip II, and the choice follows the verb's normal Perfekt auxiliary — [[verpassen]] takes [[haben]]."},
{s:"Konjunktiv II", q:"What is Konjunktiv II doing in [[An deiner Stelle würde ich warten]]?", a:["giving advice","reporting someone else's words","describing a past habit","stating a fact about the future"], t:"rule", c:0, e:"[[An deiner Stelle]] — if I were you — is unreal by definition, and reporting someone else's words would call for Konjunktiv I instead."},

{s:"Passive", q:"[[Das Haus ist gebaut ___.]] (perfect passive)", a:["worden","geworden","werden","wurde"], t:"gap", c:0, e:"In the passive perfect the participle of [[werden]] loses its [[ge-]]."},
{s:"Passive", q:"[[Das Fenster ist geöffnet]] describes…", a:["the resulting state","the action in progress","a future action","a habit"], t:"rule", c:0, e:"[[sein]] + participle is the state; [[werden]] + participle is the action."},
{s:"Passive", q:"Which preposition names a person as the agent?", a:["von","durch","mit","bei"], t:"recall", c:0, e:"[[von]] for an agent, [[durch]] for a means or cause."},
{s:"Passive", q:"[[Das Dorf wurde ___ das Hochwasser zerstört.]]", a:["durch","von","mit","für"], t:"gap", c:0, e:"[[durch]] + Akkusativ names a means or a cause; a person or agent who acts takes [[von]] + Dativ."},
{s:"Passive", q:"[[Der Brief wurde von ___ Chefin unterschrieben.]]", a:["der","die","den","dem"], t:"gap", c:0, e:"[[von]] always takes the Dativ, so feminine [[die Chefin]] becomes [[der Chefin]] in the agent phrase."},
{s:"Passive", q:"When an active sentence is turned into the passive, what happens to the accusative object?", a:["It becomes the nominative subject","It stays in the accusative","It becomes a dative object","It has to move into a [[von]]-phrase"], t:"rule", c:0, e:"[[Der Mann baut das Haus]] → [[Das Haus wird gebaut]]; the old subject either disappears or comes back with [[von]]."},
{s:"Passive", q:"[[Man tanzt hier viel]] — what does that look like in the passive?", a:["Es wird hier viel getanzt.","Hier wird viel tanzen.","Man wird hier viel getanzt.","Hier ist viel getanzt."], t:"rule", c:0, e:"[[tanzen]] has no accusative object, so the passive has no subject at all and a dummy [[es]] fills position 1."},
{s:"Passive", q:"What is the Präteritum of [[Das Haus wird gebaut]]?", a:["Das Haus wurde gebaut.","Das Haus ist gebaut worden.","Das Haus war gebaut worden.","Das Haus würde gebaut."], t:"recall", c:0, e:"Only the [[werden]] half carries the tense: [[wird]] → [[wurde]]. The other two are the Perfekt and the Plusquamperfekt."},
{s:"Passive", q:"Which sentence does NOT dodge the passive?", a:["Das Haus wird gebaut.","Man baut das Haus.","Das lässt sich machen.","Das ist zu machen."], t:"rule", c:0, e:"[[man]] + active, [[sich lassen]] and [[sein]] + [[zu]] + Infinitiv are the three standard ways round it; the first sentence is a passive."},
{s:"Passive", q:"[[Das Formular muss bis Freitag unterschrieben ___.]]", a:["werden","worden","wird","geworden"], t:"gap", c:0, e:"A modal plus passive ends in the infinitive [[werden]]; [[worden]] belongs only to the passive Perfekt, where it loses its [[ge-]]"},

{s:"Konjunktiv I — reported speech", q:"In formal writing, which form marks [[Er sagt, er ___ krank]] as a reported claim?", a:["sei","ist","war","gewesen ist"], t:"gap", c:0, e:"Konjunktiv I reports a claim without endorsing it. The indicative [[ist]] is grammatical too, but it quietly endorses the claim."},
{s:"Konjunktiv I — reported speech", q:"Why is [[sie hätten]] used rather than [[sie haben]] in reported speech?", a:["Konjunktiv I would look identical to the present","[[haben]] has no Konjunktiv I","it is more polite","the plural always uses Konjunktiv II"], t:"rule", c:0, e:"When Konjunktiv I is indistinguishable from the indicative, Konjunktiv II takes over."},
{s:"Konjunktiv I — reported speech", q:"Where is Konjunktiv I mainly found?", a:["journalism and formal writing","casual speech","questions","commands"], t:"rule", c:0, e:"In speech the indicative is normal."},
{s:"Konjunktiv I — reported speech", q:"What is the Konjunktiv I of [[haben]] for [[er/sie/es]]?", a:["habe","hat","hätte","hatte"], t:"recall", c:0, e:"Konjunktiv I is the infinitive stem plus [[-e]], so [[er habe]]; [[hätte]] is Konjunktiv II and only steps in as a fallback."},
{s:"Konjunktiv I — reported speech", q:"[[Die Zeugin sagte, sie ___ nichts gesehen.]] (formal report — use Konjunktiv I)", a:["habe","hat","hätte","haben"], t:"gap", c:0, e:"[[sie habe]] is clearly different from the indicative [[sie hat]], so Konjunktiv I is available and no fallback is needed."},
{s:"Konjunktiv I — reported speech", q:"Why does reported [[ich spiele]] come out as [[ich würde spielen]]?", a:["The Konjunktiv I form [[spiele]] is identical to the indicative","Konjunktiv I has no first-person form","[[spielen]] is a strong verb","Konjunktiv I may not be used with weak verbs"], t:"rule", c:0, e:"When Konjunktiv I cannot be told apart from the present tense, German switches to Konjunktiv II — here [[würde]] + Infinitiv."},
{s:"Konjunktiv I — reported speech", q:"Why are [[sei]] and [[seien]] by far the commonest Konjunktiv I forms in print?", a:["[[sein]] is the only verb whose Konjunktiv I differs from the indicative in every person","[[sein]] is the most frequent verb in German","[[sein]] has no Konjunktiv II","Only [[sein]] is permitted in reported speech"], t:"rule", c:0, e:"Every other verb collides with the indicative somewhere and has to fall back on Konjunktiv II; [[sein]] never does."},
{s:"Konjunktiv I — reported speech", q:"What is the difference between [[Er sagt, er sei krank]] and [[Er sagt, er ist krank]]?", a:["Konjunktiv I stays neutral about the claim, the indicative quietly endorses it","The second sentence is ungrammatical","Konjunktiv I signals that the speaker knows the claim is false","There is no difference of any kind"], t:"rule", c:0, e:"Both are correct German: the indicative is normal in speech, while Konjunktiv I belongs to journalism, minutes and academic writing."},
{s:"Konjunktiv I — reported speech", q:"Konjunktiv I is built on which stem?", a:["the infinitive stem","the Präteritum stem","the Partizip II","the [[du]]-form stem"], t:"recall", c:0, e:"Infinitive stem plus [[-e, -est, -e, -en, -et, -en]] — which is exactly why the [[wir]] and [[sie]] forms come out identical to the present."},
{s:"Konjunktiv I — reported speech", q:"[[Er sagt, er ___ uns morgen abholen.]] (formal report: he can pick us up)", a:["könne","kann","könnte","konnte"], t:"gap", c:0, e:"[[er könne]] is distinct from the indicative [[er kann]], so Konjunktiv I holds; [[könnte]] would only take over if the two were identical."},
{s:"Konjunktiv I — reported speech", q:"[[Er sagt, er sei krank.]] Whose claim is the illness?", a:["his — the writer is not vouching for it","the writer's, stated as fact","the doctor's","nobody's, it is a question"], t:"rule", c:0, e:"Konjunktiv I reports without endorsing. [[Er sagt, er ist krank]] would let the illness stand as fact."},
{s:"Konjunktiv I — reported speech", q:"Why does a German newspaper write [[Der Minister habe nichts gewusst]]?", a:["to attribute the claim without confirming it","because the minister is being polite","because it happened long ago","to make it a question"], t:"rule", c:0, e:"The Konjunktiv I is the German equivalent of English scare-quotes around a reported claim."},

/* ---------- IX. Word Order ---------- */

{s:"The verb-second rule", q:"[[Morgen ___ ich nach Berlin.]]", a:["fahre","ich fahre","fahren","zu fahren"], t:"gap", c:0, e:"The conjugated verb holds second position and the subject follows it."},
{s:"The verb-second rule", q:"A whole subordinate clause in first position counts as…", a:["one element","two elements","no element","the verb"], t:"rule", c:0, e:"[[Weil es billig ist, fahre ich mit dem Bus.]]"},
{s:"The verb-second rule", q:"In [[Ich habe ein Buch gekauft]], where is the participle?", a:["at the end of the clause","second","first","before the object"], t:"rule", c:0, e:"Everything verbal except the conjugated verb goes to the end."},
{s:"The verb-second rule", q:"[[Heute ___ nach Hause.]] (I'm going home today)", a:["gehe ich","ich gehe","gehen ich","ich gehen"], t:"gap", c:0, e:"[[Heute]] occupies position 1, so the conjugated verb must come next and the subject slides in behind it."},
{s:"The verb-second rule", q:"[[Wenn es regnet, ___.]] (we stay at home)", a:["bleiben wir zu Hause","wir bleiben zu Hause","wir zu Hause bleiben","zu Hause wir bleiben"], t:"gap", c:0, e:"A whole subordinate clause counts as one single element, so the main verb is still the second element and the subject follows it."},
{s:"The verb-second rule", q:"What exactly does verb-second count?", a:["the second unit of meaning, which may be several words","the second word of the sentence","the second noun in the sentence","the second stressed syllable"], t:"rule", c:0, e:"In [[Nach Berlin fahre ich morgen]] the two-word phrase [[nach Berlin]] is one element, so [[fahre]] is still in second position."},
{s:"The verb-second rule", q:"[[Ich weiß nicht, wann der Zug ___.]]", a:["abfährt","fährt ab","ab fährt","abfahren"], t:"gap", c:0, e:"An indirect question sends the verb to the end of its clause, and a separable verb travels there in one piece."},
{s:"The verb-second rule", q:"Where does the conjugated verb stand in a relative clause?", a:["at the very end of the clause","second, as in a main clause","first","directly after the relative pronoun"], t:"recall", c:0, e:"[[Der Mann, der dort steht, …]] — relative clauses, indirect questions and subordinating conjunctions all push the verb to the end."},
{s:"The verb-second rule", q:"What changes between [[Ich fahre morgen nach Berlin]] and [[Morgen fahre ich nach Berlin]]?", a:["only the emphasis — whatever stands first is highlighted","the tense","the meaning of [[fahren]]","nothing, because one of them is simply wrong"], t:"rule", c:0, e:"Position 1 is the emphasis slot; the verb stays second either way and the subject steps aside when something else takes the front."},
{s:"The verb-second rule", q:"How many elements may stand in front of the conjugated verb in a main clause?", a:["exactly one","one or two","any number","none at all"], t:"recall", c:0, e:"That is the whole rule. [[Morgen ich fahre nach Berlin]] fails because two elements come before [[fahre]]."},
{s:"The verb-second rule", q:"[[Morgen fahre ich nach Köln.]] Why is [[ich]] after the verb?", a:["[[Morgen]] has taken first position, so the verb keeps second","the subject always follows the verb","it is a question","[[fahren]] is irregular"], t:"rule", c:0, e:"Only one element may stand before the finite verb. If something else takes that slot, the subject moves behind."},
{s:"The verb-second rule", q:"[[Weil er kein Geld hatte, blieb er zu Hause.]] Why does [[blieb]] come first in the second half?", a:["the whole [[weil]] clause fills first position","it is an imperative","[[bleiben]] is a strong verb","the comma requires it"], t:"rule", c:0, e:"A subordinate clause counts as a single element, so the main verb still lands in second position overall."},
{s:"The verb-second rule", q:"[[Das Buch gab mir mein Vater.]] Who gave what to whom?", a:["my father gave me the book","I gave the book to my father","the book was given to my father","my father was given the book"], t:"rule", c:0, e:"[[mein Vater]] is nominative and [[das Buch]] accusative, whatever the order. [[mir]] is the dative recipient."},

{s:"Order in the middle field", q:"What does TeKaMoLo stand for?", a:["temporal, kausal, modal, lokal","tense, case, mood, location","time, kind, motion, location","topic, case, modal, logic"], t:"rule", c:0, e:"When, why, how, where — in that order."},
{s:"Order in the middle field", q:"[[Den Ball? Ich gebe ___.]] (I give it to him — two pronouns)", a:["ihn ihm","ihm ihn","ihm den","den ihm"], t:"gap", c:0, e:"With two pronouns the accusative comes first."},
{s:"Order in the middle field", q:"With two full nouns the order is…", a:["dative before accusative","accusative before dative","either","alphabetical"], t:"rule", c:0, e:"[[Ich gebe dem Kind den Ball.]]"},
{s:"Order in the middle field", q:"Which sentence follows TeKaMoLo?", a:["Ich fahre morgen mit dem Zug nach Hamburg.","Ich fahre mit dem Zug morgen nach Hamburg.","Ich fahre nach Hamburg morgen mit dem Zug.","Ich fahre mit dem Zug nach Hamburg morgen."], t:"rule", c:0, e:"Time before manner before place: [[morgen]] (wann?), [[mit dem Zug]] (wie?), [[nach Hamburg]] (wohin?)."},
{s:"Order in the middle field", q:"Which slot comes last in TeKaMoLo?", a:["Lokal — wo? wohin?","Temporal — wann?","Kausal — warum?","Modal — wie?"], t:"recall", c:0, e:"The place expression is pushed right up to the end of the middle field: [[Ich fahre heute mit dem Bus in die Stadt]]."},
{s:"Order in the middle field", q:"[[Kannst du ___ zeigen?]] (show me the photo)", a:["mir das Foto","das Foto mir","mich das Foto","das Foto mich"], t:"gap", c:0, e:"A pronoun comes before a noun object whatever their cases, because known information goes before new."},
{s:"Order in the middle field", q:"What single principle lies behind all three object-order rules?", a:["pronouns come early, and known information before new","the accusative always comes first","the longer phrase always comes first","the object nearer the verb takes the dative"], t:"rule", c:0, e:"Two pronouns is the one situation where the accusative jumps ahead of the dative: [[Ich gebe ihn ihm]]."},
{s:"Order in the middle field", q:"[[Ich kenne den Film ___.]]", a:["nicht","kein","keinen","nichts"], t:"gap", c:0, e:"[[kein]] only replaces [[ein]] or a bare noun; a noun with a definite article is negated by [[nicht]], which goes late in the clause."},
{s:"Order in the middle field", q:"Where does [[nicht]] stand when it negates one particular word?", a:["immediately before that word","at the very end of the clause","directly after the conjugated verb","in front of the subject"], t:"rule", c:0, e:"[[nicht heute]], [[nicht schön]]. Only sentence negation goes late — and even then [[nicht]] stays in front of any verb at the end."},
{s:"Order in the middle field", q:"Which negator goes with a noun that has [[ein]] or no article at all?", a:["kein","nicht","nichts","nie"], t:"recall", c:0, e:"[[Ich habe ein Auto]] → [[Ich habe kein Auto]]; [[nicht]] handles everything else."},
{s:"Order in the middle field", q:"[[Ich habe das Buch nicht gelesen.]] What is being denied?", a:["that I read it","that it was a book","that it was mine","that I own it"], t:"rule", c:0, e:"[[nicht]] immediately before the participle negates the action itself — I did not read it."},
{s:"Order in the middle field", q:"[[Ich habe nicht das Buch gelesen, sondern die Zeitung.]] What is being denied?", a:["that it was the book","that I read anything","that I finished it","that I understood it"], t:"rule", c:0, e:"Put [[nicht]] directly in front of a phrase and it negates that phrase alone, which is why [[sondern]] can follow."},
{s:"Order in the middle field", q:"[[Er kommt heute nicht.]] versus [[Er kommt nicht heute, sondern morgen.]] — what is the difference?", a:["the first denies his coming, the second only the day","they mean the same","the second is ungrammatical","both deny only the day"], t:"rule", c:0, e:"Final [[nicht]] negates the whole sentence; [[nicht]] parked in front of [[heute]] narrows the denial to the timing."},

{s:"Conjunctions", q:"Which conjunction sends the verb to the end?", a:["weil","denn","aber","und"], t:"recall", c:0, e:"[[weil]] is subordinating; [[denn]] leaves the order untouched."},
{s:"Conjunctions", q:"[[Deshalb ___ ich zu Hause.]]", a:["bleibe","ich bleibe","bleiben","zu bleiben"], t:"gap", c:0, e:"[[deshalb]] occupies position 1, so the verb comes second."},
{s:"Conjunctions", q:"Which pair means the same but behaves differently?", a:["denn and weil","und and oder","aber and sondern","dass and ob"], t:"rule", c:0, e:"[[Ich bleibe, denn ich bin müde]] beside [[…, weil ich müde bin]]."},
{s:"Conjunctions", q:"[[Ich bleibe zu Hause, denn ___.]]", a:["ich bin müde","ich müde bin","bin ich müde","müde ich bin"], t:"gap", c:0, e:"[[denn]] is coordinating: it stands outside the clause and leaves ordinary main-clause order untouched."},
{s:"Conjunctions", q:"[[Wir gehen trotzdem raus, obwohl das Wetter schlecht ___.]]", a:["ist","ist es","es ist","sei"], t:"gap", c:0, e:"[[obwohl]] is subordinating, so the conjugated verb drops to the very end of its own clause."},
{s:"Conjunctions", q:"Why does [[und]] leave the word order alone in [[Ich komme und du bleibst]]?", a:["coordinating conjunctions stand outside the clause, in position 0","[[und]] is really an adverb","[[und]] itself counts as the first element","[[und]] can only join two nouns"], t:"rule", c:0, e:"[[und, aber, oder, denn, sondern]] fill no slot at all, so the subject still comes first and the verb still second."},
{s:"Conjunctions", q:"Which of these takes position 1 itself, so that the verb comes straight after it?", a:["trotzdem","obwohl","weil","dass"], t:"rule", c:0, e:"Adverbial connectors — [[deshalb]], [[deswegen]], [[trotzdem]], [[dann]], [[außerdem]] — occupy position 1, so the verb follows and the subject comes third."},
{s:"Conjunctions", q:"Which list contains coordinating conjunctions only?", a:["und, aber, oder, denn, sondern","und, aber, weil, denn","oder, denn, obwohl, sondern","aber, dass, oder, und"], t:"recall", c:0, e:"Those five are the entire set; everything else either sends the verb to the end or claims position 1 for itself."},
{s:"Conjunctions", q:"Which conjunction replaces something that has just been denied?", a:["sondern","aber","denn","oder"], t:"recall", c:0, e:"[[Er ist nicht Arzt, sondern Krankenpfleger]] — [[sondern]] puts the correction in place of what was negated, while [[aber]] merely contrasts."},
{s:"Conjunctions", q:"Which conjunction introduces a single event in the past?", a:["als","wenn","ob","falls"], t:"recall", c:0, e:"[[als]] for one past occasion, [[wenn]] for **if** or **whenever** — both send the verb to the end."},
{s:"Conjunctions", q:"[[Er kam nicht, denn er war krank.]] and [[Er kam nicht, weil er krank war.]] — what is the difference?", a:["they mean the same but the verb sits differently","the first is wrong","only the second gives a reason","the second is a question"], t:"rule", c:0, e:"[[denn]] coordinates and leaves the order alone; [[weil]] subordinates and sends the verb to the end."},
{s:"Conjunctions", q:"[[Ich weiß, dass er kommt.]] What does [[dass]] do to the verb?", a:["sends it to the end of its clause","puts it first","removes its ending","makes it past tense"], t:"rule", c:0, e:"Every subordinating conjunction pushes the finite verb to the end — the single biggest clue that a clause is subordinate."},

{s:"Infinitive clauses with zu", q:"[[Ich versuche, früh ___.]] ([[aufstehen]])", a:["aufzustehen","zu aufstehen","aufstehen zu","zu aufzustehen"], t:"gap", c:0, e:"With a separable verb the [[zu]] sits between prefix and stem."},
{s:"Infinitive clauses with zu", q:"Which verb takes NO [[zu]]?", a:["müssen","versuchen","hoffen","beginnen"], t:"recall", c:0, e:"Modals, [[werden]], [[lassen]], [[sehen]] and [[hören]] take a bare infinitive."},
{s:"Infinitive clauses with zu", q:"When can [[um … zu]] not be used?", a:["when the two halves have different subjects","in the past","with separable verbs","in questions"], t:"rule", c:0, e:"Use [[damit]] instead: [[Ich erkläre es, damit du es verstehst.]]"},
{s:"Infinitive clauses with zu", q:"[[Ich fahre in die Stadt, ___ einen Anzug zu kaufen.]] (in order to buy a suit)", a:["um","ohne","statt","damit"], t:"gap", c:0, e:"[[um … zu]] states the purpose; [[damit]] cannot be used here because it needs a full clause with a conjugated verb."},
{s:"Infinitive clauses with zu", q:"[[Ich erkläre es noch einmal, ___ du es verstehst.]] (so that you understand it)", a:["damit","um","um zu","ohne zu"], t:"gap", c:0, e:"[[um … zu]] works only when both halves share a subject; here they do not, so [[damit]] takes over."},
{s:"Infinitive clauses with zu", q:"How is the [[zu]]-infinitive of [[mitkommen]] written?", a:["mitzukommen","zu mitkommen","mit zu kommen","mitkommen zu"], t:"recall", c:0, e:"With a separable verb the [[zu]] climbs inside the word, between prefix and stem: [[aufzustehen]], [[einzukaufen]]."},
{s:"Infinitive clauses with zu", q:"When does [[brauchen]] take [[zu]] + Infinitiv?", a:["only in the negative","only in questions","always","never"], t:"rule", c:0, e:"[[Du brauchst nicht zu kommen]] — you needn't come. Used positively, [[brauchen]] simply takes an object."},
{s:"Infinitive clauses with zu", q:"What does [[Ich muss gehen]] look like in the Perfekt?", a:["Ich habe gehen müssen.","Ich habe gehen gemusst.","Ich bin gehen müssen.","Ich habe gemusst gehen."], t:"recall", c:0, e:"A modal in the perfect keeps its infinitive form instead of taking a Partizip II — the double infinitive."},
{s:"Infinitive clauses with zu", q:"In a subordinate clause with a double infinitive, where does the auxiliary go?", a:["in front of the two infinitives","right at the end, as usual","in second position","immediately after the conjunction"], t:"rule", c:0, e:"[[…, weil ich habe gehen müssen]] — the one case where a subordinate clause does not end on its finite verb."},
{s:"Infinitive clauses with zu", q:"[[Sie schlief, statt ___.]] (instead of studying)", a:["zu lernen","lernen","zu lernt","lernen zu"], t:"gap", c:0, e:"[[statt]], [[ohne]] and [[um]] all end in a plain [[zu]] + Infinitiv at the close of the clause."},

{s:"Commas", q:"Where is a comma required?", a:["before a subordinate clause","before [[und]] in a list","after a fronted element","before [[wie]] in a comparison"], t:"rule", c:0, e:"[[Ich bleibe, weil es regnet.]]"},
{s:"Commas", q:"[[Äpfel, Birnen ___ Bananen]]", a:["und",", und","; und",", und auch"], t:"gap", c:0, e:"German does not use a serial comma before [[und]]."},
{s:"Commas", q:"When may the comma before a [[zu]] infinitive be left out?", a:["only before a bare, unextended infinitive","always","never","only after [[um]]"], t:"rule", c:0, e:"[[Iris versprach mitzumachen.]] Once anything depends on the infinitive — and always after [[um]], [[ohne]], [[statt]] — the comma is compulsory."},
{s:"Commas", q:"Which sentence is punctuated correctly?", a:["Der Mann, der dort steht, ist mein Bruder.","Der Mann der dort steht, ist mein Bruder.","Der Mann, der dort steht ist mein Bruder.","Der Mann der dort steht ist mein Bruder."], t:"rule", c:0, e:"A relative clause is fenced off on both sides, because a German comma marks a clause boundary rather than a pause."},
{s:"Commas", q:"Which of these always has a comma in front of it?", a:["aber","und","oder","wie"], t:"recall", c:0, e:"[[aber]], [[sondern]] and [[denn]] always take one; between two main clauses the comma before [[und]] or [[oder]] is optional."},
{s:"Commas", q:"Why is there no comma in [[Ich stehe auf und gehe]]?", a:["[[und]] is joining two verbs that share one subject","[[und]] never takes a comma","the sentence is too short to need one","[[aufstehen]] is a separable verb"], t:"rule", c:0, e:"Give the second half its own subject — [[Ich stehe auf, und sie geht]] — and the comma becomes possible again."},
{s:"Commas", q:"[[Er ist so groß ___ ich.]]", a:["wie","als","denn","so"], t:"gap", c:0, e:"A comparison of equals takes [[wie]], and no comma goes in front of it."},
{s:"Commas", q:"What punctuation follows a fronted element, as in [[Morgen fahre ich weg]]?", a:["none at all","a comma","a comma only in formal writing","a dash"], t:"recall", c:0, e:"German does not comma off a fronted phrase the way English often does; the verb simply follows it in second position."},
{s:"Commas", q:"What belongs in the gap? [[Äpfel, Birnen ___ und Bananen]]", a:["nothing","a comma","a semicolon","a dash"], t:"gap", c:0, e:"German does not use the Oxford comma: no comma goes in front of [[und]] in a list."},
{s:"Commas", q:"Could the comma be dropped in [[Er ging, ohne zu zahlen]]?", a:["No — after [[ohne]], [[um]] or [[statt]] it is compulsory","Yes, because the infinitive is bare","Yes, commas before [[zu]] are always optional","No, because [[zahlen]] is a weak verb"], t:"rule", c:0, e:"Only a bare infinitive with nothing depending on it and no conjunction in front may lose the comma: [[Iris versprach mitzumachen]]."},

/* ---------- X. Questions ---------- */

{s:"W-question words", q:"Which asks about possession?", a:["wessen","wem","wen","wer"], t:"recall", c:0, e:"[[wer – wen – wem – wessen]] decline like [[der]]."},
{s:"W-question words", q:"[[___ gehst du?]] (where to)", a:["Wohin","Wo","Woher","Wann"], t:"gap", c:0, e:"[[wo]] is position, [[wohin]] destination, [[woher]] origin."},
{s:"W-question words", q:"[[___ Buch möchtest du?]] (which)", a:["Welches","Welcher","Was","Wie"], t:"gap", c:0, e:"[[welcher]] declines like a der-word and agrees with the noun."},
{s:"W-question words", q:"[[___ hast du gestern getroffen?]] (whom did you meet)", a:["Wen","Wer","Wem","Wessen"], t:"gap", c:0, e:"[[treffen]] takes a direct object, so the accusative [[wen]]. [[wer]] would turn that person into the one doing the meeting."},
{s:"W-question words", q:"[[___ gehört das Auto?]] (to whom)", a:["Wem","Wen","Wer","Wessen"], t:"gap", c:0, e:"[[gehören]] takes a dative object, so [[wem]]. English **whom** covers both [[wen]] and [[wem]], so the German verb has to decide."},
{s:"W-question words", q:"[[wer]] changes its form in the same pattern as which word?", a:["the definite article [[der]]","the possessive [[mein]]","the pronoun [[ich]]","none — it never changes"], t:"rule", c:0, e:"[[wer, wen, wem, wessen]] mirrors [[der, den, dem, dessen]]. Learn one set and you have the other."},
{s:"W-question words", q:"Which W-word asks where somebody has come from?", a:["woher","wohin","wo","wann"], t:"recall", c:0, e:"[[wo]] asks about position, [[wohin]] about destination and [[woher]] about origin — the same three-way split that decides case after a two-way preposition."},
{s:"W-question words", q:"[[___ weit ist es bis zum Bahnhof?]] (how far)", a:["Wie","Was","Wo","Welche"], t:"gap", c:0, e:"[[wie]] combines freely with a second word: [[wie lange, wie oft, wie alt, wie spät, wie weit]]."},
{s:"W-question words", q:"Which of these asks about a countable number?", a:["wie viele","wie viel","wie oft","wie weit"], t:"recall", c:0, e:"[[wie viele Bücher]] counts separate items; [[wie viel Zeit]] measures an uncountable mass."},
{s:"W-question words", q:"What decides between [[wer]] and [[wen]] at the start of a question?", a:["Whether the person is the subject or the direct object","Whether the person is male or female","Whether the answer is singular or plural","Whether the verb is present or past"], t:"rule", c:0, e:"[[Wer]] asks for the subject and [[wen]] for the object; case, not meaning, does the work."},

{s:"Question structure", q:"How does a yes/no question begin?", a:["with the verb","with the subject","with a question word","with [[ob]]"], t:"rule", c:0, e:"[[Kommst du morgen?]]"},
{s:"Question structure", q:"[[Ich frage, ___ du mitkommst.]]", a:["ob","wenn","wann","dass"], t:"gap", c:0, e:"An indirect yes/no question uses [[ob]], never [[wenn]]."},
{s:"Question structure", q:"In an indirect question the verb goes…", a:["at the end","second","first","after the subject"], t:"rule", c:0, e:"[[Ich weiß nicht, wo er wohnt.]]"},
{s:"Question structure", q:"[[___ du schon gegessen?]] (have you eaten yet)", a:["Hast","Bist","Du hast","Habst"], t:"gap", c:0, e:"A yes/no question puts the conjugated verb first, ahead of the subject, and [[essen]] builds its perfect with [[haben]]."},
{s:"Question structure", q:"What happens when the statement [[Du kommst morgen]] becomes a yes/no question?", a:["The verb moves in front of the subject","The verb moves to the end","[[ob]] is added at the front","Only the intonation changes"], t:"rule", c:0, e:"[[Kommst du morgen?]] The neutral question form inverts subject and verb; a statement left in place with rising intonation ([[Du kommst morgen?]]) is only a colloquial check, not the standard form."},
{s:"Question structure", q:"[[Wohin ___ ihr im Sommer?]] (are you all going)", a:["fahrt","fährt","ihr fahrt","fahren"], t:"gap", c:0, e:"The question word takes first position and the conjugated verb second, so the subject [[ihr]] is pushed behind it."},
{s:"Question structure", q:"In a W-question, where does the conjugated verb stand?", a:["Second, straight after the question word","First, before the question word","Last","Third, after the subject"], t:"rule", c:0, e:"The W-word fills position one, so the verb simply keeps its normal second slot — the same verb-second rule as in a statement."},
{s:"Question structure", q:"[[Sag mir bitte, wann der Zug ___.]] (arrives — [[ankommen]])", a:["ankommt","kommt an","ankommen","an kommt"], t:"gap", c:0, e:"An indirect question is a subordinate clause, so the verb goes last — and a separable verb puts itself back together when it gets there."},
{s:"Question structure", q:"Why is [[Ich frage, wenn du mitkommst]] wrong?", a:["An indirect yes/no question needs [[ob]], not [[wenn]]","[[fragen]] cannot take a subordinate clause","The verb must come first after [[wenn]]","[[mitkommen]] cannot end a clause"], t:"rule", c:0, e:"[[ob]] is **whether**; [[wenn]] means **if** or **whenever** in a condition or time clause. Mixing them is one of the commonest learner errors."},
{s:"Question structure", q:"In [[Kannst du morgen kommen?]], which verb stands in first position?", a:["the modal [[kannst]]","the infinitive [[kommen]]","both together","neither — [[du]] comes first"], t:"recall", c:0, e:"The conjugated verb leads and the infinitive waits at the end, the usual verb bracket opened one slot earlier."},

{s:"wo(r)- and da(r)- compounds", q:"[[___ wartest du?]] (what are you waiting for)", a:["Worauf","Wofür","Auf wen","Warum"], t:"gap", c:0, e:"[[warten auf]] + a thing → [[worauf]]."},
{s:"wo(r)- and da(r)- compounds", q:"When is the [[r]] inserted?", a:["before a vowel","before a consonant","always","never in questions"], t:"rule", c:0, e:"[[worauf]], [[woran]], but [[womit]], [[wofür]]."},
{s:"wo(r)- and da(r)- compounds", q:"[[Auf wen wartest du?]] asks about…", a:["a person","a thing","a place","a time"], t:"rule", c:0, e:"People keep the preposition plus a pronoun; things use the compound."},
{s:"wo(r)- and da(r)- compounds", q:"[[Ich freue mich schon ___.]] (I am looking forward to it)", a:["darauf","dafür","auf es","daran"], t:"gap", c:0, e:"[[sich freuen auf]] plus a thing becomes [[da-]] + [[auf]] = [[darauf]]. The literal [[auf es]] is not possible in German."},
{s:"wo(r)- and da(r)- compounds", q:"[[___ hat er so lange gesprochen?]] (about what)", a:["Worüber","Woüber","Worauf","Womit"], t:"gap", c:0, e:"[[sprechen über]] plus [[wo-]] gives [[worüber]], with the [[r]] inserted because [[über]] begins with a vowel."},
{s:"wo(r)- and da(r)- compounds", q:"[[Auf ___ wartest du?]] (which person are you waiting for)", a:["wen","wem","was","wer"], t:"gap", c:0, e:"For a person the preposition stays in front and takes a question pronoun; [[warten auf]] governs the accusative, so [[wen]]."},
{s:"wo(r)- and da(r)- compounds", q:"Why can [[Womit fährst du?]] never mean **who are you travelling with**?", a:["wo(r)- compounds refer to things only, never to people","[[mit]] cannot form a compound","[[womit]] really means **how**","[[fahren]] does not combine with [[mit]]"], t:"rule", c:0, e:"For people you need [[Mit wem fährst du?]] — the preposition keeps a real pronoun rather than fusing."},
{s:"wo(r)- and da(r)- compounds", q:"[[darunter]] means…", a:["under it","over it","with it","for it"], t:"recall", c:0, e:"[[da-]] + [[unter]], with [[r]] inserted because [[unter]] starts with a vowel. Compare [[darüber]] (**over it**) and [[dafür]] (**for it**)."},
{s:"wo(r)- and da(r)- compounds", q:"[[Hast du ___ gedacht?]] (did you think of it)", a:["daran","dafür","an es","damit"], t:"gap", c:0, e:"[[denken an]] plus a thing gives [[daran]]; about a person it would be [[an ihn]] or [[an sie]]."},
{s:"wo(r)- and da(r)- compounds", q:"For a person, which form replaces [[worauf]]?", a:["auf wen","woraufhin","darauf","auf was"], t:"recall", c:0, e:"[[warten auf]] governs the accusative, so a person gives [[Auf wen wartest du?]]; only things fuse into [[worauf]]."},

/* ---------- XI. Comparison ---------- */

{s:"Comparative and superlative", q:"Comparative of [[interessant]]", a:["interessanter","mehr interessant","interessantest","am interessanten"], t:"recall", c:0, e:"German adds endings however long the adjective is."},
{s:"Comparative and superlative", q:"Superlative of [[kalt]] standing alone", a:["am kältesten","am kaltsten","der kälteste","am kälter"], t:"recall", c:0, e:"An extra [[e]] goes in after [[-d, -t, -s, -ß, -z]]."},
{s:"Comparative and superlative", q:"[[Er ist der ___ Läufer.]] (fastest)", a:["schnellste","am schnellsten","schnellsten","schneller"], t:"gap", c:0, e:"Before a noun the superlative takes adjective endings."},
{s:"Comparative and superlative", q:"Why is [[mehr interessant]] wrong?", a:["German compares by adding an ending, however long the word","[[interessant]] cannot be compared","it needs [[am]] instead","only short adjectives compare"], t:"rule", c:0, e:"[[interessanter]], [[am interessantesten]]."},
{s:"Comparative and superlative", q:"Comparative of [[jung]]", a:["jünger","junger","mehr jung","am jüngsten"], t:"recall", c:0, e:"Short adjectives take an umlaut in the comparative: [[alt → älter]], [[lang → länger]], [[jung → jünger]]."},
{s:"Comparative and superlative", q:"Superlative of [[groß]] standing alone", a:["am größten","am größesten","am großten","am größer"], t:"recall", c:0, e:"[[groß]] ends in [[-ß]] but is the one adjective that skips the extra [[e]] — never [[am größesten]]."},
{s:"Comparative and superlative", q:"[[Im Juli ist es ___ als im Mai.]] (warmer)", a:["wärmer","warmer","am wärmsten","mehr warm"], t:"gap", c:0, e:"[[warm]] is a short adjective, so it umlauts: [[wärmer]], [[am wärmsten]]."},
{s:"Comparative and superlative", q:"Why is it [[am kältesten]] but [[am schnellsten]]?", a:["an extra [[e]] goes in before [[-sten]] after [[-d, -t, -s, -ß, -z, -sch]]","[[kalt]] is an irregular adjective","the [[e]] marks the umlaut","longer adjectives always take an extra [[e]]"], t:"rule", c:0, e:"The extra [[e]] just makes the ending sayable: [[am ältesten]], [[am heißesten]] — with [[am größten]] as the exception."},
{s:"Comparative and superlative", q:"Which adjectives take an umlaut in the comparative?", a:["short one-syllable ones such as [[alt]], [[jung]], [[stark]]","any adjective containing [[a]], [[o]] or [[u]]","adjectives of three syllables or more","only adjectives describing size"], t:"rule", c:0, e:"[[alt → älter]], [[stark → stärker]] — but a long adjective like [[interessant]] never umlauts."},
{s:"Comparative and superlative", q:"[[Ich nehme den ___ Weg.]] (shortest)", a:["kürzesten","kürzeste","am kürzesten","kürzer"], t:"gap", c:0, e:"In front of a noun the superlative declines like any adjective, and accusative [[den]] calls for [[-en]]."},
{s:"Comparative and superlative", q:"[[Dieses Buch ist ___ als der Film.]] (more exciting — [[spannend]])", a:["spannender","mehr spannend","am spannendsten","spannendere"], t:"gap", c:0, e:"However long the adjective, German adds [[-er]]; there is no [[mehr spannend]]."},
{s:"Comparative and superlative", q:"[[Anna ist größer als Berta, aber Clara ist am größten.]] Who is shortest?", a:["Berta","Anna","Clara","it cannot be told"], t:"rule", c:0, e:"[[als]] marks the comparison, and [[am größten]] marks the top, so Berta is below Anna, who is below Clara."},
{s:"Comparison patterns", q:"[[Je mehr er übt, desto besser wird er.]] What is being claimed?", a:["practice improves him","he practises too much","he is already the best","practice is not helping"], t:"rule", c:0, e:"[[je … desto …]] links two rising quantities, like English **the more … the better**."},

{s:"Irregular comparisons", q:"Comparative of [[gut]]", a:["besser","guter","gutter","mehr gut"], t:"recall", c:0, e:"[[gut – besser – am besten]]."},
{s:"Irregular comparisons", q:"[[gern]] → ?", a:["lieber","gerner","mehr gern","gernst"], t:"recall", c:0, e:"[[gern – lieber – am liebsten]] expresses preference."},
{s:"Irregular comparisons", q:"Superlative of [[viel]]", a:["am meisten","am vielsten","am mehr","am vielen"], t:"recall", c:0, e:"[[viel – mehr – am meisten]]."},
{s:"Irregular comparisons", q:"Why is the comparative of [[hoch]] written [[höher]] and not [[hocher]]?", a:["the [[c]] drops out before the ending and comes back in [[am höchsten]]","[[höher]] is a different word from [[hoch]]","[[hoch]] has no comparative of its own","German never writes [[ch]] before [[-er]]"], t:"rule", c:0, e:"[[hoch → höher → am höchsten]]: the [[c]] is missing in the middle form only."},
{s:"Irregular comparisons", q:"Superlative of [[nah]]", a:["am nächsten","am nahesten","am nahsten","näher"], t:"recall", c:0, e:"[[nah → näher → am nächsten]]. The same form gives you [[nächste Woche]] for next week."},
{s:"Irregular comparisons", q:"Comparative of [[bald]]", a:["eher","bälder","balder","am ehesten"], t:"recall", c:0, e:"[[bald → eher → am ehesten]]; [[eher]] doubles as **rather** in everyday speech."},
{s:"Irregular comparisons", q:"[[Ich esse gern Fisch, aber ___ Fleisch.]] (prefer)", a:["lieber","gerner","mehr gern","am liebsten"], t:"gap", c:0, e:"[[gern → lieber → am liebsten]] is how German expresses liking, preferring and liking best."},
{s:"Irregular comparisons", q:"[[Heute schmeckt die Suppe ___ als gestern.]] (better)", a:["besser","guter","gütter","am besten"], t:"gap", c:0, e:"[[gut → besser → am besten]]; [[guter]] is only [[gut]] wearing an adjective ending."},
{s:"Irregular comparisons", q:"[[Er verdient ___ Geld als ich.]] (more)", a:["mehr","vieler","viel","am meisten"], t:"gap", c:0, e:"[[viel → mehr → am meisten]], and [[mehr]] itself never takes an ending."},
{s:"Irregular comparisons", q:"Why do [[gut]], [[viel]] and [[gern]] not simply add [[-er]]?", a:["they are irregular, exactly as good, much and gladly are in English","they are adverbs, and adverbs never compare","they are too short to carry an ending","they compare with [[mehr]] instead"], t:"rule", c:0, e:"The irregular comparatives are the same handful of very common words that English breaks too."},

{s:"Comparison patterns", q:"[[Er ist größer ___ ich.]]", a:["als","wie","dann","so"], t:"gap", c:0, e:"[[als]] marks a difference, [[wie]] marks equality."},
{s:"Comparison patterns", q:"[[Je mehr ich lerne, ___ weniger weiß ich.]]", a:["desto","als","wie","umso mehr"], t:"gap", c:0, e:"[[je]] sends the verb to the end, [[desto]] keeps it second."},
{s:"Comparison patterns", q:"[[Es wird ___ kälter.]] (colder and colder)", a:["immer","mehr","sehr","noch"], t:"gap", c:0, e:"[[immer]] + comparative expresses gradual change."},
{s:"Comparison patterns", q:"Why is [[größer wie ich]] wrong?", a:["[[als]] marks a difference, [[wie]] marks equality","[[wie]] is only for questions","[[größer]] takes no comparison word","it should be [[so]]"], t:"rule", c:0, e:"[[größer als ich]], but [[so groß wie ich]]."},
{s:"Comparison patterns", q:"[[Mein Bruder ist genauso alt ___ ich.]]", a:["wie","als","denn","dass"], t:"gap", c:0, e:"Equality takes [[wie]]; only a real difference takes [[als]]."},
{s:"Comparison patterns", q:"In a [[je …, desto …]] sentence, where does the verb go in the [[je]] half?", a:["at the very end","in second position","directly after [[je]]","in front of the comparative"], t:"rule", c:0, e:"[[Je früher du kommst, desto besser ist es]] — [[je]] opens a subordinate clause, [[desto]] a main one with the verb second."},
{s:"Comparison patterns", q:"[[Je mehr er isst, desto ___ wird er.]] (fatter — [[dick]])", a:["dicker","dick","am dicksten","mehr dick"], t:"gap", c:0, e:"Both halves of a [[je …, desto …]] sentence need a comparative, never a plain or superlative form."},
{s:"Comparison patterns", q:"[[Wir fahren mit dem ___ Zug.]] (fastest)", a:["schnellsten","schnellste","am schnellsten","schnellster"], t:"gap", c:0, e:"After dative [[dem]] every adjective ending is [[-en]], the superlative included."},
{s:"Comparison patterns", q:"Which frame means **not as … as**?", a:["[[nicht so … wie]]","[[nicht so … als]]","[[nicht mehr … wie]]","[[kein so … wie]]"], t:"recall", c:0, e:"[[Sie ist nicht so alt wie du.]] Negating the equality frame does not turn [[wie]] into [[als]]."},
{s:"Comparison patterns", q:"Why [[Er läuft am schnellsten]] but [[Er ist der schnellste Läufer]]?", a:["a superlative standing alone after the verb takes [[am …-sten]]; before a noun it declines","[[am]] is used for people and [[der]] for things","[[am schnellsten]] is spoken and [[der schnellste]] written","[[der schnellste]] is really a comparative"], t:"rule", c:0, e:"The declined form is also what you use when the superlative replaces a noun: [[Er ist der schnellste]]."},
{s:"Comparison patterns", q:"[[Die Tage werden immer ___.]] (longer and longer)", a:["länger","langer","am längsten","mehr lang"], t:"gap", c:0, e:"[[immer]] plus a comparative is German's way of saying more and more."},

/* ---------- XII. Nouns ---------- */

{s:"Guessing the gender", q:"What gender is a noun ending in [[-ung]]?", a:["feminine","masculine","neuter","varies"], t:"recall", c:0, e:"[[die Zeitung]], [[die Meinung]]."},
{s:"Guessing the gender", q:"[[das Mädchen]] is neuter because…", a:["[[-chen]] always makes a noun neuter","girls are grammatically neuter","it is a loanword","it is a plural"], t:"rule", c:0, e:"[[-chen]] and [[-lein]] override the base noun's gender."},
{s:"Guessing the gender", q:"In a compound the gender comes from…", a:["the last element","the first element","the longest element","the article of the whole"], t:"rule", c:0, e:"[[die Tür]] + [[der Griff]] = [[der Türgriff]]."},
{s:"Guessing the gender", q:"Which gender do nouns in [[-keit]] and [[-schaft]] take?", a:["[[die]] — both are feminine","[[der]] — both are masculine","[[das]] — both are neuter","[[die]] for [[-keit]], [[der]] for [[-schaft]]"], t:"recall", c:0, e:"[[die Möglichkeit]], [[die Freundschaft]] — as are nouns in [[-ung]], [[-heit]], [[-ion]] and [[-tät]]."},
{s:"Guessing the gender", q:"Which article goes with [[Instrument]]?", a:["das Instrument","der Instrument","die Instrument","dem Instrument"], t:"recall", c:0, e:"[[-ment]] is neuter, and so are [[-um]] ([[das Zentrum]]) and [[-nis]] ([[das Ergebnis]])."},
{s:"Guessing the gender", q:"[[___ Gebäude ist ganz neu.]]", a:["Das","Der","Die","Dem"], t:"gap", c:0, e:"Nouns beginning with [[Ge-]] are usually neuter, like [[das Gebäude]]."},
{s:"Guessing the gender", q:"What gender are [[Montag]], [[Juli]] and [[Frühling]]?", a:["all masculine","all neuter","all feminine","[[Frühling]] is neuter, the other two masculine"], t:"recall", c:0, e:"Days, months and seasons are [[der]] — and so is any noun ending in [[-ling]]."},
{s:"Guessing the gender", q:"You meet a new noun ending in [[-ismus]]. What is the safe guess?", a:["[[der]]","[[die]]","[[das]]","no ending predicts gender"], t:"rule", c:0, e:"[[der Kapitalismus]], like [[der Motor]] in [[-or]] and [[der Lehrer]] in [[-er]]."},
{s:"Guessing the gender", q:"A verb used as a noun, such as [[Essen]] or [[Laufen]], is…", a:["neuter — [[das Essen]], [[das Laufen]]","masculine","feminine","the gender of the nearest related noun"], t:"rule", c:0, e:"Infinitives turned into nouns are always [[das]], and always capitalised."},
{s:"Guessing the gender", q:"[[Hast du ___ Zeitung schon gelesen?]]", a:["die","der","das","den"], t:"gap", c:0, e:"[[-ung]] is feminine, and the feminine article stays [[die]] in the accusative."},
{s:"Guessing the gender", q:"[[Das Mädchen ist groß. Es spielt Fußball.]] Why [[es]] and not [[sie]]?", a:["[[Mädchen]] is grammatically neuter","the girl is very young","the sentence is wrong","[[spielen]] requires [[es]]"], t:"rule", c:0, e:"The [[-chen]] ending makes any noun neuter. Grammatical gender is a fact about the word, not the person."},
{s:"Guessing the gender", q:"[[Die Regierung hat entschieden. Sie tritt morgen zurück.]] Who resigns?", a:["the government","the chancellor","the speaker","nobody yet"], t:"rule", c:0, e:"[[Regierung]] is feminine because of [[-ung]], so [[sie]] points back to it — not to a woman."},

{s:"Forming the plural", q:"Plural of [[das Auto]]", a:["die Autos","die Auten","die Autoe","die Autö"], t:"recall", c:0, e:"Loanwords usually take [[-s]]."},
{s:"Forming the plural", q:"Plural of [[die Lehrerin]]", a:["die Lehrerinnen","die Lehrerins","die Lehrerine","die Lehrerin"], t:"recall", c:0, e:"Feminine [[-in]] doubles the n and adds [[-nen]]."},
{s:"Forming the plural", q:"Which plural article is used?", a:["die, for every gender","der","das","it keeps the singular article"], t:"rule", c:0, e:"All plurals take [[die]] in the nominative."},
{s:"Forming the plural", q:"Plural of [[der Mann]]", a:["die Männer","die Manne","die Männe","die Mannen"], t:"recall", c:0, e:"Short nouns often take [[-er]] plus umlaut: [[Mann → Männer]], [[Haus → Häuser]], [[Buch → Bücher]]."},
{s:"Forming the plural", q:"Plural of [[die Stadt]]", a:["die Städte","die Stadten","die Stadts","die Städter"], t:"recall", c:0, e:"One of the few feminines that does not take [[-(e)n]]: [[die Stadt → die Städte]], like [[die Hand → die Hände]]."},
{s:"Forming the plural", q:"Plural of [[der Lehrer]]", a:["die Lehrer","die Lehrere","die Lehrern","die Lehrers"], t:"recall", c:0, e:"Nouns in [[-er]], [[-en]] and [[-el]] usually add nothing at all — only the article changes."},
{s:"Forming the plural", q:"Which plural ending do almost all feminine nouns take?", a:["[[-(e)n]]","[[-e]] with umlaut","[[-er]] with umlaut","[[-s]]"], t:"rule", c:0, e:"[[die Frau → die Frauen]], [[die Zeitung → die Zeitungen]]; feminines in [[-in]] double the [[n]] — [[die Lehrerinnen]]."},
{s:"Forming the plural", q:"What happens to the noun itself in the dative plural?", a:["it adds an extra [[-n]] unless the plural already ends in [[-n]] or [[-s]]","nothing at all","it loses its umlaut","it adds an [[-s]]"], t:"rule", c:0, e:"[[mit den Kindern]], [[mit den Freunden]] — but [[mit den Autos]] and [[mit den Frauen]] stay as they are."},
{s:"Forming the plural", q:"[[Ich spiele oft mit den ___.]] ([[das Kind]])", a:["Kindern","Kinder","Kinds","Kindes"], t:"gap", c:0, e:"The plural is [[die Kinder]], and the dative plural adds the extra [[-n]]."},
{s:"Forming the plural", q:"[[Wir haben zwei ___ gekauft.]] ([[das Buch]])", a:["Bücher","Buchen","Buche","Buchs"], t:"gap", c:0, e:"Short neuter nouns favour [[-er]] plus umlaut; no dative [[-n]] here, because the object is accusative."},

{s:"Weak nouns (n-declension)", q:"[[Ich sehe den ___.]] ([[der Student]])", a:["Studenten","Student","Studentes","Studentn"], t:"gap", c:0, e:"Weak nouns add [[-en]] in every case but the nominative singular."},
{s:"Weak nouns (n-declension)", q:"Genitive of [[der Name]]", a:["des Namens","des Namen","des Names","der Name"], t:"recall", c:0, e:"[[Name]] is a mixed weak noun and adds [[-s]] in the genitive."},
{s:"Weak nouns (n-declension)", q:"Accusative of [[der Herr]]", a:["den Herrn","den Herren","den Herr","dem Herrn"], t:"recall", c:0, e:"[[Herr]] takes [[-n]] in the singular and [[-en]] in the plural."},
{s:"Weak nouns (n-declension)", q:"[[Ich habe gestern mit dem ___ gesprochen.]] ([[der Nachbar]])", a:["Nachbarn","Nachbar","Nachbars","Nachbaren"], t:"gap", c:0, e:"[[der Nachbar]] is weak, so every case except the nominative singular ends in [[-n]]."},
{s:"Weak nouns (n-declension)", q:"[[Kennst du diesen ___?]] ([[der Junge]])", a:["Jungen","Junge","Junges","Jungem"], t:"gap", c:0, e:"A masculine noun in [[-e]] naming a person is almost always weak: [[den Jungen]], [[den Kunden]], [[den Kollegen]]."},
{s:"Weak nouns (n-declension)", q:"Dative of [[der Mensch]]", a:["dem Menschen","dem Mensch","den Menschen","dem Menschem"], t:"recall", c:0, e:"[[Mensch]] joins [[Herr]], [[Nachbar]] and [[Bauer]] as a weak noun that does not end in [[-e]]."},
{s:"Weak nouns (n-declension)", q:"How do you recognise a weak noun?", a:["a masculine noun in [[-e]] naming a person or animal, or a person-word in [[-ent]], [[-ant]], [[-ist]], [[-at]]","any noun that ends in [[-e]]","any masculine noun","feminine nouns ending in [[-in]]"], t:"rule", c:0, e:"[[der Kollege]], [[der Löwe]], [[der Student]], [[der Polizist]], [[der Soldat]] — and nationalities like [[der Franzose]]."},
{s:"Weak nouns (n-declension)", q:"Which case leaves a weak noun without its [[-n]]?", a:["the nominative singular","the accusative singular","the dative singular","the genitive plural"], t:"rule", c:0, e:"[[der Student]] as subject, but [[den]], [[dem]] and [[des Studenten]] everywhere else."},
{s:"Weak nouns (n-declension)", q:"Genitive of [[der Herr]]", a:["des Herrn","des Herrs","des Herres","des Herren"], t:"recall", c:0, e:"[[Herr]] is the odd one out: just [[-n]] through the singular, [[-en]] in the plural — [[die Herren]]."},
{s:"Weak nouns (n-declension)", q:"[[Wir helfen dem ___.]] ([[der Franzose]])", a:["Franzosen","Franzose","Französen","Franzosem"], t:"gap", c:0, e:"Nationalities ending in [[-e]] are weak, and [[helfen]] calls for the dative in any case."},
{s:"Weak nouns (n-declension)", q:"[[Ich sehe den Studenten.]] How many students?", a:["one — this is the singular accusative","several","two","it cannot be told"], t:"rule", c:0, e:"[[sehen]] takes the accusative, and the accusative plural would be [[die Studenten]]. So [[den]] is what forces the singular — the [[-en]] is the weak-noun case ending, not a plural."},
{s:"Weak nouns (n-declension)", q:"[[Der Junge hilft dem Herrn.]] Who is being helped?", a:["the gentleman","the boy","both help each other","nobody"], t:"rule", c:0, e:"[[helfen]] takes the dative, and [[Herr]] is a weak noun, so its dative singular is [[dem Herrn]]."},

{s:"Compound nouns", q:"[[die Bahnhofstraße]] is feminine because…", a:["[[Straße]] is feminine","[[Bahnhof]] is masculine","of the linking -s","compounds are always feminine"], t:"rule", c:0, e:"The last element carries the gender."},
{s:"Compound nouns", q:"How should a long compound be read?", a:["right to left","left to right","by syllables","by the article"], t:"rule", c:0, e:"The final noun is the head; everything before it modifies it."},
{s:"Compound nouns", q:"The [[-s]] in [[Arbeitsplatz]] is…", a:["a linking sound with no rule worth learning","a genitive","a plural","a typo"], t:"rule", c:0, e:"Linking [[-s]] and [[-n]] follow historical patterns."},
{s:"Compound nouns", q:"[[Meine Schwester spielt in ___ Fußballmannschaft.]]", a:["der","dem","die","das"], t:"gap", c:0, e:"The compound is feminine because [[die Mannschaft]] is, and [[in]] for position takes the dative."},
{s:"Compound nouns", q:"[[das Haus]] + [[die Tür]] gives…", a:["die Haustür","das Haustür","der Haustür","die Türhaus"], t:"recall", c:0, e:"The last element sets the gender; the first element is only there to describe it."},
{s:"Compound nouns", q:"Plural of [[das Krankenhaus]]", a:["die Krankenhäuser","die Krankenhausen","die Krankenhäuse","die Krankenhaus"], t:"recall", c:0, e:"The last element carries the plural as well: [[das Haus → die Häuser]], so [[die Krankenhäuser]]."},
{s:"Compound nouns", q:"Which part of a compound carries the plural and the case ending?", a:["the last element","the first element","every element","whichever element is longest"], t:"rule", c:0, e:"Everything in front of the last element is pure description and never takes a case or plural ending — though a linking [[-s]] or [[-n]] may appear at the seam ([[Arbeitsplatz]], [[Krankenhaus]])."},
{s:"Compound nouns", q:"Which words does German capitalise?", a:["every noun, including nouns made from verbs and adjectives — [[das Laufen]], [[etwas Neues]]","only proper names","only the first noun in a sentence","nouns and the adjectives in front of them"], t:"rule", c:0, e:"If a word is being used as a noun it takes a capital, whatever part of speech it started as."},
{s:"Compound nouns", q:"[[Können ___ mir bitte helfen?]] (formal you)", a:["Sie","sie","du","ihr"], t:"gap", c:0, e:"Formal [[Sie]] and [[Ihr]] are always capitalised; informal [[du]] and [[ihr]] are lower case by default."},
{s:"Compound nouns", q:"[[die Geschwindigkeit]] + [[die Begrenzung]] gives…", a:["die Geschwindigkeitsbegrenzung","die Begrenzungsgeschwindigkeit","die Geschwindigkeitbegrenzung","das Geschwindigkeitsbegrenzung"], t:"recall", c:0, e:"The head noun comes last, and a linking [[-s]] appears at the seam, as in [[Arbeitsplatz]]."},

{s:"Countries and nationalities", q:"[[Ich fahre ___ Schweiz.]]", a:["in die","nach","zu der","auf die"], t:"gap", c:0, e:"Countries with an article take [[in]] + accusative for movement."},
{s:"Countries and nationalities", q:"[[Ich fahre ___ Berlin.]]", a:["nach","in die","zu","an"], t:"gap", c:0, e:"[[nach]] for places that take no article."},
{s:"Countries and nationalities", q:"Which is correct?", a:["Ich spreche Deutsch.","Ich spreche Deutsche.","Ich spreche der Deutsch.","Ich spreche Deutscher."], t:"rule", c:0, e:"A language name is a capitalised noun. Only the adjective is lower case: [[ein deutsches Auto]]."},
{s:"Countries and nationalities", q:"[[Meine Tante wohnt ___ Türkei.]]", a:["in der","in die","nach","in dem"], t:"gap", c:0, e:"[[die Türkei]] carries an article, so position is [[in]] plus the dative."},
{s:"Countries and nationalities", q:"[[Nächstes Jahr fliegen wir ___ USA.]]", a:["in die","in den","nach","in der"], t:"gap", c:0, e:"[[die USA]] is plural, and movement takes the accusative — position would be [[in den USA]]."},
{s:"Countries and nationalities", q:"When do you use [[nach]] with a country and when [[in]]?", a:["[[nach]] for countries with no article, [[in]] for those that carry one","[[nach]] for movement, [[in]] for position","[[nach]] only for European countries","they are interchangeable"], t:"rule", c:0, e:"[[nach Deutschland]], [[nach Japan]] — but [[in die Schweiz]], [[in den Iran]]. People and businesses take [[zu]]."},
{s:"Countries and nationalities", q:"Which country name is masculine?", a:["[[der Iran]]","[[der Schweiz]]","[[der Türkei]]","[[der Niederlande]]"], t:"recall", c:0, e:"[[die Schweiz]] and [[die Türkei]] are feminine, [[die Niederlande]] and [[die USA]] plural."},
{s:"Countries and nationalities", q:"[[Sie kommt ___ Schweiz.]] (from)", a:["aus der","aus die","von der","aus"], t:"gap", c:0, e:"Coming from somewhere is [[aus]]: [[aus Deutschland]] without an article, [[aus der Schweiz]] with one."},
{s:"Countries and nationalities", q:"The feminine of [[der Franzose]] is…", a:["die Französin","die Franzosin","die Französe","die Franzosine"], t:"recall", c:0, e:"[[-in]] makes the feminine, and here the stem umlauts too; compare [[der Türke]] → [[die Türkin]]."},
{s:"Countries and nationalities", q:"Which is right — [[ein deutsches Auto]] or [[ein Deutsches Auto]]?", a:["[[ein deutsches Auto]] — the adjective stays lower case","[[ein Deutsches Auto]] — nationality words are always capitalised","both are correct","neither; it is [[ein Deutsch Auto]]"], t:"rule", c:0, e:"[[Deutsch]] the language and [[der Deutsche]] the person take capitals; [[deutsch]] the adjective does not."},

/* ---------- XIII. Usage ---------- */

{s:"Impersonal es", q:"[[Es gibt ___ Grund.]]", a:["einen","ein","einem","eines"], t:"gap", c:0, e:"[[es gibt]] always takes the accusative."},
{s:"Impersonal es", q:"[[___ geht mir gut.]] / [[Mir geht ___ gut.]]", a:["Es … es","Es … —","Das … es","Ich … es"], t:"gap", c:0, e:"[[es]] moves out of first position but stays in the clause."},
{s:"Impersonal es", q:"[[Es ist mir kalt]] uses which case for [[mir]]?", a:["dative","accusative","nominative","genitive"], t:"recall", c:0, e:"Expressions of how someone feels take the dative."},
{s:"Impersonal es", q:"Why does German say [[es regnet]] rather than just [[regnet]]?", a:["a German sentence needs a subject","[[es]] means the sky","it is more polite","to keep the verb second"], t:"rule", c:0, e:"[[es]] is a placeholder subject where nothing is really acting."},
{s:"Impersonal es", q:"Which is correct German for **there are many problems**?", a:["Es gibt viele Probleme.","Es geben viele Probleme.","Es gibt viele Problemen.","Sie gibt viele Probleme."], t:"recall", c:0, e:"[[es gibt]] never changes for number — the same [[gibt]] serves both **there is** and **there are**."},
{s:"Impersonal es", q:"**There is nobody at home.** Which German sentence does the book give?", a:["Es ist niemand zu Hause.","Es gibt niemanden zu Hause.","Es gibt niemand zu Hause.","Es sind niemand zu Hause."], t:"rule", c:0, e:"Use [[es ist]] or [[es sind]] for a specific thing in a specific place; keep [[es gibt]] for existence in general."},
{s:"Impersonal es", q:"In which sentence does [[es]] disappear altogether rather than just move out of first position?", a:["Mir ist kalt.","Mir geht es gut.","Heute regnet es.","Hier gibt es ein Café."], t:"rule", c:0, e:"[[Es ist mir kalt]] loses its [[es]] completely once [[mir]] leads; elsewhere [[es]] gives up first position but stays in the clause."},
{s:"Impersonal es", q:"Which of these expressions takes an **accusative** object rather than a dative one?", a:["es gibt","es gefällt mir","es tut mir leid","es fehlt mir"], t:"rule", c:0, e:"[[es gibt]] is the odd one out: [[es gibt einen Grund]], while the feeling expressions all take the dative."},
{s:"Impersonal es", q:"[[Es tut ___ leid.]] (**I am sorry**)", a:["mir","mich","ich","meiner"], t:"gap", c:0, e:"The person who feels something stands in the dative: [[es tut mir leid]], [[es geht mir gut]], [[es fehlt mir]]."},
{s:"Impersonal es", q:"Which sentence means **it is thundering**?", a:["Es donnert.","Es schneit.","Es friert.","Es wird hell."], t:"recall", c:0, e:"Weather verbs have no real subject, so [[es]] fills the subject slot: [[es donnert]], [[es schneit]], [[es friert]]."},
{s:"Impersonal es", q:"[[Im Dezember ___ es hier oft.]] (**snows**)", a:["schneit","schneien","schneist","schneiet"], t:"gap", c:0, e:"Impersonal [[es]] is always third person singular, so the verb takes the [[er/sie/es]] ending whatever else is in the sentence."},

{s:"Modal particles", q:"[[Komm doch mit!]] — what does [[doch]] add?", a:["gentle encouragement","a negative","a question","past time"], t:"recall", c:0, e:"Particles colour a sentence without adding information."},
{s:"Modal particles", q:"[[Du kommst nicht mit?]] How do you contradict this?", a:["Doch!","Ja!","Nein!","Schon!"], t:"recall", c:0, e:"[[doch]] contradicts a negative question; [[ja]] would agree with it."},
{s:"Modal particles", q:"Where do modal particles sit?", a:["in the middle field","first","last","after the subject only"], t:"rule", c:0, e:"They are never in first position and never stressed."},
{s:"Modal particles", q:"Which particle signals resignation — **that is just how it is**?", a:["halt","denn","ja","wohl"], t:"recall", c:0, e:"[[Das ist halt so.]] [[eben]] does the same job with a slightly sharper edge."},
{s:"Modal particles", q:"[[Er ist wohl krank.]] What does [[wohl]] add?", a:["the speaker is assuming it — presumably he is ill","the speaker has seen him and knows it for certain","the speaker is urging him to stay in bed","the speaker is contradicting a denial"], t:"rule", c:0, e:"[[wohl]] marks the sentence as the speaker's guess; drop it and the same words become a statement of fact."},
{s:"Modal particles", q:"[[Warte ___, ich komme sofort.]] (soften the request — **hang on a sec**)", a:["mal","wohl","halt","eigentlich"], t:"gap", c:0, e:"[[mal]] takes the edge off an imperative; without it [[Warte!]] sounds like an order."},
{s:"Modal particles", q:"[[Was machst du ___ da?]] (a friendly, softened question)", a:["denn","halt","ja","eben"], t:"gap", c:0, e:"[[denn]] belongs to questions: it turns an interrogation into ordinary curiosity."},
{s:"Modal particles", q:"[[schon]], [[eben]] and [[doch]] also exist as ordinary adverbs. What tells the particle use from the adverb use?", a:["its position in the clause and whether it is stressed","the case of the noun that follows","whether the verb is strong or weak","whether the sentence is main or subordinate"], t:"rule", c:0, e:"Particles sit unstressed in the middle field and never in first position; the full adverbs [[schon]] **already** and [[eben]] **just now** can be stressed and can lead the clause."},
{s:"Modal particles", q:"[[Das ist ja klar.]] What is the speaker doing with [[ja]]?", a:["appealing to something both of them already know","expressing doubt about it","asking for confirmation","agreeing with a negative question"], t:"rule", c:0, e:"[[ja]] as a particle points at shared knowledge — nothing like [[ja]] as the answer **yes**."},
{s:"Modal particles", q:"[[Das stimmt ___, aber es ist zu teuer.]] (conceding the point)", a:["schon","mal","denn","halt"], t:"gap", c:0, e:"[[schon]] concedes before an objection, roughly English **true enough, but…**"},

{s:"False friends", q:"[[Ich bekomme ein Bier.]] means…", a:["I am getting a beer","I am becoming a beer","I like beer","I am buying a beer"], t:"recall", c:0, e:"[[bekommen]] is to receive; to become is [[werden]]."},
{s:"False friends", q:"[[aktuell]] means…", a:["current","actually","accurate","actual size"], t:"recall", c:0, e:"\"Actually\" is [[eigentlich]]."},
{s:"False friends", q:"[[das Gift]] means…", a:["poison","present","talent","gift shop"], t:"recall", c:0, e:"A present is [[das Geschenk]]."},
{s:"False friends", q:"Why is [[bekommen]] the costliest false friend?", a:["it looks like **become** but means **receive**","it is spelt like an English word","it has two meanings","it is irregular"], t:"rule", c:0, e:"[[Ich bekomme ein Bier]] orders a beer. To become is [[werden]]."},
{s:"False friends", q:"A colleague says [[Das ist mein Chef]]. Who is she talking about?", a:["her boss","the cook","the head waiter","the company owner"], t:"recall", c:0, e:"[[der Chef]] is the boss; an English *chef* is [[der Koch]]."},
{s:"False friends", q:"[[Das war eine sehr ___ Entscheidung.]] (**sensible**)", a:["vernünftige","sensible","empfindliche","brave"], t:"gap", c:0, e:"[[sensibel]] means **sensitive**, not sensible — the word you want is [[vernünftig]]."},
{s:"False friends", q:"Which gloss is the correct one?", a:["[[brav]] = **well-behaved**","[[eventuell]] = **eventually**","[[sensibel]] = **sensible**","[[fast]] = **fast**"], t:"rule", c:0, e:"[[brav]] is well-behaved (brave = [[mutig]]); [[eventuell]] is possibly (eventually = [[schließlich]]); [[fast]] is almost (fast = [[schnell]])."},
{s:"False friends", q:"Which German word means **also, too, as well**?", a:["auch","also","eben","sowohl"], t:"recall", c:0, e:"German [[also]] means **so, therefore** — it opens a conclusion, it never adds an item to a list."},
{s:"False friends", q:"What is [[der See]]?", a:["a lake","the sea","a view","a harbour"], t:"recall", c:0, e:"[[der See]] is a lake and [[die See]] is the sea — same word, two genders, two meanings. [[das Meer]] is the safer word for sea."},
{s:"False friends", q:"[[Sie trägt heute einen ___.]] (**skirt**)", a:["Rock","Stein","Chef","Art"], t:"gap", c:0, e:"[[der Rock]] is a skirt; a rock in the ground is [[der Stein]]."},
{s:"False friends", q:"[[Er will Arzt ___.]] (**become**)", a:["werden","bekommen","behalten","spenden"], t:"gap", c:0, e:"**To become** is [[werden]]. [[bekommen]] means **to receive**, so [[ich bekomme ein Bier]] orders a beer rather than announcing a transformation."},

/* ---------- XIV. Reference ---------- */

{s:"Verbs that take the dative", q:"[[Ich danke ___.]]", a:["dir","dich","deiner","du"], t:"gap", c:0, e:"[[danken]] takes a dative object."},
{s:"Verbs that take the dative", q:"Which verb does NOT take the dative?", a:["sehen","helfen","folgen","gefallen"], t:"recall", c:0, e:"[[sehen]] takes an accusative object."},
{s:"Verbs that take the dative", q:"Why can dative verbs not form a normal passive?", a:["they have no accusative object to promote","they are irregular","they are always reflexive","they take [[sein]]"], t:"rule", c:0, e:"The passive promotes an accusative object to subject."},
{s:"Verbs that take the dative", q:"[[Kannst du ___ helfen?]] (**me**)", a:["mir","mich","ich","meiner"], t:"gap", c:0, e:"[[helfen]] has no accusative object at all — its one object is dative: [[ich helfe dir]], never [[ich helfe dich]]."},
{s:"Verbs that take the dative", q:"[[Das Buch gehört ___ Lehrerin.]]", a:["der","die","den","dem"], t:"gap", c:0, e:"[[gehören]] takes the dative, and the dative singular of a feminine noun is [[der]]."},
{s:"Verbs that take the dative", q:"[[Die Jacke passt ihm nicht.]] means…", a:["the jacket does not fit him","he does not like the jacket","he did not pass the jacket on","the jacket does not belong to him"], t:"recall", c:0, e:"[[passen]] means **to suit or fit** and takes a dative person; **to belong to** is [[gehören]], also dative."},
{s:"Verbs that take the dative", q:"Why is it [[Ich folge dem Auto]] and not [[Ich folge das Auto]]?", a:["[[folgen]] is one of the verbs whose single object is dative","[[Auto]] is neuter, so it can only stand in the dative","every verb of motion governs the dative","the accusative is reserved for the subject"], t:"rule", c:0, e:"A short list of common verbs — [[helfen, danken, folgen, gehören, passen, gefallen, antworten]] — takes a dative object where English has a direct one. There is no pattern; they are learnt as a list."},
{s:"Verbs that take the dative", q:"[[Der Film gefällt ___ Kindern.]]", a:["den","die","der","dem"], t:"gap", c:0, e:"Dative plural is [[den]] plus an [[-n]] on the noun: [[den Kindern]]. Note that in German the film pleases the children rather than the children liking the film."},
{s:"Verbs that take the dative", q:"Which is correct German for **Answer me!**", a:["Antworte mir!","Antworte mich!","Antworte an mich!","Antworte zu mir!"], t:"rule", c:0, e:"[[antworten]] takes a dative person and no preposition; you answer *to* someone in German, not *at* them."},
{s:"Verbs that take the dative", q:"[[Sie schenkt ___ Bruder eine Uhr.]] (**her** brother)", a:["ihrem","ihren","ihr","seinem"], t:"gap", c:0, e:"[[schenken]] takes both cases at once — dative person, accusative thing — so the brother is [[ihrem Bruder]] and the watch is [[eine Uhr]]."},
{s:"Verbs that take the dative", q:"[[Das Buch gehört meiner Schwester.]] Who owns the book?", a:["my sister","the book's author","nobody is stated","I do"], t:"rule", c:0, e:"[[gehören]] takes a dative object, so the dative names the owner even though English makes it the subject."},
{s:"Verbs that take the dative", q:"[[Der Film gefällt mir.]] What is the grammatical subject?", a:["[[der Film]]","[[mir]]","there is none","[[gefallen]]"], t:"rule", c:0, e:"German says the film pleases me. The person is dative, which is why [[ich gefalle den Film]] is nonsense."},

{s:"Verbs with fixed prepositions", q:"[[Ich warte ___ den Bus.]]", a:["auf","für","an","nach"], t:"gap", c:0, e:"[[warten auf]] + accusative."},
{s:"Verbs with fixed prepositions", q:"[[Ich interessiere mich ___ Musik.]]", a:["für","an","auf","über"], t:"gap", c:0, e:"[[sich interessieren für]] + accusative."},
{s:"Verbs with fixed prepositions", q:"[[Das hängt ___ dir ab.]]", a:["von","auf","an","für"], t:"gap", c:0, e:"[[abhängen von]] + dative."},
{s:"Verbs with fixed prepositions", q:"[[Ich freue mich ___ die Ferien.]] (**look forward to** the holidays)", a:["auf","über","für","an"], t:"gap", c:0, e:"[[sich freuen auf]] plus accusative points forward in time; [[die Ferien]] shows the accusative here."},
{s:"Verbs with fixed prepositions", q:"Someone has just handed you a present. Which do you say?", a:["Ich freue mich über das Geschenk.","Ich freue mich auf das Geschenk.","Ich freue mich an dem Geschenk.","Ich freue mich für das Geschenk."], t:"rule", c:0, e:"[[sich freuen über]] is pleasure at something that has happened; [[sich freuen auf]] is anticipation of something still to come. Both take the accusative."},
{s:"Verbs with fixed prepositions", q:"Which preposition is locked to [[denken]] in the sense **to think of**?", a:["an","auf","über","für"], t:"recall", c:0, e:"[[denken an]] takes the accusative: [[ich denke an dich]]. [[denken über]] exists only in the sense of holding an opinion."},
{s:"Verbs with fixed prepositions", q:"[[Wir warten auf ___ Zug.]]", a:["den","dem","der","des"], t:"gap", c:0, e:"[[warten auf]] fixes [[auf]] to the accusative, so a two-way preposition that could take either case here can only be accusative."},
{s:"Verbs with fixed prepositions", q:"[[Ich fürchte mich nicht ___ Hunden.]] (**afraid of** dogs)", a:["vor","von","für","über"], t:"gap", c:0, e:"[[sich fürchten vor]] takes the dative — which is why the plural [[Hunde]] appears as [[Hunden]]."},
{s:"Verbs with fixed prepositions", q:"You are waiting for the train. How do you say **I am waiting for it**?", a:["Ich warte darauf.","Ich warte auf es.","Ich warte dafür.","Ich warte es."], t:"rule", c:0, e:"For a thing, fuse the preposition into a [[da(r)-]] compound; keep preposition plus pronoun only for people: [[ich warte auf ihn]]."},
{s:"Verbs with fixed prepositions", q:"Which case does [[teilnehmen an]] take?", a:["Dative","Accusative","Genitive","It varies with the meaning"], t:"recall", c:0, e:"[[an]] is a two-way preposition, but in a fixed pairing the case is settled once and for all — dative here, accusative in [[denken an]]."},

{s:"Numbers", q:"How is 47 written?", a:["siebenundvierzig","vierzigsieben","vierundsiebzig","siebzigvier"], t:"recall", c:0, e:"Units come before tens, joined by [[und]], all as one word."},
{s:"Numbers", q:"What does [[1.000,50]] mean in German?", a:["one thousand point five","one point zero zero zero five","one and a half","ten thousand and five"], t:"rule", c:0, e:"The separators are the reverse of English."},
{s:"Numbers", q:"Which is spelled irregularly?", a:["dreißig","fünfzig","vierzig","achtzig"], t:"recall", c:0, e:"[[dreißig]] uses [[ß]]; [[sechzig]] and [[siebzig]] are shortened."},
{s:"Numbers", q:"How is 365 written as one German word?", a:["dreihundertfünfundsechzig","dreihundertsechsundfünfzig","dreihundertsechzigfünf","dreihundertfünfzigsechs"], t:"recall", c:0, e:"Hundreds first, then units, then tens — the units-before-tens order survives inside the bigger number."},
{s:"Numbers", q:"How is the year 2026 spoken?", a:["zweitausendsechsundzwanzig","zweitausendzwanzigsechs","zwanzighundertsechsundzwanzig","zweitausendundzwanzigsechs"], t:"recall", c:0, e:"Years from 2000 on are read as ordinary numbers; years before that use the hundreds pattern, as in [[neunzehnhundertneunundneunzig]]."},
{s:"Numbers", q:"[[Das kostet nur ___ Euro.]] (1)", a:["einen","eins","ein","eine"], t:"gap", c:0, e:"[[eins]] drops its [[-s]] in front of a noun and then declines like the article — accusative masculine [[einen]] after [[kosten]]."},
{s:"Numbers", q:"[[Mein Bruder ist ___ Jahre alt.]] (36)", a:["sechsunddreißig","dreißigundsechs","dreiundsechzig","sechzigunddrei"], t:"gap", c:0, e:"Units first, joined by [[und]]: 36 is six-and-thirty. [[dreiundsechzig]] is 63 — the mirror image, and the classic slip."},
{s:"Numbers", q:"In [[einundzwanzig]], which part is spoken first?", a:["the units, then [[und]], then the tens","the tens, then [[und]], then the units","the tens alone, with the units added as a separate word","it depends on whether the number is even"], t:"rule", c:0, e:"German says the small digit first throughout the tens, which is why numbers have to be held in the head before being written down."},
{s:"Numbers", q:"Which word is 19?", a:["neunzehn","neunzig","neunundzehn","zehnneun"], t:"recall", c:0, e:"[[-zehn]] makes the teens, [[-zig]] makes the tens: [[neunzehn]] 19 against [[neunzig]] 90."},
{s:"Numbers", q:"How is 1 000 000 written?", a:["eine Million","ein Million","eine Millionen","tausendtausend"], t:"recall", c:0, e:"[[Million]] is a feminine noun and stands as a separate capitalised word, unlike [[hundert]] and [[tausend]], which glue on to the number."},

{s:"Time and date", q:"[[halb neun]] is…", a:["8:30","9:30","9:00","8:00"], t:"recall", c:0, e:"It means half way to nine, not half past nine."},
{s:"Time and date", q:"[[___ Mai]] (in May)", a:["im","in","am","um"], t:"gap", c:0, e:"[[in dem]] contracts to [[im]] for months and seasons."},
{s:"Time and date", q:"How do you say \"in 2026\"?", a:["2026 or im Jahr 2026","in 2026","am 2026","um 2026"], t:"rule", c:0, e:"German does not use a preposition with a bare year."},
{s:"Time and date", q:"8:45 in everyday speech is…", a:["Viertel vor neun","Viertel vor acht","Viertel nach neun","halb neun"], t:"recall", c:0, e:"Quarters look forward to the coming hour: [[Viertel vor neun]] at 8:45, [[Viertel nach acht]] at 8:15."},
{s:"Time and date", q:"[[Der Zug fährt um ___ ab.]] (7:30, colloquially)", a:["halb acht","halb sieben","halb nach sieben","sieben und halb"], t:"gap", c:0, e:"[[halb]] names the hour being approached, so [[halb acht]] is half way to eight, i.e. 7:30."},
{s:"Time and date", q:"It is 8:40 and your friend uses [[vor]]. Which hour will he name?", a:["nine — [[zwanzig vor neun]]","eight — [[zwanzig vor acht]]","eight — [[vierzig nach acht]]","nine — [[zwanzig nach neun]]"], t:"rule", c:0, e:"[[vor]] counts down to the next hour, so the number you hear is always one ahead of the hour on the clock."},
{s:"Time and date", q:"[[Wir treffen uns ___ Montag.]]", a:["am","im","um","an"], t:"gap", c:0, e:"[[am]] for days and dates, [[im]] for months and seasons, [[um]] for clock times."},
{s:"Time and date", q:"[[Mein Geburtstag ist am ___ Mai.]] (1st)", a:["ersten","erste","eins","erst"], t:"gap", c:0, e:"The ordinal behaves like an adjective, so after the dative [[am]] it ends in [[-en]]: [[der erste Mai]] but [[am ersten Mai]]."},
{s:"Time and date", q:"How is a German letter dated?", a:["Berlin, den 1. Mai 2026","Berlin, der 1. Mai 2026","Berlin, am 1. Mai 2026","Berlin, im 1. Mai 2026"], t:"recall", c:0, e:"The letter head uses the accusative [[den]]; a date in a sentence takes [[am]], and a year stands alone or as [[im Jahr 2026]] — never [[in 2026]]."},
{s:"Time and date", q:"8:15 announced in the official style is…", a:["acht Uhr fünfzehn","acht Uhr und fünfzehn","fünfzehn nach acht Uhr","acht fünfzehn Uhr"], t:"recall", c:0, e:"Official time simply reads the digits after [[Uhr]], which is why timetables and stations avoid [[Viertel]] and [[halb]] altogether."},

{s:"A weak verb in full: machen", q:"What is the [[ihr]] form of [[machen]] in the Präteritum?", a:["machtet","machtest","machten","machte"], t:"recall", c:0, e:"Weak Präteritum endings: -te, -test, -te, -ten, -tet, -ten."},
{s:"A weak verb in full: machen", q:"[[Ich ___ gemacht]] — Plusquamperfekt", a:["hatte","habe","werde","wäre"], t:"gap", c:0, e:"The pluperfect is the perfect with the auxiliary in the Präteritum."},
{s:"A weak verb in full: machen", q:"Which form is used **instead of** the Konjunktiv II of [[machen]]?", a:["würde machen","hätte gemacht","mache","machen würde haben"], t:"recall", c:0, e:"A weak verb's Konjunktiv II ([[machte]]) is identical to its Präteritum, so [[würde]] + infinitive is used instead."},
{s:"A weak verb in full: machen", q:"[[Was ___ du gestern gemacht?]]", a:["hast","hat","bist","wirst"], t:"gap", c:0, e:"[[machen]] builds its Perfekt with [[haben]]: [[ich habe gemacht]], [[du hast gemacht]]."},
{s:"A weak verb in full: machen", q:"What is the [[Sie]] imperative of [[machen]]?", a:["Machen Sie!","Mach Sie!","Macht Sie!","Sie machen!"], t:"recall", c:0, e:"The polite imperative keeps the infinitive form and puts [[Sie]] straight after it — unlike [[Mach!]] and [[Macht!]], which name no pronoun."},
{s:"A weak verb in full: machen", q:"[[___ bitte das Fenster auf, Anna!]]", a:["Mach","Machst","Macht","Machen"], t:"gap", c:0, e:"The [[du]] imperative of a weak verb is the bare stem, and the separable prefix [[auf]] stays at the end of the clause."},
{s:"A weak verb in full: machen", q:"What is the [[ihr]] form of [[machen]] in the Futur I?", a:["werdet machen","werden machen","wirst machen","werdet gemacht"], t:"recall", c:0, e:"Futur I is [[werden]] conjugated plus the infinitive at the end — only [[werden]] carries the person."},
{s:"A weak verb in full: machen", q:"What in the Präteritum shows that [[machen]] is a weak verb?", a:["the stem [[mach-]] is untouched and a [[-te-]] is slipped in before the ending","the stem vowel changes to [[a]]","the participle ends in [[-en]]","it forms the Perfekt with [[sein]]"], t:"rule", c:0, e:"[[machte, machtest, machte]] — every regular verb in the language does exactly this, so one pattern covers thousands of verbs."},
{s:"A weak verb in full: machen", q:"[[Es wird gemacht.]] Which form is this?", a:["the passive — [[werden]] plus the Partizip II","the Futur I","the Perfekt","the Konjunktiv II"], t:"rule", c:0, e:"The passive reuses the participle you already know: [[es wird gemacht]], [[es wurde gemacht]], [[es ist gemacht worden]]."},
{s:"A weak verb in full: machen", q:"[[Was ___ ihr am Wochenende?]]", a:["macht","machet","machst","machen"], t:"gap", c:0, e:"[[ihr macht]] is identical to [[er macht]] — context and word order, not the ending, tell them apart."},

{s:"A strong verb in full: sprechen", q:"What is the [[du]] form of [[sprechen]] in the present?", a:["sprichst","sprechst","sprachst","sprichest"], t:"recall", c:0, e:"e becomes i in the du and er forms."},
{s:"A strong verb in full: sprechen", q:"What is the [[du]] imperative of [[sprechen]]?", a:["Sprich!","Sprech!","Spreche!","Sprichst!"], t:"recall", c:0, e:"e to i verbs keep the vowel change in the imperative."},
{s:"A strong verb in full: sprechen", q:"What is the Partizip II of [[sprechen]]?", a:["gesprochen","gesprecht","gesprachen","sprochen"], t:"recall", c:0, e:"Strong participles end in -en and often change the vowel."},
{s:"A strong verb in full: sprechen", q:"What is the [[ich]] form of [[sprechen]] in the Präteritum?", a:["sprach","sprachte","spricht","gesprochen"], t:"recall", c:0, e:"A strong verb has its own Präteritum stem and adds no [[-te-]]; [[ich]] and [[er]] take no ending at all: [[ich sprach]], [[er sprach]]."},
{s:"A strong verb in full: sprechen", q:"[[Gestern ___ wir lange über das Problem.]] (Präteritum)", a:["sprachen","sprachten","sprechen","gesprochen"], t:"gap", c:0, e:"Plural endings are added to the Präteritum stem [[sprach-]]: [[wir sprachen]], [[ihr spracht]]."},
{s:"A strong verb in full: sprechen", q:"Which of these is NOT a feature of a strong verb like [[sprechen]]?", a:["the Präteritum is built by inserting [[-te-]] after the stem","the stem vowel shifts in the [[du]] and [[er]] forms of the present","the Präteritum has a stem vowel of its own","the Partizip II ends in [[-en]]"], t:"rule", c:0, e:"The [[-te-]] Präteritum is the mark of a weak verb; a strong verb changes its vowel instead."},
{s:"A strong verb in full: sprechen", q:"What is the [[ich]] form of [[sprechen]] in the Konjunktiv II?", a:["spräche","sprachte","sprache","spreche"], t:"recall", c:0, e:"Strong Konjunktiv II is the Präteritum stem with an umlaut — though outside writing most speakers say [[würde sprechen]]."},
{s:"A strong verb in full: sprechen", q:"[[Er ___ sehr gut Deutsch.]]", a:["spricht","sprecht","sprichst","sprechst"], t:"gap", c:0, e:"The vowel shift [[e]] → [[i]] hits the [[du]] and [[er/sie/es]] forms of the present: [[du sprichst]], [[er spricht]]."},
{s:"A strong verb in full: sprechen", q:"Why is it [[ihr sprecht]] and not [[ihr spricht]]?", a:["the vowel change affects only the [[du]] and [[er/sie/es]] forms","[[ihr]] forms never take an ending","the vowel change happens only in the Präteritum","[[sprechen]] is weak in the plural"], t:"rule", c:0, e:"Only two cells of the present tense change vowel; [[wir]], [[ihr]] and [[sie]] keep the plain infinitive stem [[sprech-]]."},
{s:"A strong verb in full: sprechen", q:"[[Ich ___ morgen mit dem Chef sprechen.]] (Futur I)", a:["werde","wirst","wird","werdet"], t:"gap", c:0, e:"Futur I is [[werden]] in the right person plus the infinitive at the end of the clause, exactly as for a weak verb."},

/* ---------- XV. Strong Verbs ---------- */

{s:"Strong and irregular verbs: beginnen – fliegen", q:"Partizip II of [[bleiben]]", a:["ist geblieben","hat geblieben","ist gebleibt","hat gebliebt"], t:"recall", c:0, e:"[[bleiben]] is one of the three special verbs that take [[sein]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"Präteritum of [[bringen]]", a:["brachte","brang","bringte","gebracht"], t:"recall", c:0, e:"A mixed verb: new vowel, weak endings."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"Which vowel pattern does [[finden]] follow?", a:["i–a–u","ei–ie–ie","ie–o–o","a–u–a"], t:"recall", c:0, e:"[[finden, fand, gefunden]], like [[singen]] and [[trinken]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"What makes a verb strong rather than weak?", a:["the stem vowel changes in the past","it takes [[sein]]","it is irregular in the present only","it has a prefix"], t:"rule", c:0, e:"[[singen, sang, gesungen]] against weak [[spielen, spielte, gespielt]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"What is the Präteritum of [[beginnen]]?", a:["begann","begonnen","beginnte","begunn"], t:"recall", c:0, e:"[[beginnen]] runs i–a–o: [[begann]] in the Präteritum, [[begonnen]] as the participle — the same shape as [[gewinnen]] (gewann, gewonnen)."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"What is the Partizip II of [[essen]], with its auxiliary?", a:["hat gegessen","hat geessen","ist gegessen","hat gegesst"], t:"recall", c:0, e:"[[essen]] swallows an extra syllable: [[gegessen]], not [[geessen]]. Eating is not motion, so the auxiliary is [[haben]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"Which line gives the three principal parts of [[fliegen]] correctly?", a:["fliegen – flog – ist geflogen","fliegen – flog – hat geflogen","fliegen – flug – ist geflogen","fliegen – flieg – ist gefliegen"], t:"recall", c:0, e:"[[fliegen]] is the ie–o–o family, along with [[bieten]] (bot, geboten) and [[verlieren]]. Flying takes you from A to B, so [[sein]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"Which verb on this page takes [[sein]] in the Perfekt even though nothing moves?", a:["bleiben","bringen","brechen","bieten"], t:"rule", c:0, e:"[[ist geblieben]]. [[sein]] covers a change of state as well as motion — and staying put is a state. Only four verbs on this page take it: [[bleiben, fahren, fallen, fliegen]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"[[bringen]] and [[denken]] sit among the strong verbs. What is odd about them?", a:["They change the stem vowel and add the weak [[-te]]/[[-t]] endings","They change the stem vowel and nothing else","They add [[-te]] with no vowel change at all","They are completely regular and only look strange"], t:"rule", c:0, e:"[[brachte, gebracht]] and [[dachte, gedacht]] do both jobs at once. These mixed verbs are the reason the table is headed irregular rather than simply strong."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"Which verb also changes its vowel in the [[er/sie/es]] form of the present?", a:["brechen → [[bricht]]","bleiben → [[bleibt]]","beginnen → [[beginnt]]","bringen → [[bringt]]"], t:"rule", c:0, e:"A strong past does not guarantee a present change — that is why the table has a separate [[er/sie/es]] column. Short [[e]] goes to [[i]]: [[bricht, isst]]; long [[e]] goes to [[ie]]: [[empfiehlt]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"[[Der Kellner ___ mir den Fisch.]] (recommends)", a:["empfiehlt","empfehlt","empfielt","empfahlt"], t:"gap", c:0, e:"[[empfehlen]] takes the long change [[e → ie]]: [[du empfiehlst, er/sie empfiehlt]], but [[wir/ihr empfehlen/empfehlt]] keep the [[e]]."},
{s:"Strong and irregular verbs: beginnen – fliegen", q:"[[Ich ___ gestern mit dem Zug nach Berlin gefahren.]]", a:["bin","habe","hat","ist"], t:"gap", c:0, e:"[[fahren]] is a verb of motion, so the table gives [[ist gefahren]]. Choose the auxiliary from the table, then put it in the right person: [[ich bin gefahren]]."},

{s:"Strong and irregular verbs: geben – lügen", q:"Partizip II of [[gehen]]", a:["ist gegangen","hat gegangen","ist gegehen","hat gegeht"], t:"recall", c:0, e:"Motion verb → [[sein]]."},
{s:"Strong and irregular verbs: geben – lügen", q:"Präteritum of [[helfen]]", a:["half","halfte","hilfte","geholfen"], t:"recall", c:0, e:"[[helfen, half, geholfen]]."},
{s:"Strong and irregular verbs: geben – lügen", q:"[[kennen]] or [[wissen]] for a fact you can state?", a:["wissen","kennen","either","neither"], t:"recall", c:0, e:"[[kennen]] is for people and places, [[wissen]] for facts and clauses."},
{s:"Strong and irregular verbs: geben – lügen", q:"What is the Präteritum of [[lesen]]?", a:["las","lies","lase","gelesen"], t:"recall", c:0, e:"[[lesen]] is e–a–e: [[las]], [[hat gelesen]]. The vowel comes back to [[e]] in the participle, exactly as in [[geben]] (gab, gegeben) and [[sehen]]."},
{s:"Strong and irregular verbs: geben – lügen", q:"Which line gives the three principal parts of [[kommen]] correctly?", a:["kommen – kam – ist gekommen","kommen – kam – hat gekommen","kommen – kommte – ist gekommen","kommen – kum – ist gekommen"], t:"recall", c:0, e:"[[kommen]] is o–a–o and describes arrival, so [[sein]]: [[Ich bin gekommen]]. [[gehen]] and [[laufen]] on this page behave the same way."},
{s:"Strong and irregular verbs: geben – lügen", q:"What is the Partizip II of [[genießen]], with its auxiliary?", a:["hat genossen","hat geniessen","ist genossen","hat genießt"], t:"recall", c:0, e:"[[genießen]] shortens its vowel in the past, and a short vowel is spelt [[ss]], not [[ß]]: [[genoss, genossen]] — like [[schließen → geschlossen]]."},
{s:"Strong and irregular verbs: geben – lügen", q:"[[gefallen]] means to please. In [[Der Film hat mir gefallen]], what is the subject?", a:["[[der Film]] — the thing doing the pleasing","[[mir]] — the person who liked it","both, equally","the sentence has no subject"], t:"rule", c:0, e:"German turns 'I liked the film' around: the thing is nominative, the person dative. Note also that [[gefallen]] takes [[haben]], even though plain [[fallen]] takes [[sein]]."},
{s:"Strong and irregular verbs: geben – lügen", q:"Which of these takes [[sein]] in the Perfekt?", a:["gelingen","gewinnen","genießen","geben"], t:"rule", c:0, e:"[[ist gelungen]] — succeeding is a change of state, so [[sein]]. The verb is usually impersonal: [[Es ist mir gelungen]] = I managed it."},
{s:"Strong and irregular verbs: geben – lügen", q:"Which verb takes an umlaut in the [[er/sie/es]] form?", a:["[[halten]] → [[hält]]","[[kommen]] → [[kömmt]]","[[liegen]] → [[liegt]]","[[lügen]] → [[lügt]]"], t:"rule", c:0, e:"Only stems with [[a]] or [[au]] umlaut in the present: [[hält, lässt, läuft, gefällt]]. A stem that already has [[ü]] or [[ie]] does not change at all."},
{s:"Strong and irregular verbs: geben – lügen", q:"[[Wie ___ du?]] — [[Ich heiße Anna.]]", a:["heißt","heißst","heiße","hieß"], t:"gap", c:0, e:"A stem ending in [[ß]] or [[s]] absorbs the [[du]] ending, so [[du heißt]] looks identical to [[er heißt]]. [[hieß]] is the Präteritum."},
{s:"Strong and irregular verbs: geben – lügen", q:"[[Er ___ mir hundert Euro geliehen.]]", a:["hat","ist","habt","sind"], t:"gap", c:0, e:"[[leihen]] is ei–ie–ie ([[lieh, geliehen]]) like [[bleiben]] and [[scheinen]] — but it takes a direct object, so [[haben]] rather than [[sein]]."},

{s:"Strong and irregular verbs: messen – sprechen", q:"[[er ___]] from [[nehmen]] (present)", a:["nimmt","nehmt","nahm","nimmst"], t:"gap", c:0, e:"[[nehmen, nimmt, nahm, genommen]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"[[Er ___ über den See geschwommen.]]", a:["ist","hat","war","wird"], t:"gap", c:0, e:"Movement from A to B takes [[sein]]. With a duration ([[eine Stunde geschwommen]]) [[haben]] is also used."},
{s:"Strong and irregular verbs: messen – sprechen", q:"In the perfect, [[Ich habe gehen ___]]", a:["müssen","gemusst","zu müssen","muss"], t:"gap", c:0, e:"A modal with a second verb uses the double infinitive."},
{s:"Strong and irregular verbs: messen – sprechen", q:"What is the Präteritum of [[sein]]?", a:["war","wurde","gewesen","seinte"], t:"recall", c:0, e:"[[sein]] is the most irregular verb in the language: [[ist – war – ist gewesen]]. It is one of only two verbs on this page taking [[sein]]; the other is [[schwimmen]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"What is the Partizip II of [[singen]], with its auxiliary?", a:["hat gesungen","hat gesingt","ist gesungen","hat gesangen"], t:"recall", c:0, e:"[[singen]] belongs to the i–a–u family with [[finden, trinken, springen]]: [[sang, gesungen]]. It can take an object, so [[haben]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"Which line gives the three principal parts of [[schreiben]] correctly?", a:["schreiben – schrieb – hat geschrieben","schreiben – schrieb – ist geschrieben","schreiben – schrob – hat geschrieben","schreiben – schreibte – hat geschreibt"], t:"recall", c:0, e:"ei–ie–ie, the pattern of [[bleiben]] and [[steigen]]. [[scheinen]] on this same page runs identically: [[schien, geschienen]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"[[mögen, müssen]] and [[sollen]] all build their Präteritum the same way. How?", a:["The stem loses any umlaut and takes the weak [[-te]]: [[mochte, musste, sollte]]","The stem vowel changes and no ending is added: [[mag, muss, soll]]","The umlaut is kept and [[-te]] added: [[mögte, müsste, sollte]]","They have no Präteritum and use the Perfekt instead"], t:"rule", c:0, e:"Modals are mixed verbs: changed stem plus weak endings. Beware [[müsste]] — it exists, but it is Konjunktiv II, not the past."},
{s:"Strong and irregular verbs: messen – sprechen", q:"Which verb keeps its stem vowel unchanged in the [[er/sie/es]] form?", a:["[[schreiben]] → [[schreibt]]","[[nehmen]] → [[nimmt]]","[[raten]] → [[rät]]","[[sehen]] → [[sieht]]"], t:"rule", c:0, e:"The second column of the table exists purely to flag this. [[nehmen, raten, sehen, schlafen, sprechen]] all shift; [[schreiben, singen, schneiden, rufen]] do not."},
{s:"Strong and irregular verbs: messen – sprechen", q:"[[schlafen]] and [[schlagen]] differ by one letter. Which pair of Präteritum forms is right?", a:["[[schlief]] and [[schlug]]","[[schlug]] and [[schlief]]","[[schlief]] and [[schlog]]","[[schlaf]] and [[schlag]]"], t:"rule", c:0, e:"[[schlafen]] is a–ie–a like [[raten]] (riet); [[schlagen]] is a–u–a like [[tragen]] (trug). Both return to [[a]] in the participle: [[geschlafen, geschlagen]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"[[Meine Schwester ___ sehr gut Deutsch.]]", a:["spricht","sprecht","sprechst","sprachen"], t:"gap", c:0, e:"[[sprechen]] changes [[e → i]] in the [[du]] and [[er/sie/es]] forms only: [[du sprichst, sie spricht]], but [[wir sprechen, ihr sprecht]]."},
{s:"Strong and irregular verbs: messen – sprechen", q:"[[Wir haben den ganzen Abend im Chor ___.]] (sung)", a:["gesungen","gesingt","gesangen","gesungt"], t:"gap", c:0, e:"In the i–a–u family the [[a]] belongs to the Präteritum ([[wir sangen]]) and the [[u]] to the participle ([[gesungen]]). Swapping them is the commonest slip."},

{s:"Strong and irregular verbs: springen – ziehen", q:"Partizip II of [[werden]]", a:["ist geworden","hat geworden","ist worden","hat gewordet"], t:"recall", c:0, e:"[[worden]] without [[ge-]] is the passive form only."},
{s:"Strong and irregular verbs: springen – ziehen", q:"Präteritum of [[wissen]]", a:["wusste","wisste","weißte","gewusst"], t:"recall", c:0, e:"Mixed verb: [[wissen, weiß, wusste, gewusst]]."},
{s:"Strong and irregular verbs: springen – ziehen", q:"[[Ich habe den Koffer getragen]] — why [[haben]]?", a:["[[tragen]] has a direct object","[[tragen]] is weak","[[Koffer]] is masculine","it is a mistake"], t:"recall", c:0, e:"A verb with an accusative object takes [[haben]], even when it feels like motion."},
{s:"Strong and irregular verbs: springen – ziehen", q:"Why is the auxiliary printed next to every participle?", a:["it cannot be predicted from the verb itself","it changes with the tense","it depends on the subject","it is different in each region"], t:"rule", c:0, e:"Whether a verb takes [[haben]] or [[sein]] has to be learnt with it."},
{s:"Strong and irregular verbs: springen – ziehen", q:"What is the Partizip II of [[vergessen]], with its auxiliary?", a:["hat vergessen","hat gevergessen","ist vergessen","hat vergesst"], t:"recall", c:0, e:"An inseparable prefix blocks the [[ge-]]: [[vergessen, verloren]]. The participle of [[vergessen]] is therefore identical to the infinitive."},
{s:"Strong and irregular verbs: springen – ziehen", q:"What is the Präteritum of [[ziehen]]?", a:["zog","zieh","zug","gezogen"], t:"recall", c:0, e:"[[ziehen]] joins the ie–o–o family with [[fliegen]] and [[verlieren]]: [[zog, hat gezogen]]. It takes an object, hence [[haben]]."},
{s:"Strong and irregular verbs: springen – ziehen", q:"Which line gives the three principal parts of [[sterben]] correctly?", a:["sterben – starb – ist gestorben","sterben – starb – hat gestorben","sterben – sterbte – ist gestorben","sterben – storb – ist gestorben"], t:"recall", c:0, e:"e–a–o, the pattern of [[werfen]] (warf, geworfen) and [[treffen]] (traf, getroffen) — but of those three only [[sterben]] takes [[sein]], because dying is a change of state."},
{s:"Strong and irregular verbs: springen – ziehen", q:"[[wachsen]] takes [[sein]]. Which principle puts it there?", a:["It describes a change of state","It describes movement from one place to another","It is an inseparable verb","Its Präteritum has the vowel [[u]]"], t:"rule", c:0, e:"The rule has two halves — motion, and change. Growing is not motion but it is change, so [[ist gewachsen]], alongside [[werden]] and [[sterben]]."},
{s:"Strong and irregular verbs: springen – ziehen", q:"[[verstehen]] is not in the table. How can you still be sure its Präteritum is [[verstand]]?", a:["A prefixed verb inherits the principal parts of its base verb [[stehen]]","Verbs beginning with [[ver-]] are always weak and take [[-te]]","Any verb missing from the table is regular","You cannot know without looking it up"], t:"rule", c:0, e:"That inheritance is why 74 base verbs cover several hundred compounds. Only the auxiliary can shift: [[aufstehen]] keeps [[stand, gestanden]] but takes [[sein]]."},
{s:"Strong and irregular verbs: springen – ziehen", q:"Which verb takes an umlaut in the [[er/sie/es]] form?", a:["[[waschen]] → [[wäscht]]","[[werfen]] → [[wärft]]","[[trinken]] → [[trünkt]]","[[ziehen]] → [[züht]]"], t:"rule", c:0, e:"Only [[a]] and [[au]] stems umlaut: [[wäscht, wächst, trägt]]. An [[e]] stem shifts to [[i]] instead — [[wirft, trifft, stirbt]] — and [[i]] and [[ie]] stems do not change."},
{s:"Strong and irregular verbs: springen – ziehen", q:"[[Der Preis ___ im letzten Jahr stark gestiegen.]]", a:["ist","hat","haben","sind"], t:"gap", c:0, e:"[[steigen]] is ei–ie–ie ([[stieg, gestiegen]]) and means going up, so [[sein]] — like [[springen]] and [[wachsen]] on this page. The subject is singular, so [[ist]]."},
{s:"Strong and irregular verbs: springen – ziehen", q:"[[Was hast du am Wochenende ___?]] (done)", a:["getan","getunt","getun","getat"], t:"gap", c:0, e:"[[tun]] goes [[tut – tat – hat getan]]. The participle borrows the [[a]] of the Präteritum, which is why it is not [[getun]]."},

/* ---------- XVI. Everyday German ---------- */

{s:"Greetings and politeness", q:"Which greeting is the safe default with a stranger?", a:["Guten Tag","Hallo","Servus","Tschüss"], t:"recall", c:0, e:"[[Hallo]] is informal and [[Tschüss]] is a farewell."},
{s:"Greetings and politeness", q:"What does [[Gute Besserung]] mean?", a:["get well soon","good luck","enjoy your meal","congratulations"], t:"recall", c:0, e:"Said to someone who is ill."},
{s:"Greetings and politeness", q:"What does [[Wie bitte?]] mean?", a:["pardon?","how much?","please?","how are you?"], t:"recall", c:0, e:"[[bitte]] covers please, you're welcome, here you are and pardon."},
{s:"Greetings and politeness", q:"Which is said before eating?", a:["Guten Appetit","Prost","Gern geschehen","Viel Glück"], t:"recall", c:0, e:"[[Prost]] is for drinking."},
{s:"Greetings and politeness", q:"[[___ Tag! Wie geht es Ihnen?]]", a:["Guten","Gute","Gutes","Guter"], t:"gap", c:0, e:"[[der Tag]] is masculine accusative here, so [[Guten Tag]]."},
{s:"Greetings and politeness", q:"Which greeting would you hear in Munich or Vienna but rarely in Hamburg?", a:["Grüß Gott","Guten Abend","Auf Wiedersehen","Gute Nacht"], t:"recall", c:0, e:"[[Grüß Gott]] is southern Germany and Austria. [[Servus]] is southern too, and does double duty as both hello and goodbye."},
{s:"Greetings and politeness", q:"What does [[Gern geschehen]] mean?", a:["my pleasure","see you soon","good luck","congratulations"], t:"recall", c:0, e:"It answers [[Danke]]. [[Bitte schön]] does the same job, and also means [[here you are]] when you hand something over."},
{s:"Greetings and politeness", q:"A stranger asks [[Wie geht es Ihnen?]] Which reply matches?", a:["Danke, gut. Und Ihnen?","Danke, gut. Und dir?","Danke, gut. Und Sie?","Danke, gut. Und du?"], t:"rule", c:0, e:"[[Wie geht es Ihnen?]] is dative, so the echo must be dative too: [[Und Ihnen?]] The informal pair is [[Wie geht's?]] and [[Und dir?]]"},
{s:"Greetings and politeness", q:"Which pair correctly matches a goodbye to its register?", a:["[[Auf Wiedersehen]] formal, [[Tschüss]] informal","[[Tschüss]] formal, [[Auf Wiedersehen]] informal","[[Gute Nacht]] formal, [[Bis bald]] informal","[[Servus]] formal, [[Hallo]] informal"], t:"rule", c:0, e:"[[Auf Wiedersehen]] is literally 'until seeing again'. [[Gute Nacht]] is not a general goodbye at all — it is said only when someone is going to bed."},
{s:"Greetings and politeness", q:"[[Es ___ mir leid.]] (I'm sorry)", a:["tut","tue","macht","ist"], t:"gap", c:0, e:"The apology is fixed: [[Es tut mir leid]], literally 'it does me sorrow', with the person in the dative. [[Entschuldigung]] is lighter and also covers 'excuse me'."},
{s:"Greetings and politeness", q:"A colleague has just passed her exam. [[Herzlichen ___!]]", a:["Glückwunsch","Glück","Besserung","Appetit"], t:"gap", c:0, e:"[[Herzlichen Glückwunsch]] = congratulations, said afterwards. [[Viel Glück]] is good luck beforehand, and [[Gute Besserung]] is for someone who is ill."},
{s:"Greetings and politeness", q:"You arrive for dinner at seven in the evening: [[Guten ___!]]", a:["Abend","Morgen","Tag","Nacht"], t:"gap", c:0, e:"[[Guten Abend]] from about 18:00, [[Guten Morgen]] until about 11, [[Guten Tag]] in between. Note it is [[Gute]] Nacht without the [[-n]], because [[Nacht]] is feminine."},

{s:"Getting by", q:"Which is the polite way to order?", a:["Ich hätte gern einen Kaffee","Ich will einen Kaffee","Ich habe einen Kaffee","Gib mir einen Kaffee"], t:"recall", c:0, e:"[[Ich will]] sounds blunt to the point of rudeness."},
{s:"Getting by", q:"[[Mir ist schlecht]] means…", a:["I feel sick","I am bad at this","it is bad for me","I am in a bad mood"], t:"recall", c:0, e:"Feelings take the dative: [[mir]], not [[ich]]."},
{s:"Getting by", q:"How do you ask someone to slow down?", a:["Langsamer, bitte","Schneller, bitte","Leiser, bitte","Später, bitte"], t:"recall", c:0, e:"[[langsam]] slow, comparative [[langsamer]]."},
{s:"Getting by", q:"[[Ich ___ gern einen Kaffee.]] (I'd like)", a:["hätte","habe","will","möchte gern"], t:"gap", c:0, e:"[[Ich hätte gern]] is the standard polite request."},
{s:"Getting by", q:"Why is [[Ich will einen Kaffee]] avoided when ordering?", a:["[[wollen]] states a demand and sounds blunt","it is grammatically wrong","[[Kaffee]] needs the dative","it is too formal"], t:"rule", c:0, e:"Use [[Ich hätte gern]] or [[Ich möchte]]."},
{s:"Getting by", q:"What does [[Nur schauen, danke]] mean?", a:["just looking, thanks","just a moment, thanks","just one, thanks","it looks good, thanks"], t:"recall", c:0, e:"The stock reply to a shop assistant. If you do want help, [[Ich suche …]] tells them what you are after."},
{s:"Getting by", q:"You have lost your way on foot. What do you say?", a:["Ich habe mich verlaufen","Ich habe mich verfahren","Ich bin verloren","Ich suche mich"], t:"recall", c:0, e:"[[sich verlaufen]] is specifically going astray on foot — the book flags the reflexive. Lost while driving would be [[sich verfahren]]."},
{s:"Getting by", q:"You need to ask a stranger for help. Which is right?", a:["Können Sie mir helfen?","Kannst du mir helfen?","Können Sie mich helfen?","Kannst du mich helfen?"], t:"rule", c:0, e:"Two things at once: [[Sie]] for anyone you have not been offered [[du]] by, and [[helfen]] governs the dative — [[mir]], never [[mich]]."},
{s:"Getting by", q:"[[Ich hätte gern]] is the standard polite request. What is [[hätte]]?", a:["the Konjunktiv II of [[haben]]","the Präteritum of [[haben]]","the imperative of [[haben]]","the Partizip II of [[haben]]"], t:"rule", c:0, e:"Konjunktiv II is what makes a German request polite, the way 'would' does in English. [[Ich möchte]] is the Konjunktiv II of [[mögen]] and is equally polite."},
{s:"Getting by", q:"[[___ Sie das bitte wiederholen?]] (could you)", a:["Können","Könnt","Kann","Konnten"], t:"gap", c:0, e:"Formal [[Sie]] always takes the same verb form as [[sie]] = they. [[Könnt]] belongs to [[ihr]], the plural of [[du]], so it is for a group of friends."},
{s:"Getting by", q:"[[Wie sagt man das ___ Deutsch?]] (in German)", a:["auf","in","an","zu"], t:"gap", c:0, e:"The fixed phrase is [[auf Deutsch]] — [[auf]] plus the bare language name, with no article. English 'in' is the trap here."},
{s:"Getting by", q:"In a restaurant, asking to pay: [[Die ___, bitte.]]", a:["Rechnung","Zahlen","Kosten","Preis"], t:"gap", c:0, e:"[[die Rechnung]] is the bill; [[die Zahlen]] would be the numbers and [[die Kosten]] the costs. In a bar the shorter [[Zahlen, bitte]] is more usual — and it takes no article at all."},

/* ---------- XVII. Vocabulary ---------- */

{s:"People and family", q:"Which article does [[Mädchen]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"Every noun ending in -chen is neuter, whatever it refers to."},
{s:"People and family", q:"What does [[die Geschwister]] mean?", a:["siblings","grandparents","in-laws","twins"], t:"recall", c:0, e:"Normally used in the plural."},
{s:"People and family", q:"How do you say **aunt**?", a:["die Tante","der Onkel","die Nichte","die Cousine"], t:"recall", c:0, e:"[[der Onkel]] is uncle, [[die Nichte]] niece."},
{s:"People and family", q:"[[Meine ___ heißt Anna und mein Bruder heißt Tom.]]", a:["Schwester","Bruder","Tante","Mutter"], t:"gap", c:0, e:"[[die Schwester]] — sister."},
{s:"People and family", q:"Why is [[das Mädchen]] neuter even though it means **girl**?", a:["the ending -chen makes any noun neuter","German has no feminine for children","it is a loanword","it is an exception with no reason"], t:"rule", c:0, e:"Grammatical gender is a property of the word, not of the thing."},

{s:"The body", q:"Which article does [[Auge]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"[[das Auge]], plural [[die Augen]]."},
{s:"The body", q:"What does [[der Rücken]] mean?", a:["back","stomach","shoulder","knee"], t:"recall", c:0, e:"[[der Bauch]] is the stomach."},
{s:"The body", q:"How do you say **hand**?", a:["die Hand","der Arm","der Finger","die Schulter"], t:"recall", c:0, e:"[[die Hand]], plural [[die Hände]]."},
{s:"The body", q:"[[Ich wasche mir die ___ vor dem Essen.]]", a:["Hände","Füße","Ohren","Haare"], t:"gap", c:0, e:"[[die Hand]], plural [[die Hände]]."},

{s:"Food and drink", q:"Which article does [[Brot]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"[[das Brot]]; a roll is [[das Brötchen]]."},
{s:"Food and drink", q:"What is [[der Käse]]?", a:["cheese","cake","meat","cabbage"], t:"recall", c:0, e:"Cake is [[der Kuchen]]."},
{s:"Food and drink", q:"How do you say **apple**?", a:["der Apfel","die Birne","die Kartoffel","der Saft"], t:"recall", c:0, e:"[[der Apfel]], plural [[die Äpfel]]."},
{s:"Food and drink", q:"[[Zum Frühstück esse ich ein ___ mit Butter.]]", a:["Brötchen","Bier","Fleisch","Gemüse"], t:"gap", c:0, e:"[[das Brötchen]] — bread roll."},

{s:"Animals", q:"Which article does [[Pferd]] take?", a:["das","der","die","den"], t:"recall", c:0, e:"[[das Pferd]], plural [[die Pferde]]."},
{s:"Animals", q:"What is [[der Vogel]]?", a:["bird","fox","fish","frog"], t:"recall", c:0, e:"[[der Fuchs]] is fox, [[der Frosch]] frog."},
{s:"Animals", q:"How do you say **cat**?", a:["die Katze","der Hund","die Maus","das Schaf"], t:"recall", c:0, e:"[[die Katze]] is feminine, [[der Hund]] masculine."},
{s:"Animals", q:"[[Der ___ bellt laut im Garten.]]", a:["Hund","Vogel","Fisch","Hase"], t:"gap", c:0, e:"[[bellen]] is to bark, so it must be [[der Hund]]."},

{s:"The house", q:"Which article does [[Küche]] take?", a:["die","das","der","den"], t:"recall", c:0, e:"Nouns ending in -e are usually feminine."},
{s:"The house", q:"What is [[das Fenster]]?", a:["window","door","floor","wall"], t:"recall", c:0, e:"[[die Tür]] is door."},
{s:"The house", q:"How do you say **cupboard**?", a:["der Schrank","das Regal","der Tisch","das Bett"], t:"recall", c:0, e:"[[das Regal]] is a shelf."},
{s:"The house", q:"[[Ich koche das Abendessen in der ___.]]", a:["Küche","Garage","Treppe","Decke"], t:"gap", c:0, e:"[[die Küche]] — kitchen."},

{s:"Clothing", q:"Which article does [[Hose]] take?", a:["die","das","der","den"], t:"recall", c:0, e:"[[die Hose]] is singular in German although trousers is plural in English."},
{s:"Clothing", q:"What is [[der Rock]]?", a:["skirt","coat","jacket","rock"], t:"recall", c:0, e:"A false friend: the mineral is [[der Stein]]."},
{s:"Clothing", q:"How do you say **shoe**?", a:["der Schuh","der Stiefel","die Socke","der Gürtel"], t:"recall", c:0, e:"[[der Stiefel]] is a boot."},
{s:"Clothing", q:"[[Im Winter trage ich einen warmen ___.]]", a:["Mantel","Rock","Bluse","Socke"], t:"gap", c:0, e:"[[der Mantel]] is masculine, matching [[einen warmen]]."},

{s:"Jobs and work", q:"Which article does [[Firma]] take?", a:["die","das","der","den"], t:"recall", c:0, e:"[[die Firma]], plural [[die Firmen]]."},
{s:"Jobs and work", q:"What is [[der Anwalt]]?", a:["lawyer","doctor","judge","engineer"], t:"recall", c:0, e:"[[der Richter]] is a judge."},
{s:"Jobs and work", q:"How is the feminine of [[Lehrer]] formed?", a:["Lehrerin","Lehrerine","Lehrera","Lehrere"], t:"recall", c:0, e:"Most job names add -in, plural -innen."},
{s:"Jobs and work", q:"[[Der ___ arbeitet im Krankenhaus und hilft Patienten.]]", a:["Arzt","Bäcker","Anwalt","Gärtner"], t:"gap", c:0, e:"[[der Arzt]] — doctor."},

{s:"Places in town", q:"Which article does [[Bahnhof]] take?", a:["der","die","das","den"], t:"recall", c:0, e:"[[der Bahnhof]], from [[die Bahn]] plus [[der Hof]] — the last element decides."},
{s:"Places in town", q:"What is [[die Apotheke]]?", a:["pharmacy","department store","library","post office"], t:"recall", c:0, e:"[[die Bibliothek]] is a library."},
{s:"Places in town", q:"How do you say **church**?", a:["die Kirche","das Schloss","der Dom","das Rathaus"], t:"recall", c:0, e:"[[der Dom]] is specifically a cathedral."},
{s:"Places in town", q:"[[Ich hole Geld von der ___.]]", a:["Bank","Post","Kirche","Brücke"], t:"gap", c:0, e:"[[die Bank]] — bank, and also a bench."},

{s:"Travel and transport", q:"Which article does [[Flugzeug]] take?", a:["das","der","die","den"], t:"recall", c:0, e:"[[das Flugzeug]], plural [[die Flugzeuge]]."},
{s:"Travel and transport", q:"What is [[die Fahrkarte]]?", a:["ticket","timetable","platform","journey"], t:"recall", c:0, e:"[[der Fahrplan]] is the timetable."},
{s:"Travel and transport", q:"Which verb covers travelling by car or train?", a:["fahren","gehen","fliegen","laufen"], t:"recall", c:0, e:"[[gehen]] is only on foot."},
{s:"Travel and transport", q:"[[Der ___ fährt um acht Uhr vom Bahnhof ab.]]", a:["Zug","Flug","Koffer","Hafen"], t:"gap", c:0, e:"[[der Zug]] — train."},

{s:"Nature and weather", q:"Which article does [[Sonne]] take?", a:["die","der","das","den"], t:"recall", c:0, e:"[[die Sonne]] but [[der Mond]] — the opposite of the French genders."},
{s:"Nature and weather", q:"What is [[der Baum]]?", a:["tree","branch","bush","forest"], t:"recall", c:0, e:"[[der Wald]] is a forest."},
{s:"Nature and weather", q:"How do you say **it is raining**?", a:["es regnet","es ist Regen","der Regen ist","es regnen"], t:"recall", c:0, e:"Weather uses impersonal [[es]]."},
{s:"Nature and weather", q:"[[Im Sommer scheint die ___ jeden Tag.]]", a:["Sonne","Mond","Wolke","Regen"], t:"gap", c:0, e:"[[die Sonne]] — sun. [[scheinen]] is to shine."},

{s:"Time and the calendar", q:"Which article do the days of the week take?", a:["der","die","das","they vary"], t:"recall", c:0, e:"Days, months and seasons are all masculine."},
{s:"Time and the calendar", q:"What is [[das Wochenende]]?", a:["weekend","weekday","fortnight","week"], t:"recall", c:0, e:"[[die Woche]] plus [[das Ende]]."},
{s:"Time and the calendar", q:"How do you say **in May**?", a:["im Mai","am Mai","in Mai","um Mai"], t:"recall", c:0, e:"[[in dem]] contracts to [[im]] for months and seasons."},
{s:"Time and the calendar", q:"[[Am ___ arbeite ich nicht, sondern ruhe mich aus.]]", a:["Wochenende","Morgen","Jahr","Kalender"], t:"gap", c:0, e:"[[das Wochenende]] — weekend."},

{s:"School and study", q:"Which article does [[Prüfung]] take?", a:["die","das","der","den"], t:"recall", c:0, e:"Every noun ending in -ung is feminine."},
{s:"School and study", q:"What are [[die Ferien]]?", a:["school holidays","lessons","exams","terms"], t:"recall", c:0, e:"Plural only. Time off work is [[der Urlaub]]."},
{s:"School and study", q:"How do you say **exercise book**?", a:["das Heft","das Buch","die Tafel","der Stift"], t:"recall", c:0, e:"[[das Buch]] is a book."},
{s:"School and study", q:"[[Der Lehrer schreibt das Wort an die ___.]]", a:["Tafel","Kreide","Pause","Note"], t:"gap", c:0, e:"[[die Tafel]] — board."},

{s:"Technology and media", q:"Which article does [[Handy]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"[[das Handy]] means a mobile phone, not something convenient."},
{s:"Technology and media", q:"What are [[die Nachrichten]]?", a:["the news","the messages app","the settings","the headlines of a paper"], t:"recall", c:0, e:"Singular [[die Nachricht]] is a single message."},
{s:"Technology and media", q:"How do you say **screen**?", a:["der Bildschirm","die Tastatur","der Drucker","das Kabel"], t:"recall", c:0, e:"[[die Tastatur]] is the keyboard."},
{s:"Technology and media", q:"[[Mein ___ hat keinen Akku mehr.]]", a:["Handy","Kabel","Foto","Passwort"], t:"gap", c:0, e:"[[das Handy]] — mobile phone."},

{s:"Money and shopping", q:"Which article does [[Geld]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"[[das Geld]], and it is uncountable."},
{s:"Money and shopping", q:"What is [[die Rechnung]]?", a:["bill","receipt","discount","change"], t:"recall", c:0, e:"[[die Quittung]] is the receipt."},
{s:"Money and shopping", q:"Which noun exists only in the plural?", a:["die Kosten","das Konto","der Preis","die Münze"], t:"recall", c:0, e:"[[die Kosten]] and [[die Schulden]] have no singular."},
{s:"Money and shopping", q:"[[Die ___, bitte!]] — asking to pay in a restaurant", a:["Rechnung","Quittung","Kasse","Münze"], t:"gap", c:0, e:"[[die Rechnung]] is the bill; [[die Quittung]] is the receipt."},

{s:"Health and illness", q:"Which article does [[Krankenhaus]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"The last element [[das Haus]] decides the gender."},
{s:"Health and illness", q:"What is [[das Rezept]]?", a:["prescription","receipt","treatment","tablet"], t:"recall", c:0, e:"It also means a cooking recipe."},
{s:"Health and illness", q:"How do you say **I have a headache**?", a:["Ich habe Kopfschmerzen","Ich habe Kopfschmerz","Mein Kopf hat Schmerz","Ich bin Kopfschmerz"], t:"recall", c:0, e:"Aches are plural. Alternatively [[Mir tut der Kopf weh]]."},
{s:"Health and illness", q:"[[Ich nehme eine ___ gegen Kopfschmerzen.]]", a:["Tablette","Spritze","Wunde","Impfung"], t:"gap", c:0, e:"[[die Tablette]] — tablet."},

{s:"Countries and languages", q:"Which country takes an article?", a:["die Schweiz","Deutschland","Frankreich","Italien"], t:"recall", c:0, e:"Also [[die Türkei]], [[die Niederlande]], [[die USA]]."},
{s:"Countries and languages", q:"How do you say **to Switzerland**?", a:["in die Schweiz","nach Schweiz","nach der Schweiz","zu Schweiz"], t:"recall", c:0, e:"Countries with an article take [[in]] plus the accusative for movement."},
{s:"Countries and languages", q:"What is the language of [[Österreich]]?", a:["Deutsch","Österreichisch","Ungarisch","Schweizerisch"], t:"recall", c:0, e:"Austria and much of Switzerland are German-speaking."},
{s:"Countries and languages", q:"[[Wien liegt in ___.]]", a:["Österreich","der Schweiz","Ungarn","Polen"], t:"gap", c:0, e:"Vienna is in Austria, which takes no article."},

{s:"Colours, shapes and materials", q:"Which colour never takes an adjective ending?", a:["rosa","rot","grün","blau"], t:"recall", c:0, e:"[[rosa]], [[lila]], [[orange]] and [[beige]] are invariable: [[ein rosa Kleid]]."},
{s:"Colours, shapes and materials", q:"What colour is [[gelb]]?", a:["yellow","green","grey","gold"], t:"recall", c:0, e:"[[grün]] is green, [[grau]] grey."},
{s:"Colours, shapes and materials", q:"Which article does [[Holz]] take?", a:["das","die","der","den"], t:"recall", c:0, e:"[[das Holz]] — wood."},
{s:"Colours, shapes and materials", q:"[[Der Himmel ist heute ___.]]", a:["blau","blaue","blauer","blaues"], t:"gap", c:0, e:"After [[sein]] the adjective is predicative and takes no ending."},

{s:"Common adjectives", q:"What is the opposite of [[teuer]]?", a:["billig","reich","schwer","voll"], t:"recall", c:0, e:"[[teuer]] expensive, [[billig]] cheap."},
{s:"Common adjectives", q:"[[schwer]] can mean…", a:["both heavy and difficult","only heavy","only difficult","only serious"], t:"recall", c:0, e:"Its opposite [[leicht]] likewise means both light and easy."},
{s:"Common adjectives", q:"What is the opposite of [[laut]]?", a:["leise","langsam","dunkel","leer"], t:"recall", c:0, e:"[[laut]] loud, [[leise]] quiet."},
{s:"Common adjectives", q:"[[Der Koffer ist zu ___, ich kann ihn nicht tragen.]]", a:["schwer","leicht","teuer","voll"], t:"gap", c:0, e:"[[schwer]] means both heavy and difficult."},

{s:"Everyday verbs", q:"Which of these is irregular?", a:["nehmen","machen","spielen","kaufen"], t:"recall", c:0, e:"[[nehmen, nimmt, nahm, genommen]]. The others are weak."},
{s:"Everyday verbs", q:"Which verb do you use for knowing a fact?", a:["wissen","kennen","können","verstehen"], t:"recall", c:0, e:"[[kennen]] is for people and places you are acquainted with."},
{s:"Everyday verbs", q:"What is the difference between [[wohnen]] and [[leben]]?", a:["wohnen is to reside, leben is to be alive","they are identical","wohnen is temporary only","leben is only for animals"], t:"rule", c:0, e:"[[Ich wohne in Berlin]] but [[Er lebt noch]]."},
{s:"Everyday verbs", q:"[[Ich ___ jeden Morgen einen Kaffee.]]", a:["trinke","esse","fahre","lese"], t:"gap", c:0, e:"[[trinken]] — to drink."},
{s:"Everyday verbs", q:"Why is [[nehmen]] listed as irregular?", a:["its stem changes: nimmt, nahm, genommen","it takes [[sein]]","it is reflexive","it has a separable prefix"], t:"rule", c:0, e:"Irregular verbs change the stem vowel rather than adding [[-t-]]."},

{s:"Verbs of movement, speech and thought", q:"Which is the regular partner of [[liegen]]?", a:["legen","lügen","leihen","lassen"], t:"recall", c:0, e:"[[legen]] to lay something down, [[liegen]] to be lying."},
{s:"Verbs of movement, speech and thought", q:"Which of these is irregular?", a:["schließen","öffnen","üben","prüfen"], t:"recall", c:0, e:"[[schließen, schloss, geschlossen]]."},
{s:"Verbs of movement, speech and thought", q:"What does [[empfehlen]] mean?", a:["to recommend","to receive","to feel","to complain"], t:"recall", c:0, e:"[[empfehlen, empfiehlt, empfahl, empfohlen]] — irregular."},
{s:"Verbs of movement, speech and thought", q:"[[Bitte ___ die Tür, es ist kalt!]] (close)", a:["schließ","schließen","geschlossen","schließt"], t:"gap", c:0, e:"The [[du]] imperative is the bare stem: [[schließ]] (also [[schließe]])."}

];
